window.D2=[{"n": 24, "t": "فرامل ABS بتمنع العربية من الانزلاق ازاي؟", "e": "How ABS Brakes Prevent Skidding", "h": "لو دست فرامل جامد، العجل بيفضل يلف شوية بدل ما يتقفل.", "sc": [["الدواسة اللي بتنبض", "لو داست فرامل بقوة على طريق مبلول، ممكن تحس بنبض أو اهتزاز تحت رجلك، والعربية بتفضل ماشية في خط مستقيم وبتوقف. ده نظام ABS شغال. هدفه حاجة واحدة: يمنع العجل من إنه يتقفل وانت بتفرمل."], ["مشكلة قفل العجل", "لو عجلة اتقفلت تماما وهي لسه ماشية على الأرض، بتنزلق بدل ما تدور. ومع الانزلاق بتفقد تماسك أكتر، وبتفقد القدرة على التوجيه. يعني تعمل الدريكسيون وتشوف العربية مكملة في نفس الاتجاه."], ["حساس على كل عجلة", "النظام فيه حساس عند كل عجلة بيقيس سرعة دورانها باستمرار. ده بيبعت إشارات لوحدة تحكم إلكترونية، بتقارن سرعة العجلات ببعضها وبسرعة العربية التقريبية."], ["لما عجلة بتقرب تتقفل", "لو وحدة التحكم لاحظت إن عجلة بتبطأ بسرعة أكتر من الباقي، يعني على وشك الانزلاق، بتتصرف فورا. بتخفف ضغط الفرامل عليها لجزء من الثانية، فالعجلة تلف تاني."], ["صمامات تضغط وتفلت", "في الدايرة الهيدروليكية للفرامل فيه صمامات صغيرة بتفتح وتقفل بسرعة. لما تفتح، الضغط بيقل على عجلة. ولما تقفل بيرجع. وبتعمل كده مرات كتير في الثانية، فتحافظ على العجلة قرب حد التماسك الأقصى."], ["ليه النبض في الدواسة", "النبض اللي بتحسه في الدواسة هو تأثير الصمامات وهي بتغير الضغط بسرعة. ده طبيعي، وده معناه إن النظام شغال. المهم إنك ما ترفعش رجلك. اضغط بقوة وكمل، وسيب النظام يشتغل."], ["التوجيه أثناء الفرملة", "بسبب إن العجل لسه بيلف، ممكن تحرك الدريكسيون وتتفادى عائق وانت بتفرمل. ده بيفرق جدا في الطوارئ. من غير ABS، لو قفلت العجل كان لازم ترفع رجلك الأول عشان تقدر توجه."], ["مش بيقصر مسافة دايما", "ABS مش معناه إن المسافة هتقل دايما. على الطرق الجافة المسافة قريبة، وعلى الأرض الرملية أو الثلج ممكن تطلع أطول شوية. هدفه الأساسي التحكم مش تقصير المسافة. وبرضه مش بيغني عن إنك تسوق بحذر وتحافظ على مسافة أمان."], ["الفرق في الفرامل القديمة", "قبل ABS، السواقين كانوا بيتعلموا طريقة الفرملة المتقطعة بإنهم يدوسوا ويفلتوا بسرعة بإيديهم. النظام الإلكتروني بيعمل ده أسرع وأدق بكتير من أي سواق، ولكل عجلة لوحدها."], ["ليه التزحلق خطر", "لما العجلة تقفل وتنزلق على الأرض، العربية بتفقد قدرة التوجيه. العجلة اللي بتلف بتمسك الأرض أحسن من اللي بتنزلق، فالنظام بيحاول يحافظ على العجل لافة بالرغم من الفرملة الشديدة."], ["سرعة الحساب", "النظام بيقرأ سرعة كل عجلة عشرات المرات في الثانية. ولو لقى عجلة بتبطأ بشكل أسرع من الباقي، بيعتبرها بتقفل ويقلل ضغط الفرامل عليها لحظيا، وبعدين يزوده تاني."], ["مع أنواع الطرق", "على الأرض الزلقة زي المطر أو الرمل، الـ ABS بيعمل بنفس الفكرة لكن بحدود مختلفة. فهو بيساعدك تحتفظ بالتحكم، لكن مسافة التوقف ممكن تكون أطول حسب الطريق. فالسرعة المناسبة لحالة الطريق أهم."], ["إيه المطلوب منك", "في حالة الفرملة الطارئة، اضغط الفرامل بقوة وثبّت رجلك ووجه العربية. وما ترفعش رجلك لما تحس النبض. والنبض معناه إن النظام شغال. ويفضل تتأكد من تعليمات عربيتك."], ["بدون الـ ABS", "من غير ABS، لو دوست فرامل بقوة، العجل ممكن يقفل وتنزلق العربية. السواق الخبير كان بيعمل فرملة متقطعة بنفسه عشان يتجنب ده. الـ ABS بيعمل نفس الفكرة بشكل أسرع وأدق بكتير من أي سواق."], ["بقية الأنظمة", "الحساسات اللي بتقيس سرعة العجل بتتستخدم كمان في أنظمة تانية، زي التحكم في الثبات. نظام الثبات بيفرمل عجل معين لو العربية بدأت تنحرف. فالـ ABS أساس لأنظمة أمان أحدث."], ["تنبيه المؤشر", "لو لمبة الـ ABS ظهرت على لوحة العدادات وفضلت منورة، ده معناه إن النظام فيه عطل. الفرامل العادية غالبا هتفضل شغالة، لكن من غير الحماية. المفروض تفحص العربية عند مختص."], ["الاسترخاء في القيادة", "الـ ABS ما بيدّيش حرية القيادة بسرعة أكبر. هو شبكة أمان، مش بديل للحذر. حافظ على مسافة أمان كافية، خصوصا في الجو السيئ."], ["الخلاصة", "الخلاصة: حساسات بتراقب دوران العجل، ووحدة تحكم تكتشف إن عجلة على وشك تتقفل، وصمامات تفلت الضغط وترجعه بسرعة. فالعجل يفضل يدور، وتفضل متحكم في العربية. لو حسيت النبض، اضغط بقوة وكمل."]], "f": ["ABS يمنع قفل العجل.", "بيعمل ضغط وفلت متكرر.", "يسمح بالتوجيه أثناء الفرملة."], "c": "مواصلات وأمان", "dur": "4 دقايق", "tot": 229, "st": [0, 15, 28, 38, 50, 63, 76, 90, 106, 117, 129, 141, 155, 166, 181, 193, 206, 216], "w": 535}, {"n": 25, "t": "قفل الوجه (Face ID) بيعرفك ازاي؟", "e": "How Face Unlock Recognizes You", "h": "التليفون بيبني خريطة ثلاثية الأبعاد لوشك.", "sc": [["قفل من غير مفتاح", "بتبص للتليفون، ومن غير ما تلمسه ولا تقول حاجة، بيتفتح. مش بيعتمد على صورة وش بس، فبعض الأنظمة بتبني خريطة ثلاثية الأبعاد لوشك. إزاي؟ تعالى نشوف الفكرة، مع التنبيه إن مش كل التليفونات بتستخدم نفس الطريقة."], ["وش بأبعاد", "الوش مش مسطح: فيه أنف بارز وعينين غايرة وخدود. الأنظمة المعتمدة على العمق مش بتعتمد على صورة عادية بس، بتحاول تفهم الشكل الثلاثي الأبعاد. ده بيخليها أصعب في الخداع بصورة مطبوعة."], ["نقط ضوء تحت الأحمر", "في بعض الأنظمة فيه جهاز صغير بيطلع آلاف النقط من الضوء تحت الأحمر على وشك. النقط دي مش بنشوفها بعيننا. لما بتقع النقط على سطح مش مستوي، بتتوزع بشكل مختلف حسب العمق والشكل."], ["كاميرا تحت حمراء", "كاميرا مخصوصة بتلتقط صورة للنقط دي. من المسافات بين النقط وشكل توزيعها، البرنامج بيحسب عمق كل نقطة، وبيعمل خريطة بعد للوش. وده بيشتغل حتى في الظلام لأنه بيعتمد على الضوء تحت الأحمر مش على إضاءة الغرفة."], ["خريطة رقمية", "الخريطة بتتحول لقالب رقمي: مجموعة أرقام بتمثل خصائص الوش. القالب ده بيتخزن مشفر في مكان آمن في التليفون، وما بيتبعتش لأي مكان. ومعظم الأنظمة بتتعلم من وشك مع الوقت لتتأقلم."], ["المقارنة", "كل مرة تبص للتليفون بيعمل خريطة جديدة، ويقارنها بالمخزنة. لو التشابه كفاية، يفتح. ولو فيه تغيير بسيط زي لحية أو نضارة أو قبعة، النظام في الغالب بيتعامل. وفي تغيير كبير ممكن يطلب رقم سري."], ["التأكد إنك بتبص", "في بعض الأنظمة فيه شرط إن عينيك تكون مفتوحة وبتبص للشاشة، عشان ما يفتحش لو حد رفع التليفون على وشك وانت نايم. ده من إجراءات الأمان، وبيتم تفعيله أو إيقافه من الإعدادات في بعض الأجهزة."], ["أنواع تانية", "مش كل التليفونات فيها حساس عمق. بعضها بيستخدم الكاميرا الأمامية العادية وبرنامج ذكاء اصطناعي يتعرف على الوش من صورة عادية. الطريقة دي أبسط، لكنها غالبا أقل أمانا من الأنظمة المعتمدة على العمق. وبتختلف الشركات في مستوى الأمان."], ["الخصوصية", "بيانات الوش حساسة، فبتتخزن مشفرة وجوه الجهاز. وبرضه ما بتتشاركش مع التطبيقات، التطبيق بياخد إجابة نعم أو لأ بس. ومع ذلك مهم تفعل رقم سري قوي كمان، وتحدث الجهاز بانتظام."], ["الذكاء الاصطناعي في التعرف", "الأنظمة دي بتستخدم شبكات عصبية متدربة على ملايين الصور عشان تتعلم إيه اللي بيميز وش عن وش. الشبكة ما بتحفظش وش معين، بتتعلم تطلع أرقام تميز بين الوجوه. وبعد كده تقارن الأرقام بتاعتك بالمخزنة."], ["ليه ما بتتخدعش بصورة", "النظام اللي بيقيس العمق بيلاقي إن صورة مسطحة على ورقة أو شاشة ملهاش عمق زي الوش الحقيقي، فبيرفضها. وفيه أنظمة تتحقق إن العين مفتوحة أو الوش بيتحرك طبيعي. لكن مفيش نظام مضمون بنسبة مئة في المية."], ["العوامل اللي بتأثر", "الإضاءة الشديدة والزاوية والمسافة وتغطية الوش بالكامل ممكن تقلل الدقة. والتغيرات الكبيرة في الشكل ممكن تحتاج النظام يعيد التعلم. لو التليفون مش بيتعرف عليك، حاول تقرب وتبص مباشرة للكاميرا."], ["الجانب الأخلاقي", "التعرف على الوجه بيثير أسئلة عن الخصوصية، خصوصا لو استخدم في الأماكن العامة. فتفتيح التليفون بوشك على جهازك الخاص حاجة مختلفة عن أنظمة المراقبة. وده موضوع بيتناقش وبتتحط له قوانين في دول كتير."], ["الإعداد", "وقت التسجيل، التليفون بيطلب منك تحرك راسك في دايرة. ده عشان يجمع صورة للوش من زوايا مختلفة، ويبني القالب. وبعد كده بيتحسن مع الاستخدام."], ["التوائم والتشابه", "الوجوه المتشابهة جدا زي التوائم ممكن تخدع النظام أحيانا، لأن القالبين قريبين جدا. شركات بتذكر ده في وثائقها. ولو ده فارق عندك، ممكن تعتمد على رقم سري بدل الوش."], ["الأطفال", "وجوه الأطفال بتتغير بسرعة مع النمو، فالأنظمة ممكن تلاقي صعوبة في التمييز بينهم. وبرضه الشركات بتوصي أحيانا بعدم الاعتماد على الوش في الحالات اللي دقتها فيها أقل."], ["التحديثات", "الشركات بتحدث الأنظمة دي بالبرمجيات عشان تحسن الدقة وتسد ثغرات. لذلك تحديث التليفون بانتظام جزء من الأمان."], ["الخلاصة", "الخلاصة: في بعض الأنظمة، ضوء تحت أحمر ينقّط الوش، وكاميرا تقيس عمق النقط، فيتحول الوش لخريطة رقمية مشفرة، وكل مرة بتقارن. والأنظمة بتختلف من جهاز لجهاز، فما تفترضش إن كل تليفون بيشتغل بنفس الطريقة."]], "f": ["بعض الأنظمة تعتمد على العمق.", "القالب الرقمي مخزن مشفر.", "مش كل التليفونات بنفس الطريقة."], "c": "أمان وحماية", "dur": "4 دقايق", "tot": 242, "st": [0, 15, 29, 43, 58, 71, 86, 101, 117, 129, 144, 159, 172, 186, 196, 209, 220, 228], "w": 565}, {"n": 26, "t": "السد العالي بيعمل كهربا من الميّه ازاي؟", "e": "How a Hydroelectric Dam Makes Power", "h": "المية اللي واقفة ورا السد فيها طاقة كبيرة.", "sc": [["جدار بيولد كهربا", "السد العالي في أسوان بيحجز كمية ضخمة من مية النيل. ومش بس بيحميها، بيستخدم وزنها وسقوطها عشان يولد كهربا. الفكرة قديمة ومنطقية: المية اللي في مكان عالي معاها طاقة، ولما تنزل بتطلعها. السد بيحول الطاقة دي لكهربا."], ["طاقة الوضع", "أي حاجة في مكان عالي معاها طاقة مخزنة اسمها طاقة الوضع. حجر على قمة جبل، ومية في بحيرة ورا سد. كل ما الارتفاع أكبر وكل ما الكمية أكتر، الطاقة أكبر. السد بيرفع منسوب المية، فبيبقى فيه فرق ارتفاع بين المية وراه والمية قدامه."], ["الأنابيب", "جزء من المية بيتسحب من بحيرة السد لأنابيب كبيرة اسمها مواسير الضغط. بتنزل فيها بسرعة كبيرة وضغط عالي بسبب الارتفاع. كل ما الفرق في الارتفاع أكبر، الضغط والسرعة أعلى."], ["التوربين", "المية السريعة بتخبط على ريش توربين كبير فبتلفه. التوربينات المائية بتتصمم حسب ظروف الارتفاع والتدفق. وبتلف بسرعة محسوبة عشان تعطي كهربا بالتردد المطلوب."], ["المولد", "التوربين متوصل بعمود لمولد كهربي. جوه المولد مغناطيس بيلف جوه ملفات سلك. لما المغناطيس يتحرك قدام الملفات، بيتولد فيها تيار كهربائي بالحث. كل ما لف أسرع وكان المجال أقوى، زادت الكهربا."], ["المحولات والشبكة", "الكهربا الخارجة من المولد بتروح لمحولات بترفع الجهد عشان تتنقل لمسافات طويلة بخسارة أقل. بعدين بتتنقل بأسلاك الضغط العالي للمدن، وهناك محولات تانية بتخفضها لجهد البيوت."], ["بعد التوربين", "المية اللي لفت التوربين مش بتتهدر ولا بتتحرق. بتخرج من تحت وتكمل في مجرى النهر. ولهذا طاقة المية بتعتبر متجددة: الشمس بتبخر المية، والمطر بيرجعها فتتجدد الدورة، والمية نفسها ما بتتستهلكش في التوليد."], ["التحكم في الكهربا", "فيه ميزة مهمة للسدود: تقدر تتحكم في كمية المية المستخدمة بسرعة، فتتحكم في كمية الكهربا. لما الطلب يزيد على الكهربا، بنفتح ماسورة أكتر. ده بيخلي السدود مفيدة في موازنة الشبكة."], ["أكتر من فايدة", "السدود مش للكهربا بس. بتتحكم في الفيضانات وبتخزن المية للزراعة والشرب في فترات الجفاف. وفي نفس الوقت ليها تأثيرات بيئية لازم تتدرس، زي تغيير تدفق الرواسب في النهر. فالقرار بتاعها بيحتاج توازن."], ["البحيرة كبطارية", "ممكن نعتبر البحيرة خلف السد زي بطارية ضخمة. المية فيها طاقة مخزنة بسبب ارتفاعها. وقت ما نحتاج الكهربا نفتح المواسير، ولما ما نحتاجش نقللها. وبعض المحطات بتضخ المية لفوق وقت الكهربا الرخيصة وتستخدمها بعدين."], ["الفاقد", "مش كل طاقة المية بتتحول لكهربا. جزء بيضيع في الاحتكاك داخل المواسير وفي حرارة التوربين والمولد. التصميمات الجيدة بتقلل الفاقد دا لكن مفيش حاجة بتبقى مئة في المية."], ["اختلاف المنسوب", "منسوب المية خلف السد بيتغير حسب الفصول وكمية المية الواردة. وده بيغير الارتفاع الفعال ومن ثم القوة. فالمسؤولين بيحسبوا كمية المية المسموح بتصريفها حسب الاحتياج للشرب والزراعة والكهربا."], ["السد العالي كمثال", "السد العالي في أسوان من أشهر المشروعات في مصر، وبيخدم الري وتخزين المية وتوليد الكهربا. ومشروعات زيه ليها دور اقتصادي كبير، لكن مهم برضه مراجعة آثارها البيئية والاجتماعية بشكل علمي."], ["الفيضان", "النهر بيجيله ماء أكتر في بعض السنين وأقل في غيرها. السد بيخزن الزيادة ويقلل الفيضانات المدمرة، ويعوض في سنين الجفاف. ده دور مش مرتبط بالكهربا لكنه من أهم أسباب بناء السدود."], ["التحكم والبوابات", "السد فيه بوابات تتحكم في كمية المية الخارجة. وفي حالات الفيضان العالي، فيه مفيض لتصريف الزيادة بأمان. وكل ده بيتراقب بمنظومة قياس مستمرة."], ["الطاقة المتجددة", "لأن المية بتتجدد بدورة الطبيعة، الكهرومائية بتتصنف متجددة. وبتكون تكلفة تشغيلها منخفضة بعد الإنشاء. لكن الإنشاء نفسه مكلف وطويل."], ["الأثر البيئي", "السدود بتغير النظام البيئي للنهر. الرواسب بتترسب في البحيرة بدل ما توصل للأراضي في الأسفل، وبتتأثر الأسماك. فبيتم دراسة الآثار ومحاولة تقليلها قبل وبعد التنفيذ."], ["الخلاصة", "الخلاصة: مية محجوزة في مكان عالي، بتنزل في مواسير بسرعة، بتلف توربين، والتوربين يلف مولد فتتولد كهربا، والمية تكمل في النهر. السد بيحول طاقة وضع المية لطاقة كهربية، من غير ما يحرق وقود."]], "f": ["السدود تحول طاقة وضع الميّه لحركة ثم كهربا.", "التوربين يلف المولد.", "الفرق في الارتفاع مهم."], "c": "طاقة", "dur": "4 دقايق", "tot": 229, "st": [0, 16, 34, 47, 57, 70, 81, 95, 108, 122, 136, 148, 160, 173, 186, 196, 204, 215], "w": 535}, {"n": 27, "t": "طابعة 3D بتعمل حاجة من غير قالب ازاي؟", "e": "How a 3D Printer Builds Objects", "h": "بتبني الحاجة طبقة طبقة.", "sc": [["طباعة بتعمل شكل", "بتبعت ملف للطابعة، وبعد ساعتين تلاقي قطعة بلاستيك بشكل متخيل: مجسم، قطعة غيار، لعبة. من غير قالب ولا إزميل. الفكرة غريبة: بدل ما تقطع حاجة من كتلة، بتبنيها من الأول طبقة بعد طبقة. اسمها التصنيع بالإضافة."], ["الموديل في الكمبيوتر", "كل حاجة تبدأ بموديل ثلاثي الأبعاد على الكمبيوتر. تقدر ترسمه بنفسك في برنامج تصميم أو تحمله جاهز. الموديل ده بيمثل شكل القطعة من كل الجهات، بطول وعرض وارتفاع."], ["التقطيع", "الطابعة مش بتفهم الموديل كله مرة واحدة. فيه برنامج اسمه برنامج التقطيع بيقطع الموديل أفقيا لطبقات رفيعة جدا، سمك كل طبقة جزء من المليمتر. وبيحسب مسار رأس الطباعة لكل طبقة، وبيطلع ملف تعليمات للطابعة."], ["الخيط البلاستيك", "أشهر نوع من الطابعات بيستخدم خيط بلاستيك ملفوف على بكرة. الخيط بيدخل في رأس الطباعة، وهناك بيتسخن لحد ما يلين ويبقى شبه المعجون. وبعد كده بيتضغط ويخرج من فتحة صغيرة جدا."], ["رسم الطبقة الأولى", "الرأس بيتحرك فوق سطح الطباعة في اتجاهين، حسب مسار الطبقة الأولى، وهو بيطلع الخيط الليّن. البلاستيك بيلزق في السطح وبيبرد بسرعة ويجمد. الطبقة الأولى هي الأساس، ولازم تلزق كويس."], ["طبقة فوق طبقة", "بعد الطبقة الأولى، الطابعة بترفع الرأس أو تنزل السطح بمقدار سمك طبقة، وترسم التانية فوقها. البلاستيك الساخن بيلزق في الطبقة اللي تحته. وتتكرر العملية مئات المرات لحد ما القطعة تكمل."], ["الدعامات", "لو القطعة فيها جزء معلق في الهوا، زي ذراع ممدود، الطابعة مش هتقدر ترسم على الفراغ. فبتبني دعامات مؤقتة تحته. بعد الطباعة بنشيل الدعامات ونصقل الأماكن. وده جزء من تخطيط التصميم."], ["أنواع تانية", "فيه طابعات بتستخدم سائل راتنج بيتحول لجامد بتعرضه لضوء ليزر أو ضوء مخصوص، وبتطلع تفاصيل أدق. وفيه طابعات بتستخدم مسحوق بتلحمه بالليزر وبتطبع معادن. وكل نوع ليه استخدامه وتكلفته."], ["استخدامات", "الطباعة ثلاثية الأبعاد بتتستخدم في النماذج الأولية، وقطع الغيار، والأطراف الصناعية، وطب الأسنان، والهندسة. ميزتها إنك تعمل قطعة واحدة مخصوصة من غير قالب مكلف. وعيوبها إنها أبطأ من الإنتاج الضخم."], ["اختيار المادة", "أشهر الخامات البلاستيك زي PLA وPETG. الـ PLA سهل الطباعة وبينتج تفاصيل كويسة. الـ PETG أقوى وأكتر تحملا للحرارة. وفيه مواد مرنة وأخرى مقواة. لازم تختار المادة حسب استخدام القطعة."], ["المعايرة", "الطابعة محتاجة ضبط عشان النتيجة تطلع كويسة: السطح لازم يكون مستوي، وحرارة الفوهة مناسبة للمادة، وسرعة الطباعة معقولة. أي خلل بسيط ممكن يطلع قطعة بعيوب زي الخيوط الزايدة أو عدم الالتصاق."], ["نسبة التعبئة", "القطعة مش لازم تكون مصمتة بالكامل. البرنامج بيقدر يطبع الجزء الداخلي بشبكة من خطوط بنسبة معينة. ده بيوفر خامة ووقت، وبيدي قوة كفاية لمعظم الاستخدامات. وتزود النسبة لو القطعة محتاجة قوة أكبر."], ["بعد الطباعة", "القطعة ممكن تحتاج تنضيف وتصنفر وطلاء. ومع الراتنج بتحتاج غسيل وتعريض لضوء لتتصلب. وبعد كده القطعة جاهزة للاستخدام. وكل التفاصيل دي بتختلف حسب نوع الطابعة."], ["التصميم للطباعة", "مش كل شكل ينفع يتطبع بسهولة. التصميم الجيد بياخد في الاعتبار اتجاه الطباعة، وزوايا التدلي، وسمك الجدران. تعديل بسيط في التصميم ممكن يقلل الدعامات ويحسن القوة."], ["البرمجيات المفتوحة", "فيه مواقع كتير فيها نماذج مجانية جاهزة للطباعة. وفيه برامج مجانية للتصميم والتقطيع. ده بيخلي دخول المجال أرخص وأسهل لهواة وطلبة ومهندسين."], ["الأمان", "الفوهة سخنة جدا والبلاستيك الساخن ممكن يحرق، فلا تلمس الأجزاء أثناء التشغيل. ويفضل تهوية الغرفة لأن بعض المواد بتطلع أبخرة. اتبع تعليمات المصنع."], ["المستقبل", "بتتطور تقنيات الطباعة لتطبع مواد أكتر، وحتى أجزاء معقدة بالمعادن، وفي بعض التجارب بيوت. لكن الاستخدام الواسع في كل حاجة لسه محدود بالسرعة والتكلفة."], ["الخلاصة", "الخلاصة: موديل ثلاثي الأبعاد، يتقطع لطبقات، والطابعة تسخن مادة وترسم كل طبقة فوق اللي قبلها لحد ما القطعة تكمل. بناء من الصفر بدل النحت من الكتلة، وده بيفتح باب لتصميمات مكانتش ممكنة قبل كده."]], "f": ["طباعة بالإضافة طبقة فوق طبقة.", "خيط بلاستيك يسخن ويطلع.", "فيه أنواع راتنج."], "c": "تصنيع", "dur": "4 دقايق", "tot": 225, "st": [0, 15, 27, 42, 55, 68, 81, 94, 106, 119, 132, 145, 159, 170, 181, 190, 200, 210], "w": 525}, {"n": 28, "t": "الصاروخ بيطلع الفضاء ازاي؟", "e": "How a Rocket Reaches Orbit", "h": "الصاروخ مش بس بيطلع لفوق، هو لازم يجري جنب كمان.", "sc": [["أبعد من السما", "الطيارة بتطلع لحد ارتفاع حوالي عشرة كيلومترات وتفضل هناك. والصاروخ بيوصل لمئات الكيلومترات ويفضل يلف حوالين الأرض بدل ما يقع. الفرق مش بس في الارتفاع. هو في حاجة أهم: السرعة الجانبية. تعالى نفهم ليه."], ["الدفع في الفضاء", "الصاروخ بيطلع غازات ساخنة من الخلف بسرعة كبيرة. وبقانون نيوتن الثالث، الغازات اللي بتتدفع لتحت بتدفع الصاروخ لفوق. الفكرة بتشتغل حتى في الفراغ لأن الصاروخ مش بيدفع الهوا، بيدفع الغازات اللي بيحملها معاه."], ["ليه الوقود ومادة الأكسدة", "الاحتراق محتاج وقود وأكسجين. في الجو الأرضي، الطيارة بتاخد الأكسجين من الهوا. الصاروخ بيروح لمكان مفيهوش هوا، فبيشيل الأكسجين معاه في خزان أو بشكل مادة مؤكسدة. عشان كده معظم وزن الصاروخ وقود ومؤكسد."], ["ليه مش كفاية نطلع لفوق", "لو الصاروخ طلع لفوق بس واتوقف، هيقع تاني بفعل الجاذبية. عشان يفضل في المدار، لازم يتحرك أفقيا بسرعة كبيرة جدا حوالين الأرض، حوالي سبعة كيلومترات وتمن مئة متر في الثانية للمدارات المنخفضة."], ["السقوط الدايم", "لو رميت كورة بسرعة أفقية، بتقع على الأرض بعد مسافة. كل ما زودت السرعة، بتقع بعيد أكتر. لو السرعة كبيرة جدا، الكورة بتقع، لكن الأرض بتنحني بعيد عنها بنفس المعدل، فمش بتلمس الأرض أبدا. المدار هو سقوط مستمر حوالين الأرض."], ["ليه مراحل", "وزن الصاروخ ضخم، ومعظمه خزانات وقود. لما الوقود في الخزان الأول يخلص، الخزان الفاضي بقى وزن زيادة. فالصاروخ بيرمي المرحلة الأولى ويكمل بمرحلة تانية أخف. تقسيم الصاروخ لمراحل بيخليه يوصل لسرعة أكبر بوقود أقل."], ["الرواد بيطفوا", "الرواد جوه محطة الفضاء بيطفوا، مش لأن مفيش جاذبية. الجاذبية لسه موجودة وقوية هناك. هم والمحطة بيقعوا سقوط حر مع بعض حوالين الأرض، فمش بيحسوا بوزنهم. ده اللي بنسميه انعدام الوزن الظاهري."], ["العودة للأرض", "للرجوع، المركبة بتبطئ سرعتها بإشعال محركات في اتجاه مضاد، فبتنزل من المدار. وبتدخل الغلاف الجوي بسرعة كبيرة، والاحتكاك بيسخنها جدا، فعندها درع حراري. وبعدين مظلات أو أنظمة هبوط تبطئها للنزول."], ["صواريخ بتتعاد", "في السنين الأخيرة، بعض الصواريخ بقت بترجع مراحلها الأولى للأرض وتهبط بسلام، عشان تتعاد استخدامها. ده بيقلل تكلفة الإطلاق. والفكرة معقدة لأنها محتاجة تحكم دقيق وهي بتنزل."], ["المحركات والفوهات", "شكل فوهة الصاروخ مهم. الفوهة المصممة للجو بتكون مختلفة عن اللي للفراغ. وظيفتها إنها توجه الغازات الخارجة للخلف بكفاءة وتزود سرعتها. وكل ما سرعة الغازات زادت، الدفع بالنسبة للوقود المستخدم زاد."], ["التحكم", "الصاروخ لازم يفضل متزن أثناء الصعود. بيستخدم أجهزة استشعار ومحركات بتتحرك أو بتميل عشان توجه الدفع. والكمبيوتر بيعمل تصحيحات مستمرة. أي ميل بسيط من غير تصحيح ممكن يكبر بسرعة."], ["زاوية الصعود", "الصاروخ ما بيطلعش لفوق مستقيم طول الوقت. بيبدأ رأسي عشان يخرج من الجو الكثيف بسرعة، وبعدين بيميل تدريجيا في اتجاه المدار. المسار ده مصمم بحيث يحقق السرعة الأفقية المطلوبة بأقل فقد."], ["المدارات المختلفة", "فيه مدارات منخفضة قريبة من الأرض، ومدارات أعلى بكتير. القمر الصناعي في مدار أعلى بيلف أبطأ. وفيه مدار على ارتفاع معين بيلف فيه القمر بنفس سرعة دوران الأرض، فيبان ثابت فوق نفس النقطة."], ["المراحل بالتفصيل", "المرحلة الأولى بتشتغل في الأول بقوة كبيرة جدا عشان ترفع الصاروخ بوزنه الكبير في الجو الكثيف. لما تخلص بتنفصل، وتبدأ المرحلة التانية في هوا أخف بكتير. وكل مرحلة فوهتها ومحركها مصمم لظروفها."], ["الجاذبية بتفضل", "الجاذبية على ارتفاع المحطات الفضائية لسه حوالي تسعين في المية من جاذبية السطح تقريبا. عشان كده الرواد ما بيطفوش لأن مفيش جاذبية، لكن لأنهم في سقوط حر مستمر."], ["الاتصال والتتبع", "محطات على الأرض بتتتبع الصاروخ وبتبعت أوامر. الأقمار الصناعية بتتصل بمحطات الأرض في أوقات مرورها فوقها، أو عن طريق أقمار تانية. ودي منظومة معقدة لضمان استمرار التحكم."], ["الحرارة والاهتزاز", "الصاروخ بيتحمل اهتزازات وضغط وحرارة عالية. المهندسين بيختبروا الأجزاء على الأرض عشان يتأكدوا إنها تتحمل. وده من أسباب إن الصواريخ بتحتاج فريق ضخم وتجارب كتيرة."], ["الخلاصة", "الخلاصة: الصاروخ بيدفع غازات لتحت فيرتفع، بس سره الحقيقي هو السرعة الأفقية العالية اللي بتخليه يسقط حوالين الأرض من غير ما يلمسها. المراحل بتخفف الوزن، والرواد بيطفوا لأنهم في سقوط حر. فهم السرعة هو فهم الفضاء."]], "f": ["السرعة المدارية حوالي 7.8 كم/ث.", "التقسيم لمراحل يخفف الوزن.", "الطفو في المدار سببه السقوط الحر."], "c": "طيران وفضاء", "dur": "4 دقايق", "tot": 243, "st": [0, 15, 29, 43, 57, 74, 88, 102, 115, 126, 140, 152, 165, 180, 193, 205, 217, 228], "w": 567}, {"n": 29, "t": "الذكاء الاصطناعي بيرد عليك ازاي؟", "e": "How an AI Chatbot Answers You", "h": "هو بيتوقع الكلمة اللي جاية، كلمة كلمة.", "sc": [["بيرد زي إنسان", "بتكتب سؤال لشات بوت، فبيرد بإجابة منظمة ومفهومة، وأحيانا بشعر وأكواد وقصص. بيبان كأنه فاهم. بس اللي بيحصل جواه أبسط مما تتخيل في الفكرة، وأعقد في التنفيذ. هو في الأساس بيتوقع الكلمة اللي جاية، كلمة كلمة."], ["تدريب على نصوص", "النموذج بيتدرب على كمية ضخمة من النصوص: كتب ومقالات ومواقع. أثناء التدريب، بيشوف جملة ناقصة الكلمة الأخيرة، وبيحاول يتوقعها. لو غلط، بيعدل أرقام جواه شوية. وده بيتكرر مليارات المرات لحد ما بيتعلم أنماط اللغة."], ["التوكنز", "النموذج مش بيشوف حروف زي ما بنشوف. بيقطع النص لأجزاء صغيرة اسمها توكنز، ممكن تكون كلمة أو جزء كلمة أو علامة ترقيم، وبيحول كل توكن لرقم. لما بتكتب سؤال، بيتحول لسلسلة أرقام الأول."], ["الأرقام والمعاني", "كل توكن بيتمثل بمجموعة أرقام كتير بتعبر عن علاقته بباقي الكلمات. كلمات متقاربة في المعنى بتبقى أرقامها قريبة. الأرقام دي بتتعدل أثناء التدريب. وده اللي بيخليه يفرق بين كلمة بمعنيين حسب الجملة."], ["الانتباه", "النموذج فيه آلية اسمها الانتباه، بتخليه يراعي العلاقة بين كل كلمة وباقي الكلمات في الجملة. لو قلت جملة طويلة، بيعرف الضمير بيرجع لأنهي اسم. من غير آلية الانتباه، النموذج كان هيضيع في الجمل الطويلة."], ["التوقع كلمة كلمة", "بعد ما فهم سؤالك، بيحسب احتمالات لكل توكن ممكن يكون هو الأول في الإجابة، ويختار واحد. بعدها يضيفه للنص ويحسب الاحتمالات للتوكن التالي، وهكذا لحد ما الإجابة تكتمل. ده سبب إن الإجابة بتظهر تدريجيا."], ["ليه أحيانا يغلط", "النموذج بيتوقع الأنسب إحصائيا، مش بيتأكد من الحقيقة. فممكن يكتب حاجة تبان معقولة لكنها غلط، أو يخترع مرجع مش موجود. ده اللي بيسموه هلوسة. وكمان معلوماته محدودة بتاريخ التدريب، إلا لو متوصل بأداة بحث."], ["التحسين بعد التدريب", "بعد التدريب الأولي، النموذج بيتدرب على إجابات أحسن من بشر بيقيموا الردود. ده بيخليه أكتر فايدة وأقل ضررا وأقرب لأسلوب المحادثة. وفيه ضوابط وقواعد بتتحط عشان يرفض طلبات خطيرة."], ["إزاي تستفيد وتأمن", "اسأل بوضوح، وادي سياق، وراجع المعلومات المهمة من مصدر موثوق، خصوصا الأرقام والتواريخ والنصايح الطبية والقانونية. وما تدخلش بيانات سرية. هو أداة قوية، لكن المسؤولية عليك."], ["المعاملات", "النموذج فيه ملايين أو مليارات الأرقام اسمها معاملات. دي هي اللي بتتعدل أثناء التدريب. كل ما عددها زاد، النموذج غالبا بيقدر يتعلم أنماط أعقد، لكن بيحتاج حاسوب أقوى وطاقة أكتر."], ["درجة العشوائية", "النموذج ممكن يختار دايما أعلى احتمال، أو يختار بعشوائية بسيطة. لو عشوائية أعلى، الإجابات بتتنوع وتبقى أكتر إبداعا. ولو أقل، بتبقى أكتر ثباتا. عشان كده لو سألت نفس السؤال مرتين ممكن تاخد إجابتين مختلفتين."], ["السياق", "النموذج بيشوف كلامك السابق في المحادثة ضمن حد معين، اسمه نافذة السياق. لو المحادثة طالت جدا، ممكن ينسى الأجزاء الأولى. فلو في معلومة مهمة، أعد ذكرها."], ["ما بيفهمش زيك", "النموذج بيتعامل مع أنماط في النص. هل ده يعني فهم حقيقي؟ سؤال بيتناقش بين الباحثين. المهم عمليا إنه أداة قوية وبتفيد، لكن مش مصدر معصوم، ومش بتحس ولا بتتذكر محادثاتك بالطريقة اللي بيحصل عند الإنسان."], ["الأمثلة المفيدة", "النموذج مفيد في الشرح والتلخيص والترجمة وكتابة الأكواد ومراجعة النصوص. لكن مش مفيد لو اعتمدت عليه بدون مراجعة في حاجات حساسة. استخدامه الأمثل بيكون كمساعد، والقرار النهائي ليك."], ["الأسئلة الأفضل", "كل ما كان سؤالك أوضح، وفيه سياق وتفاصيل ومثال للشكل المطلوب، الإجابة بتكون أفضل. ولو الإجابة مش مناسبة، وضح للنموذج وعدلها. الحوار بيحسن النتيجة."], ["الأدوات", "بعض الأنظمة بتتوصل بأدوات: بحث على الإنترنت، حاسبة، تشغيل أكواد. وده بيخليها أدق في المعلومات الحديثة والعمليات الحسابية، لأنها بتعتمد على الأداة بدل التخمين."], ["التحيز", "النموذج اتدرب على نصوص كتبها بشر، فممكن يعكس تحيزات موجودة فيها. الشركات بتحاول تقللها بالتحسين والمراجعة، لكن مفيش نظام خالي منها تماما. وده سبب آخر للمراجعة والتفكير النقدي."], ["الخلاصة", "الخلاصة: نموذج تدرب على نصوص كتيرة، بيحول كلامك لتوكنز وأرقام، بيستخدم الانتباه عشان يفهم العلاقات، وبيتوقع الإجابة توكن بتوكن. وده بيفسر قوته، وبيفسر ليه ممكن يغلط ويحتاج مراجعتك."]], "f": ["بيتوقع التوكن التالي.", "بيتعلم من نصوص ضخمة.", "ممكن يغلط ويحتاج مراجعة."], "c": "ذكاء اصطناعي", "dur": "4 دقايق", "tot": 235, "st": [0, 15, 30, 44, 58, 72, 87, 102, 114, 125, 138, 153, 164, 179, 191, 201, 211, 223], "w": 549}, {"n": 30, "t": "لوحة المفاتيح: ازاي ضغطة بتبقى حرف على الشاشة؟", "e": "How a Key Press Becomes a Letter", "h": "ضغطة زرار صغيرة بتعدي في رحلة سريعة جدا.", "sc": [["ضغطة وحرف", "بتضغط حرف على الكيبورد، وفي نفس اللحظة بيظهر على الشاشة. بيبان فوري، لكن في الواقع حصلت رحلة كاملة جوه الجهاز في أجزاء من الثانية. تعالى نمشي مع الحرف من أول ما صباعك ينزل."], ["الزرار والدايرة", "تحت كل زرار في الكيبورد فيه نقطة تلامس كهربائية أو مفتاح ميكانيكي. في الوضع العادي الدايرة مفتوحة، يعني مفيش تيار. لما تضغط الزرار، الدايرة بتتقفل، والكهربا تقدر تعدي."], ["شبكة صفوف وأعمدة", "لو كل زرار ليه سلك لوحده، هنحتاج أسلاك كتير جدا. فالكيبورد بيستخدم شبكة صفوف وأعمدة. كل زرار بيقع عند تقاطع صف وعمود. المتحكم بيبعت إشارة في كل صف على التوالي، وبيشوف في أنهي عمود وصلت. التقاطع ده بيحدد الزرار."], ["المتحكم", "فيه معالج صغير جوه الكيبورد اسمه المتحكم. بيمسح الشبكة آلاف المرات في الثانية. لما يلاحظ إن زرار اتضغط، بيحوله لكود رقمي. الكود ده مش الحرف نفسه، هو رقم بيمثل موقع الزرار على الكيبورد."], ["الإرسال", "الكود بيتبعت للكمبيوتر، عن طريق سلك USB أو بلوتوث. الإرسال بيتم بنبضات كهربائية أو راديو بتمثل أصفار وواحدات. الكمبيوتر بيستقبل الكود ويعرف إنه جاي من الكيبورد."], ["نظام التشغيل يترجم", "نظام التشغيل عنده جدول اسمه تخطيط الكيبورد. لو اللغة إنجليزي، الكود ده معناه حرف معين. ولو اللغة عربي، نفس الكود ممكن يعني حرف تاني. عشان كده لما تغير اللغة، نفس الزرار بيطلع حرف مختلف من غير ما الكيبورد يتغير."], ["الحرف يروح للبرنامج", "نظام التشغيل بعد ما حدد الحرف، بيبعته للبرنامج المفتوح قدامك، زي المتصفح أو برنامج الكتابة. البرنامج بيضيف الحرف للنص وبيطلب من النظام يرسمه على الشاشة. وبكده يظهر الحرف عند المؤشر."], ["الأزرار المركبة", "لما تضغط أكتر من زرار مع بعض زي شيفت وحرف، الكيبورد بيبعت الأكواد الاتنين، ونظام التشغيل بيفهم إنهم مرتبطين وبيطلع حرف كبير. ولو ضغطت كنترول وحرف، النظام بيفسرها كأمر مش حرف، زي نسخ أو لصق."], ["ليه بعض الأزرار بتتجاهل", "في الكيبوردات الرخيصة، لو ضغطت أزرار كتير مع بعض ممكن يتجاهل بعضها بسبب تصميم الشبكة. الكيبوردات الألعاب غالبا بتعالج المشكلة عشان تسمح بكذا زرار في نفس الوقت. دي مش عيب فيك، دي حدود الدايرة."], ["أنواع المفاتيح", "فيه كيبوردات بغشاء مطاطي، بتدي إحساس ناعم وصوت أهدى. وفيه كيبوردات ميكانيكية، كل زرار فيها مفتاح لوحده بزنبرك، بتدي إحساس وصوت مميز. والنوع الميكانيكي بيتحمل عدد كبير من الضغطات."], ["الارتداد", "لما تضغط الزرار، التلامس الكهربائي ممكن يرتد ويفتح ويقفل بسرعة جدا في أجزاء من الثانية. المتحكم بيتجاهل الارتدادات القصيرة دي، عشان ما يسجلش الحرف أكتر من مرة. الفكرة اسمها تصفية الارتداد."], ["التكرار", "لو فضلت ضاغط على زرار، الكمبيوتر بعد فترة صغيرة بيبدأ يكرر الحرف بمعدل ثابت. ده من نظام التشغيل مش من الكيبورد. وتقدر تغير السرعة وفترة الانتظار من إعدادات النظام."], ["اللاسلكي", "الكيبورد اللاسلكي بيبعت الأكواد بالراديو بدل السلك، عن طريق بلوتوث أو جهاز استقبال صغير. بيحتاج بطارية. والإشارات غالبا مشفرة في الأنظمة الحديثة عشان حد قريب ما يسجلش اللي بتكتبه."], ["تخطيطات اللغات", "كيبورد عربي وإنجليزي على نفس الأزرار طباعة مزدوجة. الكيبورد نفسه ما بيعرفش اللغة. نظام التشغيل هو اللي بيحدد الحرف من الكود حسب اللغة المختارة."], ["الاختصارات", "الاختصارات زي نسخ ولصق بتتم لما البرنامج يتلقى كود الكنترول مع الحرف. ده بيسمح بمئات الأوامر السريعة من غير الماوس، وبيوفر وقت كبير لمن يتعودوا عليه."], ["الصحة", "الكتابة لساعات طويلة بوضع غير مريح ممكن تتعب اليدين والرسغ. وضع الكيبورد على ارتفاع مناسب وكسر الجلسة بوقفات بسيطة بيساعد. دي نصيحة عامة وليست استشارة طبية."], ["تطور الكيبورد", "ترتيب الحروف في الكيبورد الإنجليزي مأخوذ من الآلة الكاتبة القديمة، مش من ترتيب الأبجدية. والترتيب ده ثبت مع الزمن بسبب العادة، رغم وجود ترتيبات تانية."], ["الخلاصة", "الخلاصة: الضغطة بتقفل دايرة، المتحكم يكتشف مكانها في الشبكة ويحولها لكود، الكود يتبعت للكمبيوتر، ونظام التشغيل يترجمه لحرف حسب لغة الكيبورد، والبرنامج يرسمه على الشاشة. رحلة كاملة في أجزاء من الثانية، كل مرة بتكتب."]], "f": ["كل زرار بيقفل دايرة.", "الكيبورد يبعت كود مش الحرف.", "نظام التشغيل يحوله لحرف."], "c": "تكنولوجيا", "dur": "4 دقايق", "tot": 236, "st": [0, 14, 26, 43, 57, 68, 85, 98, 113, 127, 140, 153, 165, 178, 188, 199, 210, 221], "w": 550}, {"n": 31, "t": "الإنترنت بيوصل لموبايلك ازاي من أول الكابل لحد الشاشة؟", "e": "How the Internet Reaches Your Screen", "h": "الإنترنت مش سحابة في السما. هو كابلات وسيرفرات وأجهزة توجيه، وكل صفحة بتفتحها بتعدي على رحلة طويلة في أجزاء من الثانية.", "sc": [["الصفحة اللي فتحت في ثانية", "بتكتب اسم موقع في المتصفح، وبعد ثانية تقريبا الصفحة قدامك بصور وفيديو. بيتهيألك إن الصفحة كانت جاهزة في التليفون، لكن الحقيقة إنها جت من سيرفر ممكن يكون في بلد تانية. وفي الطريق عدت على أجهزة كتير: راوتر بيتك، وكابلات شركة الإنترنت، ومحطات، وكابلات تحت البحر ممكن. في الفيديو ده هنمشي مع الطلب خطوة خطوة، ونفهم إيه اللي بيحصل بالظبط، ومين المسؤول عن كل جزء. ومهم نقول من الأول إن الشكل ده مبسط، لأن الشبكة الحقيقية أعقد، لكن الفكرة الأساسية صحيحة."], ["إيه هو الإنترنت أصلا", "كتير بيفتكروا الإنترنت شركة أو موقع. هو في الحقيقة شبكة من الشبكات. شبكة بيتك متوصلة بشبكة شركة الإنترنت، وشبكة الشركة متوصلة بشبكات شركات تانية ومراكز بيانات. كل الشبكات دي بتتفاهم بقواعد متفق عليها اسمها بروتوكولات. من غير القواعد دي، كل شبكة هتتكلم بلغة مختلفة. ومفيش جهة واحدة بتمتلك الإنترنت كله، كل جزء ليه صاحب، والتعاون بينهم هو اللي بيخلي الصورة كاملة."], ["الجهاز بتاعك والراوتر", "أول محطة هي جهازك. لما تطلب صفحة، جهازك بيجهز طلب صغير مكتوب بلغة متفق عليها. الطلب ده بيتبعت للراوتر في بيتك، سواء بسلك أو واي فاي. الراوتر شغلته يوزع الاتصال على أجهزة البيت، ويحدد لكل جهاز عنوان داخلي. بعدين بيبعت الطلب للخارج عن طريق الخط اللي جاي من شركة الإنترنت. فالراوتر هو بوابة بيتك على العالم."], ["الحزم الصغيرة", "البيانات ما بتتبعتش كتلة واحدة. بتتقسم لحزم صغيرة، كل حزمة فيها جزء من البيانات، وعنوان المرسل وعنوان المستقبل ورقم ترتيب. الفكرة دي ذكية لأن لو جزء من الشبكة زحمة أو وقع، الحزم تقدر تمشي في طريق تاني. وفي الآخر الجهاز المستقبل بيجمع الحزم ويرتبها بالأرقام ويكوّن الصفحة. ولو حزمة ضاعت، بيطلبها تاني."], ["العناوين: IP والـ DNS", "كل جهاز على الإنترنت ليه عنوان رقمي اسمه IP. لكن إحنا بنكتب أسماء مش أرقام. هنا بيجي دور الـ DNS، دفتر التليفونات اللي بيحول اسم الموقع لعنوان IP. جهازك بيسأل سيرفر DNS، وهو بيرد بالعنوان. وده بيحصل في أجزاء من الثانية، وغالبا الإجابة بتتحفظ مؤقتا عشان المرة الجاية تبقى أسرع."], ["شركة الإنترنت", "بعد الراوتر، الخط بيروح لشركة الإنترنت. الخط ممكن يكون نحاس أو ألياف ضوئية أو إشارة راديو في الموبايل. الشركة عندها معدات في مناطق بتجمع خطوط ناس كتير. ومن هناك بتتوصل بشبكة أكبر. السرعة اللي بتدفع عليها هي الحد الأقصى للتدفق على الخط ده، لكن السرعة الفعلية بتتأثر كمان بالزحمة وبعد السيرفر وجودة الشبكة."], ["الألياف الضوئية", "الألياف الضوئية خيوط رفيعة من الزجاج بتنقل المعلومات كنبضات ضوء. الضوء بيرتد جوه الخيط على جدرانه الداخلية، فبيكمل طريقه حتى لو الخيط اتلوى. ميزة الألياف إنها بتنقل بيانات كتير جدا لمسافات طويلة، وبتتأثر أقل بالتشويش الكهربي. عشان كده هي العمود الفقري لشبكات الإنترنت."], ["الكابلات تحت البحر", "الاتصال بين القارات جزء كبير منه بيعدي في كابلات ألياف ضوئية موضوعة في قاع البحار والمحيطات. الكابلات دي محمية بطبقات، وبتتمد بسفن مخصوصة. وفيها معدات كل مسافة بتقوي الإشارة. ومصر مهمة جدا في الخريطة دي لأن كابلات كتير بتعدي من البحر الأحمر والبحر المتوسط. ولو كابل اتقطع، الحركة بتتحول لكابلات تانية، لكن ممكن السرعة تقل."], ["أجهزة التوجيه في الطريق", "على الطريق بين جهازك والسيرفر، فيه أجهزة توجيه كتير. كل جهاز بيشوف عنوان الوجهة في الحزمة، ويقرر تروح لأنهي جهاز بعده. هو ما بيعرفش الطريق كله، بيعرف الخطوة الجاية بس، حسب جدول فيه معلومات عن الشبكات المجاورة. وفي كذا قفزة بتوصل الحزمة. أداة اسمها تتبع المسار بتقدر تورّيك القفزات دي."], ["السيرفر ومركز البيانات", "الحزمة توصل لسيرفر، وهو كمبيوتر قوي شغال طول الوقت، موجود غالبا في مركز بيانات: مبنى فيه آلاف السيرفرات مع تبريد وكهربا احتياطية واتصال سريع. السيرفر يستقبل طلبك، ويجهز الصفحة أو يجيبها من قاعدة بيانات، ويبعتها. المواقع الكبيرة ممكن يكون عندها سيرفرات في بلاد كتير عشان الأقرب ليك يرد."], ["الشبكات الموزعة CDN", "مواقع كتير بتستخدم خدمة اسمها شبكة توصيل المحتوى. بتحتفظ بنسخ من الصور والفيديوهات في سيرفرات قريبة من المستخدمين. فلما تفتح فيديو، ممكن ياجي من سيرفر في بلدك مش من بلد صاحب الموقع. ده بيقلل التأخير ويخفف الحمل على السيرفر الأصلي، وبيحسن السرعة."], ["الرجوع وتجميع الصفحة", "السيرفر يبعت الرد، وهو كمان بيتقسم لحزم تعدي نفس الشبكة في الاتجاه العكسي، وممكن في طرق مختلفة. جهازك بيستقبلها ويرتبها. والمتصفح بيقرأ الكود ويطلب الصور والخطوط والملفات الإضافية، كل ده بطلبات صغيرة تانية. وبعدها يرسم الصفحة. فصفحة واحدة ممكن تكون عشرات أو مئات الطلبات."], ["ليه أحيانا بيبطأ", "البطء ممكن يبقى من واي فاي ضعيف، أو زحمة على خط الشركة، أو سيرفر بعيد أو مشغول، أو مشكلة في كابل. والتأخير بيتقاس بالملي ثانية، وبيعتمد على المسافة وعدد القفزات. السرعة والتأخير حاجتين مختلفتين: ممكن سرعة عالية وتأخير عالي، وده يأثر في الألعاب والمكالمات أكتر من التحميل."], ["الأمان والتشفير", "معظم المواقع النهاردة بتستخدم اتصال مشفر، وبتشوفه كقفل في المتصفح. التشفير بيخلي البيانات اللي بتعدي في الطريق غير مفهومة لأي حد في النص. لكن التشفير لا يمنع الموقع نفسه من أنه يكون مزيف، فدايما اتأكد من العنوان. وبرضه شركة الإنترنت ممكن تعرف أسماء المواقع اللي بتزورها حتى لو المحتوى مشفر."], ["طبقات الإنترنت", "الإنترنت شغال بطبقات، كل طبقة ليها شغلة وما بتهتمش بتفاصيل التانية. طبقة بتهتم بالإشارات والكابلات، وطبقة بتهتم بالعناوين والتوجيه، وطبقة بتضمن وصول البيانات كاملة ومرتبة، وطبقة للتطبيقات زي المتصفح والبريد. الفكرة دي بتخلي أي طبقة تتطور من غير ما تبوظ الباقي. فالواي فاي ممكن يتغير وفي نفس الوقت المتصفح يفضل شغال زي ما هو، لأن الطبقات متفقة على شكل التواصل بينها بس."], ["بروتوكول TCP والثقة", "فيه بروتوكول اسمه TCP مهمته إن البيانات توصل كاملة وبالترتيب. المرسل بيبعت حزم ويستنى تأكيد استلام. لو التأكيد ما جاش، بيعيد إرسال الحزمة. وبيبطأ الإرسال لو حس إن الشبكة زحمة، وبيسرع لو الطريق فاضي. ده بيمنع الشبكة من الانهيار تحت الحمل. ولهذا تحميل ملف بيوصل سليم حتى لو الشبكة بتفقد بعض الحزم في الطريق."], ["بروتوكول UDP والسرعة", "مش كل التطبيقات محتاجة كل الحزم. في مكالمة فيديو، لو حزمة صوت ضاعت، مش منطقي نستنى ونعيدها، لأن الكلام اللي بعده أهم. فيه بروتوكول اسمه UDP بيبعت من غير تأكيد. أسرع وأخف، بس بيقبل ضياع جزء. الألعاب والمكالمات بتستخدمه كتير. فاختيار البروتوكول بيعتمد على الأهم: الدقة الكاملة ولا السرعة."], ["جدول التوجيه", "كل راوتر على الطريق عنده جدول فيه معلومات عن مجموعات العناوين وأنهي جار يوصل ليها. الجداول دي بتتحدث بين الراوترات عن طريق بروتوكولات بتتبادل معلومات عن الطرق المتاحة. لو كابل وقع أو طريق زحمة، المعلومة بتنتشر والراوترات تغير اختيارها. وبالتالي الإنترنت بيصلح نفسه نسبيا، من غير ما حد مركزي يتحكم في كل خطوة."], ["العنوان الداخلي والخارجي", "الأجهزة في بيتك ليها عناوين داخلية بتشتغل جوه الشبكة بس. والراوتر ليه عنوان خارجي واحد تقريبا تشاركه كل الأجهزة. لما جهازك يطلب حاجة، الراوتر بيبدل العنوان الداخلي بالخارجي ويفتكر مين طلب إيه، وبيرجع الرد للجهاز الصح. التقنية دي اسمها ترجمة العناوين، وهي بتساعد في توفير عناوين الإنترنت اللي كانت بتقل."], ["عناوين الإصدار السادس", "عناوين IP القديمة اللي بتتكون من أربع أرقام ليها عدد محدود، حوالي أربع مليارات، وده مبقاش كفاية لكل الأجهزة. فاتعمل إصدار جديد بعناوين أطول بكتير، بيوفر عدد ضخم جدا. الانتقال بيحصل تدريجيا، والشبكات بتشتغل بالإصدارين مع بعض لفترة. وده من أسباب إن الإنترنت بيحتاج تعاون كتير عشان يتطور."], ["نقاط تبادل الإنترنت", "شبكات الشركات الكبيرة بتتوصل ببعض في أماكن اسمها نقاط تبادل الإنترنت. هناك بيتبادلوا الحركة مباشرة بدل ما يعدوها عبر وسطاء بعيدين. ده بيقلل التأخير والتكلفة. وبيخلي حركة محتوى زي الفيديوهات توصل أسرع. وجود النقاط دي في بلد بيحسن جودة الإنترنت فيها."], ["مين بيتحكم", "مفيش جهة واحدة بتتحكم في الإنترنت كله. فيه منظمات بتضع المعايير التقنية، وجهات بتوزع عناوين IP وأسماء النطاقات، وشركات بتشغل الشبكات، وحكومات بتضع قوانين لبلدها. ده معناه إن قرارات كتير بتتخذ في أماكن مختلفة. وكل شبكة ليها حرية في إدارتها طالما بتلتزم بالمعايير المتفق عليها."], ["الخلاصة", "الخلاصة: جهازك بيعمل طلب، يتقسم لحزم، يعدي على راوترك، وبعدين شركة الإنترنت، وبعدين أجهزة توجيه وألياف ضوئية وكابلات تحت البحر، ويوصل لسيرفر في مركز بيانات. السيرفر يرد بحزم ترجع لجهازك ويتجمع فيها الصفحة. كل ده في أجزاء من الثانية، وبقواعد متفق عليها. والإنترنت مش سحابة، هو بنية تحتية حقيقية على الأرض وتحت البحر."]], "f": ["الإنترنت شبكة من الشبكات المتصلة ببعض عن طريق كابلات وأجهزة توجيه", "جزء كبير من حركة الإنترنت بين القارات بيعدي في كابلات ألياف ضوئية تحت البحر", "البيانات بتتقسم لحزم صغيرة وكل حزمة ممكن تمشي في طريق مختلف", "عنوان IP بيحدد الجهاز، والـ DNS بيحول اسم الموقع لعنوان"], "c": "شبكات", "dur": "8 دقايق ونص", "tot": 508, "st": [0, 34, 60, 84, 107, 128, 151, 169, 193, 214, 235, 253, 272, 292, 313, 340, 363, 384, 407, 428, 449, 466, 486], "w": 1186}, {"n": 32, "t": "المعالج (CPU) بيفكر ازاي جوه الكمبيوتر؟", "e": "Inside a CPU: How a Processor Works", "h": "المعالج مش بيفكر زي الإنسان. هو بينفذ تعليمات بسيطة جدا بسرعة مهولة، وملايين الخطوات دي بتطلع لك لعبة وفيديو.", "sc": [["سؤال بسيط", "لما بتلعب لعبة أو بتفتح فيديو، بيتهيألك الكمبيوتر بيفهم وبيفكر. لكن الحقيقة إن المعالج بيعمل حاجات بسيطة جدا: بيجمع رقمين، يقارن، ينقل رقم من مكان لمكان. الفرق إنه بيعمل ملايين أو مليارات من الحاجات دي في الثانية. في الفيديو ده هنفهم إزاي حاجات بسيطة زي كده بتتحول لنتيجة معقدة قدامك على الشاشة."], ["كل حاجة أرقام", "الكمبيوتر بيتعامل بالنظام الثنائي: صفر وواحد. ليه؟ لأن أسهل حاجة تعملها بالكهربا هي حالتين: في تيار أو مفيش. الحالتين دول بيمثلوا واحد وصفر. والحرف والصورة والصوت والتعليمة كلها بتتحول لأرقام ثنائية. الصفر والواحد الواحد اسمه بت، وكل تمانية بتات بيكونوا بايت."], ["الترانزستور", "جوه المعالج فيه مليارات الترانزستورات في المعالجات الحديثة. الترانزستور مفتاح كهربي صغير جدا بيفتح ويقفل بإشارة كهربية، من غير أجزاء متحركة. لو اتفتح بيمر تيار، لو اتقفل بيقف. ومن مجموعة ترانزستورات بتتعمل بوابات منطقية بتعمل عمليات زي AND وOR وNOT. دي أبسط وحدات للتفكير في الكمبيوتر."], ["من البوابات للحساب", "بتوصيل بوابات منطقية بشكل معين، تقدر تعمل دايرة بتجمع رقمين. وبتوصيل دوائر كتير تعمل حاجات أكبر: ضرب وقسمة ومقارنة. الجزء اللي بيعمل الحسابات اسمه وحدة الحساب والمنطق. هو قلب المعالج الحسابي، لكنه مش كل المعالج."], ["التعليمات", "البرنامج في الآخر قائمة طويلة من التعليمات بلغة الآلة. التعليمة مثلا: حمّل الرقم من مكان كذا، اجمعه مع رقم تاني، خزن النتيجة. كل نوع معالج عنده مجموعة تعليمات يفهمها. والبرامج اللي بنكتبها بلغات سهلة بتتحول بواسطة مترجم لتعليمات المعالج."], ["دورة التنفيذ", "المعالج بيكرر دورة: يجيب التعليمة من الذاكرة، يفك شفرتها ويفهم المطلوب، ينفذها، ويحفظ النتيجة. وبعدين يروح للتعليمة اللي بعدها. فيه عداد جوه المعالج بيشاور على التعليمة الجاية. الدورة دي بتتكرر بمعدل مليارات في الثانية."], ["التردد والساعة", "المعالج بيشتغل على إيقاع ساعة داخلية بتدق مليارات المرات في الثانية. سرعة الدق اسمها التردد، وبتتقاس بالجيجاهرتز. كل دقة هي فرصة لخطوة صغيرة. لكن زيادة التردد مش كل حاجة، لأن كمية الشغل اللي بتخلص في الدقة الواحدة كمان مهمة، وبتختلف من تصميم لتصميم."], ["الرام والذاكرة", "المعالج محتاج يجيب البيانات من مكان. الرام ذاكرة سريعة بتحتفظ بالبرامج والبيانات اللي بتشتغل عليها دلوقتي، لكنها بتفقد محتواها لما الكهربا تقطع. التخزين الدائم زي الـ SSD أبطأ لكنه بيحتفظ بالملفات. المعالج بيحتاج يجيب من الرام بسرعة، لكن الرام نفسها أبطأ بكتير من سرعة المعالج."], ["الكاش", "عشان الفرق في السرعة ده، فيه جوه المعالج ذاكرة صغيرة جدا وسريعة جدا اسمها الكاش. بتحتفظ بنسخ من البيانات اللي المعالج استخدمها قريب أو غالبا هيحتاجها. لو البيانات موجودة في الكاش، الوصول أسرع. ولو لأ، لازم يجيبها من الرام. وفيه مستويات كاش، كل مستوى أكبر وأبطأ من اللي قبله."], ["الأنابيب والتنفيذ المتوازي", "المعالج مش بيستنى تعليمة تخلص تماما قبل ما يبدأ اللي بعدها. زي مصنع، كل مرحلة بتشتغل على تعليمة مختلفة في نفس الوقت. اسم الفكرة خط الأنابيب. وكمان في معالجات بتنفذ أكتر من تعليمة في نفس الدقة، لو مش معتمدين على بعض."], ["التخمين", "في الشروط زي لو الرقم أكبر من كذا، المعالج مش عارف أنهي مسار هيمشي لحد ما يحسب. فبيخمن بناء على التاريخ، وبيبدأ في المسار المتوقع. لو التخمين صح، وفّر وقت. لو غلط، بيرمي الشغل ده ويبدأ من الأول. وتقنية التخمين دي من أسباب السرعة العالية."], ["أكتر من نواة", "المعالج الحديث فيه أكتر من نواة، وكل نواة بتنفذ تعليماتها لوحدها. وده بيخلي الكمبيوتر يشغل أكتر من برنامج في نفس الوقت، أو برنامج واحد يتقسم لأجزاء. لكن مش كل البرامج بتستفيد من النوى الكتير، لأن بعض المهام لازم تتم بالترتيب."], ["الحرارة", "كل ترانزستور بيفتح ويقفل بيستهلك طاقة قليلة وبيطلع حرارة. مع مليارات الترانزستورات الحرارة بتزيد. عشان كده المعالج محتاج مروحة أو مشتت حراري. ولو اتسخن زيادة، المعالج بيقلل سرعته تلقائيا عشان يحمي نفسه. وده من أهم قيود تحسين الأداء."], ["المعالج الرسومي", "فيه معالج تاني اسمه GPU متخصص في حاجات تتعمل على بيانات كتير في نفس الوقت، زي رسم الصورة في الألعاب. فيه آلاف الوحدات الصغيرة، وكل واحدة تعمل حساب بسيط. ده مختلف عن المعالج العادي اللي عنده أنوية قليلة لكن قوية ومرنة."], ["اللغة اللي المعالج بيفهمها", "كل نوع معالج ليه لغة آلة خاصة بيه. المبرمج بيكتب بلغة سهلة زي بايثون أو سي، وبيتحول الكود بمترجم أو مفسر لتعليمات الآلة. فيه أنواع كتير للتعليمات: حسابية، ونقل بيانات، وقفز لمكان تاني في البرنامج. التعليمات دي قليلة نسبيا لكن بتكفي لبناء أي برنامج. ومعالج الموبايل بيستخدم عادة تصميم مختلف عن معالج اللابتوب، وده سبب إن البرامج مش بتتنقل بينهم بسهولة من غير تعديل."], ["السجلات", "جوه المعالج أماكن تخزين صغيرة جدا وسريعة جدا اسمها السجلات. المعالج بيحط فيها الأرقام اللي بيشتغل عليها حالا. هي أسرع من الكاش. عدد قليل منها، لكن كل العمليات الحسابية بتتم عليها. فالبرنامج بيحمل رقم من الرام للسجل، ويعمل عليه عملية، ويكتب النتيجة. وحسن استغلال السجلات من أسباب سرعة البرنامج."], ["التسلسل الهرمي للذاكرة", "فيه ترتيب للذاكرة من الأسرع والأصغر للأبطأ والأكبر: سجلات، ثم كاش بمستوياته، ثم رام، ثم تخزين دائم. كل مستوى أبطأ وأرخص وأكبر من اللي قبله. المعالج والنظام بيحاولوا يبقوا البيانات اللي هتتطلب قريب في المستويات السريعة. والمبرمجين اللي بيفهموا الفكرة دي بيكتبوا كود أسرع بكتير بنفس المعالج."], ["المقاطعات", "المعالج مش بيفضل يسأل الكيبورد كل ثانية: ضغطت حاجة؟ الجهاز نفسه بيبعتله إشارة اسمها مقاطعة لما يحصل حدث. المعالج يوقف اللي بيعمله مؤقتا، ينفذ كود صغير للتعامل مع الحدث، وبعدين يرجع. ده بيخلي النظام يتفاعل مع الماوس والكيبورد والشبكة من غير ما يضيع وقت في السؤال المستمر."], ["نظام التشغيل والوقت المشترك", "لما تفتح أكتر من برنامج، المعالج بيدي كل برنامج شريحة وقت صغيرة جدا ويبدل بينهم آلاف المرات في الثانية. فبيتهيألك إنهم شغالين مع بعض. نظام التشغيل هو اللي بينظم التبديل ده، وبيحمي كل برنامج من التأثير على ذاكرة الآخر. وفي المعالجات متعددة النوى بيشتغل أكتر من برنامج فعلا في نفس اللحظة."], ["التصنيع", "الترانزستورات بتتصنع على رقاقة سيليكون بعمليات تصوير ضوئي دقيقة جدا، طبقة فوق طبقة. الأحجام بتتقاس بالنانومتر، يعني جزء من المليون من المليمتر. أي ذرة تراب ممكن تبوظ الشريحة، عشان كده المصانع بتشتغل في غرف نظيفة جدا. وكتير من الشرايح اللي بتطلع من الرقاقة الواحدة بتتختبر وبتتصنف حسب الأداء، فنفس التصميم ممكن يتباع في فئات مختلفة."], ["قانون مور وحدوده", "من عقود، عدد الترانزستورات في الشريحة كان بيتضاعف تقريبا كل فترة. دي ملاحظة اسمها قانون مور. لكن مع وصول الأحجام لمقاييس قريبة من حجم الذرات، التحسين بقى أصعب وأغلى، وبتظهر مشاكل زي التسرب الكهربي والحرارة. فالصناعة بتلجأ لحلول زي تصميم متعدد الطبقات ومعالجات متخصصة."], ["إيه اللي بيفرق في الأداء", "الأداء مش بس تردد. هو مجموعة عوامل: عدد النوى، وكفاءة التصميم، وحجم الكاش، وسرعة الرام، وقدرة التبريد، وكمان البرنامج نفسه. معالجين بنفس التردد ممكن يدوا نتايج مختلفة جدا. ولذلك مقارنة المعالجات بتحتاج اختبارات حقيقية على الأحمال اللي بتستخدمها، مش رقم واحد على العلبة."], ["الخلاصة", "الخلاصة: المعالج ملايين الترانزستورات اللي بتتحول لبوابات منطقية، وتبني دوائر حسابية. بينفذ تعليمات بسيطة بالنظام الثنائي في دورة متكررة، بمساعدة الرام والكاش وخطوط الأنابيب والنوى المتعددة. كل التعقيد اللي بتشوفه على الشاشة ناتج عن حاجات بسيطة بتتكرر بسرعة كبيرة جدا."]], "f": ["المعالج بينفذ تعليمات بسيطة بسرعة كبيرة جدا", "التعليمات والبيانات كلها أرقام بالنظام الثنائي أصفار وواحدات", "المعالج فيه ترانزستورات بتشتغل زي مفاتيح كهربية صغيرة", "الذاكرة المؤقتة (الكاش) أسرع من الرام بس أصغر"], "c": "كمبيوتر", "dur": "7 دقايق ونص", "tot": 441, "st": [0, 22, 40, 60, 75, 91, 106, 124, 144, 165, 182, 201, 219, 235, 252, 280, 301, 321, 341, 363, 387, 405, 424], "w": 1029}, {"n": 33, "t": "محرك الطيارة النفاث بيشتغل ازاي؟", "e": "How a Jet Engine Works", "h": "محرك الطيارة بيسحب هوا كتير، يضغطه، يحرق معاه وقود، ويدفعه لورا بقوة. والرد على الدفع ده هو اللي بيطير الطيارة.", "sc": [["قوة من ورا", "محرك الطيارة بيبان معقد، لكن فكرته بسيطة: خد هوا من قدام، وادفعه بسرعة أكبر لورا. لما المحرك يدفع الهوا لورا، الهوا بيدفع المحرك لقدام، وبالتالي الطيارة. ده اللي بنسميه قانون نيوتن الثالث. التفاصيل الهندسية هي اللي بتخلي ده يحصل بكفاءة وأمان على ارتفاع عشرة كيلومترات وبسرعة قريبة من سرعة الصوت."], ["ليه مش مروحة بس", "ممكن نتخيل إن مروحة كبيرة تدفع الهوا وخلاص. وفعلا فيه طيارات بتشتغل بالمراوح. لكن المحرك النفاث بيضيف حاجة: بيحرق وقود عشان يدي الهوا طاقة أكبر. ده بيخليه يقدر يدفع بسرعات وارتفاعات عالية بكفاءة أحسن من المراوح التقليدية."], ["الأربع مراحل", "في المحرك النفاث الأساسي، الهوا بيعدي على أربع مراحل: سحب، ضغط، احتراق، وخروج. سحب الهوا من الفتحة الأمامية. ضغطه في الكمبريسور. حرق الوقود معاه في غرفة الاحتراق. ودفع الغازات الساخنة عبر التوربين وبعدها الفوهة. تعالى نشوف كل مرحلة."], ["المروحة الأمامية", "في الطيارات التجارية، أول حاجة بتشوفها المروحة الكبيرة في المقدمة. المروحة دي بتسحب كمية ضخمة من الهوا. جزء من الهوا ده بيدخل قلب المحرك، وجزء كبير بيعدي حوالين القلب في قناة خارجية من غير ما يتحرق. الهوا الخارجي ده بيدي نسبة كبيرة من الدفع في المحركات الحديثة، وبيخلي المحرك أهدى وأوفر في الوقود."], ["الكمبريسور", "الهوا اللي دخل القلب بيعدي على صفوف من ريش صغيرة بتلف بسرعة. كل صف بيضغط الهوا أكتر. في الآخر الهوا بيكون مضغوط جدا وسخن. ليه ضغط؟ لأن الاحتراق في الهوا المضغوط بيدي طاقة أكتر وكفاءة أعلى. الكمبريسور محتاج طاقة كبيرة، وبياخدها من التوربين."], ["غرفة الاحتراق", "الهوا المضغوط بيدخل غرفة الاحتراق، وهناك بيترش الوقود ويشتعل. الاحتراق مستمر، مش انفجارات متقطعة زي محرك العربية. الغازات الناتجة بتبقى حرارتها عالية جدا وبتتمدد بسرعة. الغرفة معمولة من مواد تتحمل حرارة عالية، ومتبردة بطبقة هوا أبرد بتتحرك على سطحها."], ["التوربين", "الغازات الساخنة بتعدي على ريش التوربين وبتلفه. التوربين متوصل بعمود طويل بالمروحة الأمامية والكمبريسور. فجزء من طاقة الغازات بيروح يلف الكمبريسور والمروحة، وده بيخلي المحرك يكمل نفسه من غير مصدر خارجي. الريش دي بتشتغل في ظروف قاسية: حرارة عالية جدا وسرعة دوران كبيرة."], ["الفوهة والدفع", "بعد التوربين، الغازات اللي لسه فيها طاقة بتخرج من الفوهة الخلفية بسرعة عالية. السرعة دي أكبر من سرعة الهوا لما دخل المحرك. الفرق في كمية الحركة هو اللي بيطلع قوة الدفع. وكل ما كمية الهوا المدفوعة والفرق في السرعة أكبر، الدفع أكبر."], ["ليه الريش تتحمل الحرارة", "درجة حرارة الغازات في بعض المحركات ممكن تتعدى درجة انصهار المعدن اللي الريش مصنوع منه. فكيف تفضل شغالة؟ بسبب تقنيات: مواد خاصة، وطبقات حماية، وثقوب صغيرة جدا بتطلع هوا بارد بيعمل طبقة حماية على سطح الريشة. المهندسين بيخلوا الريش تشتغل قريب من حدودها بشكل آمن."], ["بدء التشغيل", "المحرك مش بيشتغل بالدفع من أول لحظة. في الأول، لازم حاجة تلف الكمبريسور لحد ما يكون فيه هوا كفاية. فيه بادئ بيلف المحرك، وبعدين يبدأ الوقود في الدخول والاشتعال. لما المحرك يوصل لسرعة معينة بيكمل لوحده."], ["التحكم الرقمي", "المحركات الحديثة بيتحكم فيها كمبيوتر مخصوص. بيقرأ حساسات الحرارة والضغط والسرعة، وبيعدل كمية الوقود باستمرار. ده بيحمي المحرك من الظروف الغلط ويوفر وقود. والطيار بيحرك ذراع الدفع، والكمبيوتر هو اللي بيترجم الطلب لإعدادات المحرك."], ["عكس الدفع", "بعد الهبوط، الطيارة بتحتاج تبطئ بسرعة. فرامل العجل بتساعد، لكن كمان فيه نظام في المحرك بيوجه جزء من الهوا للأمام. ده بيساعد في تقليل المسافة. وهو جزء من نظام الأمان في الهبوط."], ["الأمان والفحص", "المحركات النفاثة من أكتر المعدات اللي بتتفحص. فيه فحوص دورية، وفحص بالمناظير الداخلية، وتبديل أجزاء حسب عدد ساعات التشغيل. والمحرك بيتصمم يتحمل ابتلاع طيور أو ظروف قاسية في اختبارات رسمية. وبتحصل أحيانا أعطال، والطيارات مصممة تكمل بمحرك واحد في حالات كتير."], ["الوقود والبيئة", "المحركات بتستهلك وقود كتير، وده سبب انبعاثات. الصناعة بتحاول تحسن الكفاءة بتصميمات أحدث ومواد أخف، وبتجرب وقود بديل. وكل تحسين صغير في الكفاءة بيفرق كتير لأن عدد الرحلات ضخم."], ["عملية بريتون", "الدورة اللي بيعملها المحرك النفاث اسمها دورة بريتون. هي سحب هوا وضغط وتسخين بالاحتراق وتمدد. الكفاءة بتعتمد على نسبة الضغط ودرجة حرارة الغاز عند التوربين. كل ما نسبة الضغط ودرجة الحرارة أعلى، الكفاءة أحسن. ولذلك المهندسين بيدوروا على مواد تتحمل حرارة أعلى، وتصميمات ريش بتبرد نفسها."], ["نسبة التحويط", "في المحركات التجارية، النسبة بين الهوا اللي بيعدي حوالين القلب والهوا اللي بيدخل القلب اسمها نسبة التحويط. نسبة عالية معناها دفع أكبر بالنسبة للوقود وصوت أهدى. عشان كده مراوح المحركات الحديثة بقت أكبر. أما الطيارات المقاتلة فبتستخدم نسبة منخفضة عشان السرعات العالية."], ["المحور الثنائي", "في المحركات الكبيرة، مش عمود واحد بس. فيه أعمدة متداخلة بتلف بسرعات مختلفة. المروحة الكبيرة بتلف أبطأ، والكمبريسور الداخلي أسرع. كل جزء بيلف بسرعته المثالية، وده بيحسن الكفاءة. وبيحتاج تصميم دقيق للمحامل اللي بتشيل الأعمدة."], ["المحامل والزيت", "الأعمدة بتلف بآلاف اللفات في الدقيقة، فمحتاجة محامل متينة وتزييت مستمر. نظام الزيت في المحرك بيبرد ويزيت المحامل وبيتنظف بمرشحات. ولو حصل نقص في الزيت أو تلوث، المحرك بيعطي إنذار للطيار. وفحص الزيت من أهم أنواع الصيانة."], ["المحرك التوربيني المروحي والمراوح", "بعض الطيارات الصغيرة والمتوسطة بتستخدم محرك توربيني بيلف مروحة عادية بدل مروحة كبيرة مخبية. بيكون أوفر في الوقود في السرعات والارتفاعات المنخفضة نسبيا. والمحركات النفاثة البحتة أنسب للسرعات العالية جدا. اختيار المحرك بيعتمد على نوع الطيارة ومهمتها."], ["الضوضاء", "محركات الطيران بتعمل صوت من الغازات الخارجة بسرعة عالية ومن حركة الريش. التصميمات الحديثة بتقلل الصوت: مراوح أكبر وأبطأ، وفوهات بحواف مسننة بتقلل الاضطراب، ومواد بتمتص الصوت داخل غلاف المحرك. المطارات كمان بتحدد مسارات وأوقات تقلل الإزعاج."], ["الطيران بمحرك واحد", "الطيارات التجارية الكبيرة عندها محركين أو أكتر. الطيارة مصممة وتتدرب أطقمها على إكمال الرحلة بمحرك واحد في حال العطل. ولذلك في بعض المسارات فوق البحار، الطيارات الثنائية المحرك بتتبع قواعد بتخليها دايما في مسافة معينة من مطار بديل."], ["التطور والاتجاهات", "من أول المحركات النفاثة في القرن الماضي لحد اليوم، الكفاءة اتحسنت كتير، والضوضاء قلت، والانبعاثات لكل راكب قلت. والمهندسين شغالين على مواد خفيفة مقاومة للحرارة، وتصميمات أكتر كفاءة، وتجارب على وقود بديل وطيران كهربي للمسافات القصيرة. لكن الوقت لسه طويل قبل ما تظهر بدائل كاملة للرحلات الطويلة."], ["الخلاصة", "الخلاصة: المحرك بيسحب هوا بالمروحة، يضغطه في الكمبريسور، يحرقه مع الوقود في غرفة الاحتراق، والغازات الساخنة بتلف التوربين اللي بيشغل الكمبريسور والمروحة، وبعدين تخرج من الفوهة بسرعة عالية. رد الفعل على دفع الهوا لورا هو الدفع للأمام. فكرة بسيطة ومنفذة بدقة هندسية عالية."]], "f": ["المحرك النفاث بيسحب الهوا ويضغطه ويحرقه مع الوقود ويدفع الغازات للخلف", "قانون نيوتن الثالث: لكل فعل رد فعل مساوي له ومضاد له في الاتجاه", "في المحركات التجارية الحديثة جزء كبير من الدفع بييجي من الهوا اللي بيعدي حوالين القلب", "الكمبريسور والتوربين بيكونوا متوصلين بعمود"], "c": "طيران وفضاء", "dur": "6 دقايق ونص", "tot": 396, "st": [0, 21, 37, 54, 76, 95, 111, 130, 148, 167, 183, 197, 211, 228, 241, 261, 279, 294, 309, 325, 341, 357, 378], "w": 924}, {"n": 34, "t": "القلب بيضخ الدم لجسمك كله ازاي؟", "e": "How the Heart Pumps Blood", "h": "قلبك عضلة بحجم قبضة إيدك تقريبا، بتنبض من قبل ما تتولد وما بتقفش. وفي كل نبضة بتدفع الدم لكل جزء في جسمك.", "sc": [["عضلة ما بتتعبش", "قلبك بينبض طول عمرك، في النوم والصحيان، من غير ما تفكر فيه. بيدفع الدم لكل خلية في جسمك عشان توصلها الأكسجين والغذاء. وفي نفس الوقت بيرجع الدم اللي فيه فضلات. تخيل مضخة صغيرة بتشتغل بلا توقف عشرات السنين. في الفيديو ده هنشوف إزاي القلب مبني، وإزاي الدم بيمشي في الجسم، ومين اللي بيدي القلب الأمر ينبض. ومعلومات الفيديو للمعرفة العامة، مش بديل عن الطبيب لو عندك شكوى."], ["الدم محتاج يتحرك", "كل خلية في جسمك محتاجة أكسجين وغذاء، وده بيوصلها بالدم. مفيش وسيلة تانية سريعة كفاية لجسم بحجم الإنسان. لو الدم وقف، الخلايا اللي محتاجة أكسجين كتير زي خلايا المخ بتتأثر بسرعة. عشان كده الجسم بيعتمد على مضخة قوية ومستمرة، وعلى شبكة أنابيب بتوصل لكل مكان."], ["شكل القلب من برا", "القلب موجود في الصدر ومايل شوية ناحية الشمال. حجمه قريب من قبضة اليد. وحواليه كيس رقيق بيحميه ويقلل الاحتكاك وهو بينبض. وهو متوصل بأوعية دموية كبيرة بتدخل الدم له وتطلعه منه. والقلب نفسه عضلة خاصة اسمها عضلة القلب، مختلفة عن عضلات الإيد والرجل لأنها بتشتغل بشكل تلقائي."], ["الأربع غرف", "جوه القلب أربع غرف. فوق أذينين: يمين وشمال، ودول بيستقبلوا الدم. وتحت بطينين: يمين وشمال، ودول بيضخوا الدم. الأذين الأيمن والبطين الأيمن بيتعاملوا مع الدم اللي راجع من الجسم، والأذين الأيسر والبطين الأيسر بيتعاملوا مع الدم اللي راجع من الرئتين. وبين الجانب الأيمن والأيسر حاجز عضلي بيمنع اختلاط الدم."], ["الدورة الرئوية", "الدم اللي رجع من الجسم قليل الأكسجين بيدخل الأذين الأيمن، ومنه للبطين الأيمن. البطين ده بيضخه للرئتين. في الرئتين الدم بياخد أكسجين ويطلع ثاني أكسيد الكربون اللي بنطلعه في الزفير. وبعدها الدم الغني بالأكسجين بيرجع للقلب من الناحية الشمال. دي الدورة الدموية الرئوية."], ["الدورة الجسمية", "الدم اللي رجع من الرئتين بيدخل الأذين الأيسر، وبعدين البطين الأيسر. البطين الأيسر عضلاته أقوى من الأيمن لأنه لازم يدفع الدم لكل جسمك. الدم بيطلع في أكبر شريان في الجسم، اسمه الأورطي، وبيتفرع لشرايين أصغر وأصغر لحد ما يوصل لكل الأعضاء. دي الدورة الجسمية."], ["الصمامات", "عشان الدم ما يرجعش لورا، القلب فيه صمامات. هي زي أبواب بتفتح في اتجاه واحد. لما البطين ينقبض، الصمام بين الأذين والبطين يقفل، وصمام الخروج يفتح. وبعدين العكس. صوت دقات القلب اللي الدكتور بيسمعه هو في الأساس صوت قفل الصمامات. لو الصمام ضعيف أو ضيق، الدم بيرجع أو بيتأخر، وده يحتاج علاج."], ["النبضة الواحدة", "النبضة فيها مرحلتين: انقباض وانبساط. في الانقباض عضلات البطينين بتنقبض وتدفع الدم للخارج. وفي الانبساط بتسترخي وتمتلئ بالدم من الأذينين. دورة كاملة بتاخد أقل من ثانية في الحالة العادية. ومعدل النبض للشخص البالغ في الراحة بيكون في نطاق معين بيختلف من شخص لشخص."], ["إشارة كهربائية", "مين اللي بيقول للقلب انبض؟ في القلب مجموعة خلايا خاصة في الأذين الأيمن بتولد إشارات كهربائية بانتظام. الإشارة بتنتقل في القلب بمسار منظم، فتنقبض الأذينين الأول وبعدين البطينين. ده اللي بيخلي النبض منظم. جهاز رسم القلب بيسجل النشاط الكهربائي ده من فوق الجلد."], ["بيتحكم فيه الجسم", "القلب بيشتغل تلقائي، لكن الجهاز العصبي والهرمونات بيغيروا سرعته. لما تجري أو تتخض أو تتحمس، النبض بيزيد عشان العضلات محتاجة دم أكتر. ولما ترتاح أو تنام، بيقل. وده بيحصل من غير تفكير، والجسم بيوازن حسب الاحتياج."], ["الشرايين والأوردة والشعيرات", "الشرايين جدرانها سميكة ومرنة عشان تتحمل ضغط الدم الخارج من القلب. الأوردة جدرانها أرق، وفيها صمامات صغيرة تمنع رجوع الدم، وبتساعدها عضلات الجسم في دفع الدم لفوق. والشعيرات الدموية أرق أوعية، فيها بيحصل تبادل الأكسجين والغذاء مع الخلايا. وهي منتشرة في كل الجسم."], ["ضغط الدم", "ضغط الدم هو القوة اللي الدم بيضغط بها على جدران الشرايين. الأطباء بيقيسوه برقمين: الأول لما القلب ينقبض والتاني لما يرتاح. الضغط المرتفع لفترات طويلة بيجهد القلب والشرايين. والأرقام الطبيعية والمستهدفة بيحددها الطبيب حسب حالتك، فالأحسن تقيس وتتابع معاه."], ["القلب نفسه محتاج دم", "القلب بيضخ دم لكل الجسم، لكنه ما بياخدش غذاءه من الدم اللي جواه. فيه شرايين خاصة اسمها الشرايين التاجية بتمشي على سطحه وبتغذي عضلته. لو واحد منها اتسد، جزء من العضلة يتأثر، وده اللي بيحصل في الجلطة القلبية. عشان كده الحالة دي طارئة ومحتاجة إسعاف فوري."], ["أسباب بتتعب القلب", "من العوامل المعروفة اللي بتزود خطر أمراض القلب: التدخين، وضغط الدم المرتفع، والسكر، وارتفاع الدهون الضارة، والخمول، والوزن الزايد. وده كلام معروف في الطب. ومعظمها ممكن يتحكم فيه بالنظام والمتابعة. ولو عندك أعراض زي ألم في الصدر أو ضيق نفس شديد، روح للطوارئ ومتستناش."], ["ازاي نحافظ عليه", "الحركة المنتظمة، والأكل المتوازن، والنوم الكافي، وعدم التدخين، وقياس الضغط والسكر بانتظام، كلها حاجات بتفيد القلب. ومفيش نصيحة واحدة تناسب الكل، فالمتابعة مع طبيب هي الأساس خصوصا لو فيه تاريخ عائلي لمشاكل القلب."], ["حجم النبضة", "في كل نبضة، البطين الأيسر بيدفع كمية من الدم للشريان الأورطي. الكمية دي بتسمى حجم الضربة. لو ضربتها في عدد النبضات في الدقيقة، بتطلع كمية الدم اللي القلب بيضخها في الدقيقة. وفي الراحة بتكون بضعة لترات في الدقيقة للبالغ، وتزيد كتير مع المجهود. القيم الدقيقة بتختلف من شخص لشخص."], ["الدم نفسه", "الدم مش سائل واحد، فيه بلازما وخلايا حمراء بتحمل الأكسجين بفضل بروتين اسمه الهيموجلوبين، وخلايا بيضا للمناعة، وصفائح للتجلط. الخلايا الحمراء بتكون أغلب خلايا الدم، وبتفضل في الدورة شهور قبل ما الجسم يتخلص منها ويصنع جديدة. وفقر الدم بيحصل لما قدرة الدم على حمل الأكسجين تقل."], ["مسار ورقة الدم", "لو تابعنا الدم من البطين الأيسر، بيطلع في الشريان الأورطي، وبعدين في شرايين أصغر للمخ والذراعين والكلى والأمعاء والرجلين، وبعدين شعيرات، وبعدين أوردة صغيرة ثم كبيرة، لحد ما يوصل للوريدين الكبيرين ويدخل الأذين الأيمن. الرحلة دي بتاخد حوالي دقيقة في الحالة العادية، لكن الرقم بيتغير حسب النشاط."], ["الكلى والكبد والرئة", "الدم بيعدي على أعضاء بتنقيه وتظبط تركيبه. الكلى بتفلتره وبتتخلص من الفضلات والمية الزايدة. والكبد بيعالج مواد ويخزن ويصنع بروتينات. والرئة بتخلص الدم من ثاني أكسيد الكربون وتدي الأكسجين. وده بيوضح إن الدورة مش بس نقل، لكن كمان تنقية وتنظيم."], ["تخطيط القلب", "جهاز تخطيط القلب بيحط أقطاب على الجلد بتلتقط الإشارات الكهربية الصغيرة للقلب. الشكل اللي بيظهر فيه موجات ليها أسماء، كل موجة بتمثل مرحلة من النبضة. الطبيب بيقرأ الشكل ويعرف لو في اضطراب في النبض أو مشكلة في التوصيل. هو فحص بسيط وآمن وغير مؤلم."], ["الإيكو والسماعة", "الطبيب بيسمع الصوت بالسماعة الطبية. وفيه فحص بالموجات فوق الصوتية اسمه الإيكو بيظهر صورة حية للقلب وهو بينبض، وبيورّي حجم الغرف وحركة الصمامات. الموجات فوق الصوتية بتتحرك وترتد من الأنسجة، والجهاز بيحولها لصورة. وهو آمن ومش بيستخدم إشعاع."], ["منظم ضربات القلب", "لو الجهاز الكهربي الطبيعي للقلب ضعيف أو مش منتظم، ممكن يتزرع جهاز صغير اسمه منظم ضربات القلب. بيراقب النبض، ولو بطأ أكتر من اللازم، بيبعت نبضة كهربية صغيرة تحفز القلب. الأجهزة الحديثة صغيرة وذكية، وطبيب القلب بيتابعها بانتظام."], ["الجلطات والقسطرة", "لو شريان تاجي اتسد، فيه إجراء اسمه القسطرة: أنبوب رفيع بيتوصل للشريان عن طريق وعاء دموي، وبيفتح الانسداد وممكن يحط دعامة صغيرة تثبّت الشريان مفتوح. ده من الإجراءات اللي أنقذت ناس كتير، لكن تحديد الحالة والعلاج بيكون من الطبيب المختص، وسرعة الوصول للمستشفى مهمة جدا."], ["الخلاصة", "الخلاصة: القلب مضخة عضلية بأربع غرف وصمامات. الجانب الأيمن بيبعت الدم للرئتين ياخد أكسجين، والجانب الأيسر بيضخه لكل الجسم. إشارة كهربائية بتنظم النبض، والجسم بيغير سرعته حسب احتياجك. والحفاظ عليه بيبدأ بنمط حياة صحي ومتابعة طبية."]], "f": ["القلب عضلة فيها أربع غرف: أذينين وبطينين", "الدم بيطلع من القلب في شرايين ويرجع له في أوردة", "الدورة الدموية فيها دورتين: رئوية وجسمية", "الشرايين بتشيل الدم من القلب والأوردة بترجعه", "الأرقام الطبية الدقيقة بتختلف من شخص لشخص ومعلومات الفيديو للثقافة العامة مش للتشخيص"], "c": "جسم الإنسان", "dur": "7 دقايق ونص", "tot": 453, "st": [0, 29, 48, 68, 89, 108, 126, 149, 167, 186, 201, 219, 236, 256, 275, 289, 310, 330, 350, 367, 386, 402, 418, 438], "w": 1057}, {"n": 35, "t": "المناعة والتطعيمات: جسمك بيحارب الميكروبات ازاي؟", "e": "Immune System and Vaccines", "h": "جسمك فيه جيش بيتعرف على الميكروبات الغريبة ويقاومها. والتطعيم بيدرب الجيش ده من غير ما تتعب بالمرض نفسه.", "sc": [["جيش بتبقاش شايفه", "كل يوم جسمك بيقابل بكتيريا وفيروسات وفطريات من الهوا والأكل واللمس. أغلبها ما بتتعبكش، لأن فيه جهاز كامل شغال في الخلفية بيتعرف عليها ويتخلص منها. ولما تحصل عدوى فعلا، الجهاز ده بيدخل المعركة. التطعيمات فكرتها إنها تدرب الجهاز ده قبل ما تقابل الميكروب الحقيقي. والفيديو ده للمعرفة العامة، والقرار الطبي بتاخده مع طبيبك."], ["الخط الأول", "أول خط دفاع هو الحواجز: الجلد، والأغشية المخاطية في الأنف والحلق، وحمض المعدة، والدموع. دي بتمنع الميكروبات من الدخول أصلا. الجلد سليم بيعمل حاجز قوي. ولو الميكروب عدى الحواجز دي، بيقابل الخط التاني."], ["المناعة الفطرية", "لما ميكروب يدخل، خلايا في الدم والأنسجة بتتعرف عليه بسرعة بعلامات عامة مش بتتغير. بعض الخلايا بتبلع الميكروب وتهضمه. والجسم بيطلق إشارات بتسبب التهاب: احمرار وسخونة وانتفاخ، لأن الدم بيروح بكمية أكبر للمكان ومعاه خلايا مناعية. وده رد فعل سريع لكنه مش متخصص لميكروب معين."], ["الحرارة والتعب", "لما تعيا بالأنفلونزا مثلا، الحرارة والتعب جزء من رد فعل جسمك مش بس من الفيروس. بعض مواد المناعة بتخلي المخ يرفع درجة الحرارة، وبيتعب الجسم عشان يوفر طاقة للمعركة. الحرارة الخفيفة ممكن تكون جزء من الدفاع، لكن الحرارة العالية ولا بتقل لازم تتابع مع طبيب."], ["المناعة المكتسبة", "لو العدوى استمرت، بيدخل الخط التاني: المناعة المكتسبة. دي متخصصة. فيها خلايا اسمها اللمفاوية، وأهم نوعين: خلايا بي وخلايا تي. وكل خلية بتتعرف على قطعة معينة من الميكروب اسمها المستضد. وبتعدي وقت لحد ما تتجهز، عشان كده أول مرة بتتعب فيها."], ["الأجسام المضادة", "خلايا بي بتنتج بروتينات اسمها أجسام مضادة. كل جسم مضاد بيتعرف على مستضد معين ويلزق فيه، فيمنع الميكروب من إصابة الخلايا، ويعلم الخلايا المناعية الأخرى تتخلص منه. وبتفضل بعض الأجسام المضادة في الدم لفترة، وبتتكون خلايا ذاكرة."], ["خلايا تي", "خلايا تي نوعين أساسيين: مساعدة بتنسق المعركة، وقاتلة بتدمر الخلايا اللي اتصابت بالفيروس. ده مهم لأن الفيروس بيعيش جوه الخلايا، فالأجسام المضادة لوحدها مش كفاية. ولذلك الجهاز المناعي بيحتاج الاتنين."], ["الذاكرة المناعية", "بعد ما العدوى تخلص، بتفضل خلايا ذاكرة. لو نفس الميكروب رجع، الجسم بيعرفه بسرعة ويرد بقوة أكبر قبل ما تحس بأعراض كتير. ده سبب إن بعض الأمراض بتصيبك مرة واحدة غالبا. لكن بعض الفيروسات بتتغير زي الأنفلونزا، فالمناعة القديمة ممكن ما تتعرفش عليها كويس."], ["فكرة التطعيم", "التطعيم بيستغل الذاكرة دي. بيعرض الجسم لحاجة بتشبه الميكروب من غير ما تسبب المرض الحقيقي، فالجسم يكون أجسام مضادة وخلايا ذاكرة. لما يقابل الميكروب الحقيقي بعد كده، يكون مستعد. وده بيقلل فرصة المرض أو شدته."], ["أنواع التطعيمات", "فيه أنواع كتير: ميكروب ضعيف حي، أو ميكروب مقتول، أو جزء من الميكروب زي بروتين على سطحه، أو معلومات وراثية بتخلي خلايا الجسم تصنع جزء بروتين غير ضار. الأنواع بتختلف في طريقة التصنيع وعدد الجرعات، لكن الفكرة واحدة: تعريف الجهاز المناعي على المستضد."], ["ليه الجرعات المنشطة", "بعض التطعيمات بتتاخد في كذا جرعة. الجرعة الأولى بتعمل رد فعل أولي، والجرعات التالية بتقوي الذاكرة وتطول مدة الحماية. ومع الوقت المناعة ممكن تقل في بعض التطعيمات، فبتحتاج جرعة منشطة. والجداول بتحددها الجهات الصحية."], ["الأعراض بعد التطعيم", "ممكن تحس بألم في مكان الحقنة أو تعب بسيط أو حرارة خفيفة بعد التطعيم. دي علامة إن الجهاز المناعي اشتغل، وغالبا بتروح بسرعة. الأعراض الخطيرة نادرة جدا، والجهات الصحية بتراقبها. ولو ظهر عندك رد فعل شديد، تواصل مع طبيب."], ["مناعة القطيع", "لما نسبة كبيرة من الناس تتحصن، العدوى بتلاقي صعوبة في الانتشار، وده بيحمي كمان ناس مش قادرين ياخدوا التطعيم، زي الرضع أو أصحاب بعض الأمراض. النسبة المطلوبة بتختلف من مرض لمرض حسب سرعة انتشاره."], ["الاختبار والمراجعة", "التطعيمات الجديدة بتتجرب على مراحل، بمجموعات متزايدة، وبعدين بتراجعها جهات تنظيمية قبل الاعتماد، وبعدها بيستمر رصد الأعراض الجانبية. والأحسن تاخد معلوماتك من مصادر صحية رسمية، وتسأل طبيبك عن حالتك."], ["الخلايا البيضا", "الدم فيه أنواع كتير من الخلايا البيضا. فيه خلايا بتبلع الميكروبات، وخلايا بتفرز مواد، وخلايا بتتعرف على الغريب. وعدد وأنواع الخلايا البيضا في تحليل الدم بيعطي الطبيب مؤشرات عن وجود عدوى أو التهاب. بس الأرقام لازم تتفسر مع الأعراض والفحص."], ["الغدد اللمفاوية", "الغدد اللمفاوية في الرقبة والإبط والفخذ مراكز بتتجمع فيها خلايا المناعة وبتتفلتر فيها السوائل. لما بتعيا، ممكن تحس بانتفاخ الغدد، لأنها بتنشط وتنتج خلايا أكتر. غالبا ده طبيعي مع العدوى، لكن لو الانتفاخ استمر فترة طويلة أو معاه أعراض تانية لازم تعرض نفسك على طبيب."], ["نخاع العظم والغدة الزعترية", "خلايا المناعة بتتصنع في نخاع العظم. خلايا بي بتنضج هناك، وخلايا تي بتنضج في الغدة الزعترية اللي قريبة من القلب وبتكون نشيطة في الطفولة. أثناء النضج، الجسم بيتخلص من الخلايا اللي ممكن تهاجم أنسجة الجسم نفسه، وده جزء من التحكم في المناعة الذاتية."], ["لما المناعة تغلط", "أحيانا المناعة بتشتغل غلط. في الحساسية بتتصرف بقوة تجاه مادة غير ضارة زي حبوب اللقاح. وفي أمراض المناعة الذاتية بتهاجم أنسجة الجسم. وفي ضعف المناعة بتضعف عن مقاومة العدوى. وكل حالة ليها أسبابها وعلاجها، وبتحتاج طبيب."], ["الحمى والالتهاب", "الحمى والالتهاب جزء من الرد المناعي، لكنهم ممكن يبقوا مؤذيين لو زادوا. عشان كده الأطباء بيعالجوا بعض الحالات بخافضات الحرارة أو مضادات الالتهاب. والمهم تعرف إن الأعراض مش دايما عدو، هي أحيانا علامة إن الجسم بيقاوم."], ["المضادات الحيوية والفيروسات", "المضادات الحيوية بتقتل البكتيريا أو بتمنع نموها، لكنها ما بتعالجش الفيروسات. أغلب نزلات البرد والأنفلونزا فيروسية. استخدام المضاد الحيوي من غير داعي بيزود مقاومة البكتيريا، وده مشكلة صحة عامة. فالأفضل إن الطبيب هو اللي يقرر لو في حاجة لمضاد."], ["تاريخ التطعيم", "من أقدم الأمثلة تجارب في القرن الثامن عشر على الجدري، لما لاحظ طبيب إن اللي أصيبوا بجدري الأبقار بيحموا من الجدري البشري. ومن بعدها اتطورت التطعيمات، ومرض الجدري اتأعلن القضاء عليه عالميا في أواخر السبعينيات. وده من أكبر نجاحات الصحة العامة."], ["متابعة الأمان", "بعد اعتماد التطعيم، جهات الصحة بتجمع بلاغات عن الأعراض بعده وتحللها لتشوف لو فيه علاقة حقيقية. التحليل ده مستمر، وممكن يؤدي لتحديث التوصيات. وده جزء من منظومة الأمان. ولو عندك قلق بخصوص تطعيم معين، الأحسن تسأل طبيبك أو مركز صحي موثوق."], ["الخلاصة", "الخلاصة: جسمك فيه حواجز ومناعة سريعة ومناعة متخصصة بأجسام مضادة وخلايا ذاكرة. التطعيم بيعرف الجهاز ده على المستضد من غير المرض الحقيقي، فيكون مستعد لو قابله. وده بيقلل المرض والانتشار. وتفاصيل حالتك الشخصية مكانها الطبيب."]], "f": ["الجهاز المناعي بيتعرف على الميكروبات ويقاومها", "فيه مناعة فطرية سريعة وغير متخصصة ومناعة مكتسبة متخصصة وليها ذاكرة", "التطعيم بيعرض الجسم لجزء ضعيف أو غير فعال من الميكروب أو لتعليمات لصنعه، عشان يكون ذاكرة مناعية", "التطعيمات بتمر باختبارات ومراجعات قبل ما تتعتمد", "المعلومات للثقافة العامة، والقرار الطبي مع الطبيب"], "c": "جسم الإنسان", "dur": "6 دقايق ونص", "tot": 385, "st": [0, 23, 37, 56, 75, 93, 109, 122, 141, 156, 174, 189, 205, 220, 232, 249, 269, 287, 303, 318, 335, 352, 370], "w": 898}, {"n": 36, "t": "التشفير وHTTPS: ازاي بياناتك بتفضل سرية على الإنترنت؟", "e": "HTTPS and Encryption", "h": "لما بتكتب كلمة السر على موقع، البيانات بتعدي على أجهزة كتير. التشفير هو اللي بيخليها كلام مش مفهوم لأي حد في النص.", "sc": [["الرسالة في الطريق", "لما تبعت رسالة أو تدخل كلمة سر، بياناتك بتعدي على راوتر بيتك وشركة الإنترنت وأجهزة كتير في الطريق. لو البيانات كانت مكتوبة عادي، أي حد على الطريق يقدر يقراها. عشان كده بنستخدم التشفير. في الفيديو ده هنفهم إزاي المتصفح والموقع بيتفقوا على سر مشترك، من غير ما يتقابلوا قبل كده، وإيه معنى القفل اللي في المتصفح وإيه اللي مش بيعمله."], ["معنى التشفير", "التشفير هو تحويل معلومة مفهومة لشكل مش مفهوم، بطريقة رياضية، وعلشان ترجعها لازم مفتاح. من غير المفتاح، الشكل المشفر ملوش معنى. زي قفل: أي حد يشوفه، لكن مفيش حد يفتحه من غير المفتاح. وفيه خوارزميات متفق عليها عالميا بتتعمل بشكل علني، وأمانها بيعتمد على سرية المفتاح مش على سرية الطريقة."], ["التشفير بمفتاح واحد", "النوع الأول اسمه التشفير المتماثل. نفس المفتاح بيشفر وبيفك. سريع جدا وفعال للبيانات الكبيرة. لكن فيه مشكلة: إزاي الطرفين يتفقوا على المفتاح من غير ما حد يسمعه؟ لو بعته على الإنترنت مكشوف، أي حد يقدر ياخده. فاحتاجنا طريقة تانية."], ["مفتاح عام وخاص", "الحل هو التشفير غير المتماثل. كل طرف عنده زوج مفاتيح: عام وخاص. المفتاح العام ممكن تعلنه للكل. أي حاجة تتشفر بيه ما تتفكش إلا بالمفتاح الخاص المطابق، اللي بيفضل سري عند صاحبه. فأي حد يقدر يبعتلك رسالة مشفرة بمفتاحك العام، وإنت بس اللي تفتحها."], ["ليه مش نستخدمه لكل حاجة", "التشفير بمفتاح عام وخاص أبطأ بكتير. فبنستخدمه بس في بداية الاتصال، عشان يتم الاتفاق على مفتاح واحد مشترك وسري. وبعدها الاتصال كله بيكمل بالتشفير السريع بالمفتاح المشترك ده. دي الفكرة الأساسية في HTTPS."], ["المصافحة", "أول ما المتصفح يتصل بموقع بـHTTPS، بيحصل اللي اسمه مصافحة. المتصفح يقول للموقع إيه طرق التشفير اللي يدعمها. الموقع يختار ويبعت شهادته. وبعدين الطرفين يتفقوا على مفتاح مشترك للجلسة، بطريقة رياضية متفق عليها، من غير ما المفتاح نفسه يتبعت مكشوف."], ["الشهادة", "الموقع بيبعت شهادة رقمية فيها اسم الموقع ومفتاحه العام، وموقعة من جهة موثوقة اسمها هيئة إصدار الشهادات. المتصفح عنده قائمة بالجهات الموثوقة. لو الشهادة موقعة من جهة موثوقة، ومتطابقة مع اسم الموقع، يثق إنك بتكلم الموقع الصحيح مش حد منتحل."], ["القفل في المتصفح", "القفل بيعني إن الاتصال بينك وبين الموقع مشفر، وإن الشهادة سليمة. لكن مش بيعني إن الموقع نفسه موثوق أو آمن. موقع نصب ممكن يكون عنده قفل كمان. القفل بيحمي الطريق مش النية. فتأكد من العنوان بالحرف قبل ما تدخل بياناتك."], ["ماذا يحمي التشفير", "التشفير بيحمي المحتوى من أي حد في الطريق: واي فاي عام مثلا، أو شركة الإنترنت. فلو حد بيراقب الشبكة، هيشوف بيانات مشفرة. لكن ممكن لسه يعرف اسم الموقع اللي بتتصل بيه، وحجم البيانات تقريبا. والخصوصية الكاملة محتاجة أكتر من HTTPS."], ["الهاش وكلمات السر", "المواقع المحترمة ما بتخزنش كلمة السر زي ما هي. بتخزن بصمة رياضية ليها اسمها هاش. الهاش دالة في اتجاه واحد: سهل تحسب الهاش من الكلمة، وصعب جدا ترجع للكلمة من الهاش. لما تدخل كلمة السر، الموقع يحسب هاشها ويقارنه بالمخزن. فحتى لو سرقوا القاعدة، مش هيلاقوا الكلمات بشكل مباشر."], ["ليه الكلمة القوية مهمة", "اللي بيسرق هاشات ممكن يجرب كلمات كتير ويحسب هاشها ويقارن. الكلمات الشائعة بتتكسر بسرعة. فكلمة طويلة وفريدة لكل موقع بتصعب الموضوع. ومدير كلمات السر بيساعدك تحافظ على كلمات مختلفة. والتحقق بخطوتين بيضيف طبقة حماية."], ["الهجمات الشائعة", "أكتر حاجة بتحصل مش كسر التشفير، لكن خداع الناس: صفحات مزيفة بتطلب كلمة السر، أو رسائل تتظاهر إنها من بنك. التشفير ما بيحميش لو إنت اديت بياناتك للموقع الغلط. عشان كده الانتباه للعنوان وعدم الضغط على روابط مشبوهة أهم من أي تقنية."], ["تشفير الرسائل", "بعض تطبيقات المراسلة بتستخدم تشفير من طرف لطرف. معناه إن الرسالة بتتشفر على جهازك وما بتتفكش إلا على جهاز المستلم، والخدمة نفسها ما تقدرش تقرأها. ده مختلف عن التشفير العادي اللي بيحمي الطريق بس. وبيختلف من تطبيق لتطبيق في التفاصيل."], ["الحواسيب الكمية", "بتتكلم أخبار عن حواسيب كمية ممكن تكسر بعض أنواع التشفير الحالية في المستقبل. الباحثين شغالين على خوارزميات جديدة مقاومة لده. لسه مفيش داعي للذعر، لكن الصناعة بتستعد."], ["طول المفتاح", "قوة التشفير بتتأثر بطول المفتاح. المفتاح الأطول معناه عدد احتمالات أكبر بكتير لازم المهاجم يجربها. التشفير المتماثل الحديث بيستخدم مفاتيح طولها مئة وثمانية وعشرين بت أو مئتين وست وخمسين، وده عدد احتمالات فلكي مستحيل تجريبه كله بالقوة الغاشمة بالتقنيات الحالية. عشان كده المهاجمين بيدوروا على نقاط ضعف تانية: البرمجيات، والبشر، وكلمات السر الضعيفة."], ["تبادل المفاتيح", "فيه طريقة رياضية ذكية بتسمح لطرفين يتفقوا على سر مشترك من خلال قناة مكشوفة. كل طرف بيحسب قيمة من عنده ويبعتها، والطرفين بيدمجوا القيمة المستلمة مع سرهم الخاص، فيوصلوا لنفس النتيجة. اللي بيراقب القناة بيشوف القيم المتبادلة بس، ومش هيقدر يحسب السر بسهولة. الفكرة دي أساس الاتصال الآمن من غير لقاء سابق."], ["الشهادات والسلسلة", "الشهادة الرقمية مش بتتوقع مباشرة من هيئة رئيسية دايما. فيه سلسلة: شهادة الموقع وقعتها هيئة وسيطة، والوسيطة شهادتها وقعتها هيئة جذرية موجودة في قائمة المتصفح الموثوقة. المتصفح بيتتبع السلسلة لحد ما يوصل لجذر يعرفه. لو أي حلقة غلط أو منتهية الصلاحية، بيظهر تحذير."], ["تحذير الشهادة", "لما المتصفح يظهر لك تحذير إن الاتصال غير خاص، ده معناه إن حاجة في الشهادة مش مظبوطة: ممكن منتهية، أو اسم الموقع مختلف، أو الجهة مش موثوقة، أو في احتمال تدخل في الطريق. في أغلب الأحيان بيكون خطأ إعدادات من صاحب الموقع، لكن ما تتجاهلش التحذير وتدخل بيانات حساسة."], ["التوقيع الرقمي", "التوقيع الرقمي بيستخدم المفتاح الخاص: صاحب المفتاح يوقع على بيانات بالمفتاح الخاص، وأي حد يتأكد من التوقيع بالمفتاح العام. ده بيثبت إن البيانات جاية من صاحب المفتاح ومتغيرتش. بيتستخدم في الشهادات وتحديثات البرامج والمعاملات الإلكترونية. وهو غير التشفير، لأنه بيثبت الأصل مش بيخفي المحتوى."], ["التحقق بخطوتين", "حتى لو كلمة السر اتسرقت، التحقق بخطوتين بيطلب عامل تاني: كود من تطبيق أو رسالة أو مفتاح أمان فعلي. بعض الطرق أقوى من غيرها: الرسايل النصية ممكن تتحول لجهاز المهاجم في حالات معينة، والتطبيقات ومفاتيح الأمان أقوى. تفعيله على الحسابات المهمة، زي البريد والبنك، من أهم خطوات الحماية."], ["الواي فاي العام", "الشبكات العامة المفتوحة مش مشفرة بين جهازك والراوتر. HTTPS بيحمي أغلب المحتوى حتى هناك، لكن المخاطر موجودة: شبكة مزيفة بنفس الاسم، أو محاولات لتحويلك لصفحة مزيفة. الأفضل تتجنب إدخال بيانات حساسة على شبكات عامة، أو تستخدم اتصال البيانات في الموبايل، وتتأكد من اسم الشبكة الحقيقي."], ["شبكة VPN", "الـVPN بينشئ نفق مشفر بين جهازك وسيرفر الخدمة. ده بيخفي اللي بتعمله عن شبكة الواي فاي اللي متصل بيها، ويخفي عنوان IP عن المواقع. لكن مزود الـVPN نفسه بيقدر يشوف حركتك، فلازم تثق فيه. وهو مش بيحميك من الفيروسات ولا من الاحتيال. فهو أداة مفيدة في حالات معينة، مش حل سحري."], ["الخلاصة", "الخلاصة: HTTPS بيجمع تشفير بمفتاح عام وخاص للاتفاق على سر، وتشفير سريع بمفتاح مشترك لباقي الاتصال، وشهادات تتأكد من هوية الموقع. القفل معناه اتصال مشفر مش موقع مضمون. وأقوى حماية بتجمع التقنية مع انتباهك وكلمات سر قوية."]], "f": ["التشفير بيحول البيانات لشكل غير مفهوم من غير مفتاح", "HTTPS هو HTTP مع طبقة تشفير", "التشفير المتماثل بيستخدم نفس المفتاح للتشفير وفك التشفير", "التشفير غير المتماثل بيستخدم مفتاح عام ومفتاح خاص", "الشهادات بتساعد المتصفح يتأكد من هوية الموقع"], "c": "أمان", "dur": "7 دقايق", "tot": 429, "st": [0, 26, 47, 64, 83, 97, 114, 131, 148, 165, 186, 201, 219, 236, 248, 270, 293, 311, 332, 351, 372, 391, 413], "w": 1000}, {"n": 37, "t": "الكهربا بتوصل لبيتك ازاي من المحطة؟", "e": "Electricity from Power Plant to Your Home", "h": "الكهربا اللي بتنور اللمبة ما اتولدتش في بيتك. اتولدت في محطة، ومشيت مئات الكيلومترات، وعدت على محولات كتير قبل ما توصل.", "sc": [["من الضغطة للمحطة", "بتضغط زرار اللمبة فتنور في نفس اللحظة. الكهربا ما كانتش مخزنة في السلك. هي بتتولد في محطة ممكن تبعد مئات الكيلومترات، في نفس الوقت تقريبا اللي بتستهلكها فيه. الشبكة كلها بتشتغل زي جهاز واحد ضخم، ومهمتها إنها توازن كل لحظة بين اللي بيتولد واللي بيتستهلك. تعالى نمشي مع الكهربا من المحطة لحد بيتك."], ["التوليد", "أغلب المحطات بتشتغل بنفس المبدأ: حاجة بتلف مولد. المولد بيحول الحركة لكهربا. اللي بيلف المولد ممكن يكون بخار من حرق غاز أو وقود، أو بخار من مفاعل نووي، أو مية نازلة في سد، أو هوا في توربين رياح. وفي الطاقة الشمسية بالخلايا، الكهربا بتتولد مباشرة من الضوء من غير مولد دوار."], ["المولد", "جوه المولد مغناطيس بيلف جوه ملفات سلك نحاس. حركة المغناطيس قدام الملفات بتولد فيها جهد كهربي بالحث الكهرومغناطيسي. الجهد بيتغير اتجاهه مع دوران المغناطيس، فبينتج تيار متردد. في مصر تردد الشبكة خمسين دورة في الثانية، يعني التيار بيغير اتجاهه خمسين مرة كل ثانية في الدورة الكاملة."], ["ليه متردد مش مستمر", "التيار المتردد بيسهل تغيير جهده بالمحولات. وده مهم جدا لنقل الكهربا. في الأيام الأولى للكهربا كان فيه جدل بين النظامين، والمتردد انتصر في الشبكات الكبيرة بسبب سهولة النقل لمسافات طويلة."], ["ليه نرفع الجهد", "أسلاك النقل بتسخن وتضيع طاقة كحرارة. الفقد ده بيعتمد على التيار: كل ما التيار زاد، الفقد زاد بشكل كبير. القدرة هي الجهد في التيار. فلو رفعنا الجهد، نقدر ننقل نفس القدرة بتيار أقل، ويقل الفقد. عشان كده بيتم نقل الكهربا بجهد عالي جدا."], ["المحول", "المحول جهاز بسيط من غير أجزاء متحركة. فيه ملفين حوالين قلب حديد. التيار المتردد في الملف الأول بيولد مجال مغناطيسي متغير، فبيتولد جهد في الملف التاني. نسبة عدد لفات الملفين بتحدد هل الجهد يزيد ولا يقل. محول رافع في المحطة، ومحولات خافضة في الطريق."], ["خطوط الضغط العالي", "الأبراج الكبيرة اللي بتشوفها على الطرق بتشيل خطوط الجهد العالي. الأسلاك بعيدة عن بعضها وعن الأرض لأن الجهد العالي ممكن يعمل قفزة كهربية في الهوا. وبتتعلق على عوازل من الزجاج أو السيراميك أو البلاستيك. وبيتفحصوا بانتظام."], ["محطات التحويل", "الخطوط بتوصل لمحطات تحويل بتخفض الجهد على مراحل. من جهد عالي جدا لجهد عالي، ولجهد متوسط للمناطق، وفي الآخر محول في الشارع يخفضه لجهد البيوت. المحول اللي قريب منك على الأرض أو على عمود هو الخطوة الأخيرة."], ["جهد البيت", "في بيوت مصر الجهد 220 فولت بتردد خمسين. من المحول لعداد بيتك بسلك، وبعده لوحة التوزيع فيها قواطع بتحمي الدوائر. القاطع بيفصل لو التيار زاد عن حد معين، لحماية الأسلاك من السخونة والحريق."], ["العداد", "العداد بيقيس الطاقة اللي استهلكتها بالكيلووات ساعة. الكيلووات ساعة هي استهلاك جهاز قدرته ألف وات لمدة ساعة. بعض العدادات الحديثة رقمية، وبعضها بتتقرا عن بعد أو بتتشحن مسبقا. الفاتورة بتتحسب حسب الاستهلاك والشرائح."], ["التوازن اللحظي", "مشكلة الكهربا إنها صعب تتخزن بكميات كبيرة، فلازم الإنتاج يساوي الاستهلاك تقريبا طول الوقت. لو الاستهلاك زاد فجأة، لازم محطة تزود إنتاجها. مركز التحكم بيراقب الشبكة وبيشغل أو يقلل المحطات. وده شغل مستمر 24 ساعة."], ["الأحمال", "في أوقات الذروة، زي الصيف بالظهر لما التكييفات تشتغل، الاستهلاك بيزيد جدا. والشبكة بتحتاج قدرة كفاية لتغطيه. ومن حلول الشبكات: محطات تشتغل وقت الذروة بس، وربط شبكات الدول ببعض، وتخزين في بطاريات أو سدود تضخ المية."], ["الطاقة المتجددة", "الشمس والرياح بتتغير مع الطقس، ودي أحد التحديات في الشبكات. لو الشمس غابت أو الرياح وقفت، لازم مصدر تاني يعوض. فبتتجمع المتجددة مع التخزين ومحطات مرنة وشبكات قوية."], ["الانقطاع", "لما الكهربا بتقطع، ممكن يكون عطل في محول أو خط، أو حمل زايد، أو صيانة. القواطع في الشبكة بتفصل الجزء المعطل عشان ما يتأثرش الباقي. وفرق الصيانة بتصلح الخلل. وفي بعض الأحيان بيحصل فصل مقصود لحماية النظام."], ["الأمان", "الكهربا الخطرة ما بتتلمسش. أسلاك الضغط العالي ممكن تصعق من غير لمس مباشر لو قربت منها. ولا تحاول تتعامل مع أسلاك الشارع أو المحولات، وأي سلك واقع لازم تبلغ عنه. وفي البيت، سلك الأرضي والقواطع التفاضلية بتحميك."], ["التيار الثلاثي الأطوار", "الكهربا في محطات النقل والمصانع بتكون ثلاثية الأطوار: تلات موجات متداخلة بفارق زمني ثابت. ده بيدي قدرة مستمرة وسلسة وبيستخدم موصلات أقل بالنسبة للقدرة. موتورات المصانع الكبيرة بتحب النوع ده. والبيوت غالبا بتاخد طور واحد من الثلاثة، أو تلاتة في بعض الحالات."], ["القدرة والطاقة", "القدرة بتقاس بالوات: هي معدل استهلاك الطاقة. والطاقة بتقاس بالوات ساعة. لمبة ١٠٠ وات شغالة ١٠ ساعات بتستهلك ١ كيلووات ساعة. غسالة أو تكييف قدرتهم أكبر فبيرفعوا الفاتورة أسرع. وفهم الفرق بيساعدك تعرف أي جهاز بيستهلك أكتر وتوفر."], ["الكابلات تحت الأرض", "في المدن، الكابلات غالبا بتتمد تحت الأرض لأنها أأمن وأجمل، لكنها أغلى وإصلاحها أصعب. بتتعزل بمواد بتتحمل الجهد، وبتتحمي من المية. الأسلاك العلوية أرخص وأسهل في الفحص لكنها معرضة للرياح والطيور والطقس."], ["التردد والاستقرار", "تردد الشبكة لازم يفضل ثابت قرب خمسين هرتز في مصر. لو الاستهلاك زاد أكتر من الإنتاج، التردد بينزل. لو العكس، بيعلى. مراكز التحكم بتراقب التردد كمؤشر على توازن الشبكة. وأي انحراف كبير بيشغل أنظمة حماية بتفصل أجزاء للحفاظ على الباقي."], ["الربط بين الدول", "شبكات الكهربا في دول كتير متوصلة ببعض بخطوط ربط. ده بيسمح بتبادل الكهربا: دولة عندها فائض تبيع لدولة محتاجة. وبيزود الاستقرار لأن مصادر التوليد بتتنوع. مصر عندها ربط مع جيرانها، وبتتنفذ مشروعات ربط جديدة."], ["الجهد والأمان في البيت", "سلك الأرضي بيوصل جسم الأجهزة بالأرض. لو حصل تسريب كهربي في الجهاز، التيار بيروح للأرض بدل ما يمر في جسمك، والقاطع بيفصل. القاطع التفاضلي بيحس بالفرق الصغير في التيار ويفصل بسرعة. دول من أهم عناصر الأمان في أي تمديد كهربي."], ["الحمل الزايد", "كل سلك بيتحمل تيار معين. لو وصلت أجهزة كتير على نفس الفيشة أو الدايرة، التيار بيزيد، والسلك بيسخن. القاطع بيفصل قبل ما يحصل خطر، لكن لو القاطع غير مناسب أو الأسلاك قديمة، ممكن يحصل حريق. فتجنب الوصلات المتعددة المحملة، واستعن بفني كهرباء معتمد."], ["كفاءة الاستخدام", "أجهزة موفرة للطاقة، ولمبات LED، وضبط التكييف على درجة معتدلة، وفصل الأجهزة اللي مش مستخدمة، كلها بتقلل الاستهلاك. وتقليل الاستهلاك وقت الذروة بيخفف الحمل على الشبكة. حتى التفاصيل الصغيرة بتفرق لما تتجمع عند ملايين الناس."], ["الخلاصة", "الخلاصة: مولد يلف بقوة بخار أو مية أو رياح، يولد كهربا، محول يرفع الجهد، خطوط ضغط عالي تنقلها بفقد قليل، محولات تخفض الجهد على مراحل لحد 220 فولت في بيتك. والشبكة بتوازن لحظيا بين الإنتاج والاستهلاك. شبكة معقدة لكنها بتشتغل بمبادئ فيزيائية بسيطة."]], "f": ["المحطات بتولد كهربا بمولدات بتلف بالمية أو البخار أو الرياح", "الجهد بيترفع للنقل لمسافات طويلة عشان يقلل الفاقد", "المحولات بترفع وتخفض الجهد في التيار المتردد", "الشبكة لازم توازن بين الإنتاج والاستهلاك لحظيا", "جهد البيوت في مصر 220 فولت"], "c": "طاقة", "dur": "6 دقايق ونص", "tot": 397, "st": [0, 23, 45, 64, 77, 96, 114, 130, 146, 160, 174, 189, 204, 216, 232, 248, 266, 282, 296, 313, 328, 345, 363, 378], "w": 926}, {"n": 38, "t": "الغواصة بتغطس وتطلع ازاي؟", "e": "How Submarines Dive and Surface", "h": "الغواصة تقدر تغطس وتطفو وتفضل في العمق اللي تحبه. السر في التحكم في وزنها بالنسبة للمية اللي بتزيحها.", "sc": [["سؤال أرخميدس", "السفينة الحديد بتطفو والمسمار الحديد بيغرق. ليه؟ لأن الطفو مش بيعتمد على نوع المادة بس، لكن على كمية المية اللي الجسم بيزيحها. الغواصة بتستغل نفس القاعدة، لكنها تقدر تغير وزنها عشان تطفو أو تغطس أو تثبت في العمق. وده اللي هنفهمه خطوة خطوة، ومعاه إزاي بتتحمل ضغط المية."], ["مبدأ أرخميدس", "أي جسم في سائل بتتأثر عليه قوة رفع لفوق، تساوي وزن السائل اللي زاحه. لو وزن الجسم أكبر من قوة الرفع، بيغرق. لو أقل، بيطفو. لو متساوي، بيفضل معلق. الجسم الكبير المجوف زي السفينة بيزيح مية كتير بالنسبة لوزنه، فبيطفو."], ["خزانات الصابورة", "الغواصة فيها خزانات كبيرة اسمها خزانات الصابورة. لما تعوز تغطس، بتفتح فتحات وتدخل فيها مية، فيزيد وزن الغواصة. ولما تعوز تطلع، بتطرد المية بهوا مضغوط، فيقل وزنها وتطفو. والتحكم في كمية المية بيخلي الغواصة قريبة من الطفو المحايد."], ["الغطس", "في الغطس، المية بتدخل الخزانات، والهوا بيخرج من فتحات. الغواصة تنزل. ولو فضلت بنفس الوزن، هتنزل لحد ما تقابل القاع أو يتحكم فيها الطاقم. فبيتحكم الطاقم في الميل بواسطة زعانف أفقية تتحرك مثل أجنحة، وبتساعد في توجيه الغواصة لتحت أو لفوق أثناء الحركة."], ["التحكم الدقيق", "للتحكم الدقيق في العمق، فيه خزانات صغيرة اسمها خزانات التعديل. بتتحرك فيها المية بالكميات الصغيرة عشان تظبط الوزن بدقة. وفيه خزانات توازن بتتحكم في توزيع الوزن بين المقدمة والمؤخرة، فتحافظ على اتزان الغواصة أفقيا."], ["الطلوع", "للطلوع، الغواصة بتضخ هوا مضغوط في خزانات الصابورة فتطرد منها المية. وزنها يقل وبتطفو. في الطوارئ، ممكن تتطرد المية بسرعة. بعد ما تطلع، الهوا الطبيعي بيبقى بدل المية، وبتفضل طافية على السطح."], ["الضغط", "كل عشرة أمتار تقريبا في عمق مية البحر، الضغط بيزيد بمقدار ضغط جوي واحد تقريبا. فعلى عمق مئات الأمتار، الضغط بيكون عشرات أضعاف الضغط على السطح. جسم الغواصة لازم يتحمله، من غير ما يتهرس. عشان كده بيتعمل من صلب قوي وبشكل أسطواني، لأن الشكل ده بيوزع الضغط بشكل متساوي."], ["الجسم المزدوج", "في كتير من الغواصات فيه جسمين: جسم داخلي قوي بيتحمل الضغط وفيه الطاقم والمعدات، وجسم خارجي خفيف بيدي الشكل الانسيابي وفيه خزانات الصابورة. المية بتدخل بين الجسمين، لكن الجسم الداخلي بيفضل جاف وبضغط عادي."], ["الحركة", "الغواصة بتتحرك بمروحة بتدفع المية لورا. في الغواصات التقليدية المروحة بتتحرك بموتور كهربي بيشتغل على بطاريات كبيرة عند الغطس، وتشحن البطاريات بمولد ديزل لما تكون على السطح أو قريبة منه. الغواصات النووية بتستخدم مفاعل بيولد حرارة وبخار وكهربا، فمش محتاجة هوا للاحتراق."], ["الهوا للتنفس", "الطاقم محتاج أكسجين، وبيطلعوا ثاني أكسيد كربون. الغواصة فيها أجهزة تنتج أكسجين، من الكهرباء بتحلل المية مثلا، وتنقي الهوا من ثاني أكسيد الكربون. وده بيخليها تفضل غاطسة لفترات طويلة. المدة بتعتمد على الإمدادات الغذائية وقدرة الطاقم."], ["الرؤية والملاحة", "تحت المية مفيش GPS، لأن الإشارات الراديو ما بتخترقش المية بكفاءة. الغواصة بتستخدم نظام ملاحة داخلي بيحسب موقعها من حركتها، وساعات بتطلع قريب من السطح تاخد إحداثيات. والرؤية بتتم بصريا بمنظار على السطح، أو بالسونار."], ["السونار", "السونار بيبعت موجات صوت في المية، وبيستقبل الصدى اللي بيرتد من الأجسام. من الوقت اللي بياخده الصدى بيحسب المسافة. الصوت بيتحرك في المية أسرع وأبعد من الضوء والراديو، عشان كده هو الأداة الأساسية للغواصات. وفيه سونار سلبي بيسمع بس، وفيه نشط بيبعت ويستقبل."], ["غواصات البحث", "مش كل الغواصات عسكرية. فيه غواصات علمية بتتنزل لأعماق كبيرة عشان تستكشف قاع البحر والحياة فيه. وفيها نوافذ سميكة وجسم كروي لأن الكرة أفضل شكل لتحمل الضغط. وبعضها بلا طاقم وبتتحكم فيها من السفينة."], ["الحوادث والأمان", "الغواصة بيئة مغلقة وخطرة، فيها أنظمة أمان كتير: أبواب محكمة، وإنقاذ، وطرق للطوارئ. والتدريب كبير. والتصميم بيفترض الاحتمالات الأسوأ. ومع كده حصلت حوادث تاريخية، وكل واحدة بتغير معايير التصميم."], ["الصابورة والوزن", "في الغواصة، نسبة صغيرة من وزنها هي اللي بتتحكم في طفوها. المصممين بيحسبوا وزن كل قطعة بدقة، وأي معدات تتضاف أو يتشال منها بتحتاج إعادة توازن. والطاقم بيتحرك بحذر عشان ما يغيرش توازن الغواصة. الدقة دي لازم تتحافظ عليها طول الرحلة."], ["الكثافة والملوحة والحرارة", "كثافة مية البحر بتتغير مع الملوحة ودرجة الحرارة وبين طبقات العمق. لو الغواصة عدت من طبقة لطبقة أكتر كثافة، قوة الطفو بتتغير شوية، فتحتاج تعديل. وفي بعض الأماكن في البحر، طبقات المية بتتصرف بتأثير على انتشار الصوت، وده بيأثر على السونار."], ["الشكل الانسيابي", "شكل الغواصة الحديث شبه الدمعة أو السيجار عشان يقلل مقاومة المية وهي مغمورة. المقاومة في المية أكبر بكتير من الهوا، وبتزيد بسرعة مع السرعة. عشان كده الغواصات بتتحرك بسرعات معتدلة نسبيا مقارنة بالطيارات، والسرعة العالية بتستهلك طاقة كبيرة وبتعمل ضوضاء."], ["الهدوء", "الضوضاء أعدى أعداء الغواصة العسكرية، لأنها بتكشف مكانها بالسونار. فبتتصمم بمحركات هادئة، وتثبيت المعدات على حوامل بتمتص الاهتزاز، ومراوح بشكل خاص بتقلل الفقاعات. والطاقم بيتحرك بهدوء. وده سبب إن بناء غواصة هادئة تقنية صعبة ومحمية."], ["الأسطح والبرج", "فوق الغواصة برج فيه المناظير والهوائيات. على السطح، بتخرج المناظير لرؤية السطح، وهوائيات للاتصال. الاتصال بالراديو بيحتاج هوائي فوق الماء، أو بترددات منخفضة جدا بتخترق المية لمسافات قصيرة. فالغواصة غالبا بتتصل في أوقات محددة."], ["الإنقاذ", "في حالات الطوارئ، للغواصات أنظمة إنقاذ: غرف بتسمح بخروج الطاقم، وبعض الدول عندها مركبات إنقاذ بتتصل بفتحة الغواصة المعطلة. التدريب على الخروج من العمق جزء من تدريب الطواقم. ومع ذلك أفضل إنقاذ هو الوقاية وتصميم آمن وصيانة صارمة."], ["الحياة جوه الغواصة", "الطاقم بيعيش في مساحة ضيقة لأسابيع أو شهور. فيه نوبات عمل، وطعام معبأ، ومعدات لإنتاج المية العذبة من مية البحر. الإضاءة الصناعية بتحاول تحاكي الليل والنهار. والتحمل النفسي والتدريب عنصر أساسي في اختيار الطاقم."], ["استخدامات سلمية", "الغواصات مش للحرب فقط. غواصات الأبحاث بتدرس الشعاب والكائنات في الأعماق، وبتساعد في مد الكابلات وفحص حطام السفن والبنية التحتية تحت المية. المركبات غير المأهولة بتخفف المخاطر وبتصل لأعماق أكبر. وبتفتح الباب لفهم أفضل للمحيطات."], ["الخلاصة", "الخلاصة: الغواصة بتغير وزنها بإدخال مية أو هوا في خزانات الصابورة لتغطس أو تطفو، وبتتحكم في العمق بخزانات التعديل والزعانف. جسمها القوي بيتحمل ضغط المية، وبتتحرك بمروحة وتتنفس بأجهزة، وتتنقل وترى بالسونار. فكرة أرخميدس مدعومة بهندسة دقيقة."]], "f": ["الطفو بيعتمد على الفرق بين وزن الجسم ووزن المية اللي بيزيحها (مبدأ أرخميدس)", "الغواصة فيها خزانات صابورة بتتملي مية أو هوا", "الضغط بيزيد مع العمق، فجسم الغواصة لازم يتحمله", "الغواصات التقليدية بتحتاج تطلع أو تستخدم شنوركل لتجديد الهوا، والنووية بتختلف", "الأرقام التشغيلية الدقيقة معظمها سرية"], "c": "هندسة", "dur": "6 دقايق", "tot": 374, "st": [0, 21, 38, 54, 72, 87, 101, 122, 136, 154, 170, 185, 203, 218, 230, 248, 265, 282, 297, 312, 328, 343, 358], "w": 872}, {"n": 39, "t": "بطارية الليثيوم بتشحن وتفضي ازاي؟", "e": "How Lithium-Ion Batteries Work", "h": "في موبايلك وعربية كهربية بطارية بتخزن طاقة كيميائية وتطلعها كهربا. وسرها في أيونات ليثيوم بتروح وتيجي بين قطبين.", "sc": [["طاقة في علبة صغيرة", "موبايلك بيشتغل ساعات من غير كابل. العربية الكهربية بتمشي مئات الكيلومترات. الطاقة دي كلها متخزنة في بطارية. البطارية مش بتخزن كهربا زي ما بنتخيل، هي بتخزن طاقة كيميائية، وبتحولها لكهربا وقت الاستخدام. وفي بطاريات الليثيوم أيون، اللي بتتحرك أيونات ليثيوم بين قطبين. تعالى نفهم الحركة دي."], ["المكونات الأساسية", "البطارية فيها قطب سالب غالبا من الجرافيت، وقطب موجب من مركب فيه ليثيوم ومعادن تانية، وبينهم فاصل رقيق بيمنع التلامس المباشر، وكل ده غارق في سائل اسمه الإلكتروليت بيسمح بمرور الأيونات. والدايرة الخارجية بتوصل القطبين."], ["الأيونات والإلكترونات", "الذرة لما تفقد إلكترون بتتحول لأيون موجب. أيونات الليثيوم صغيرة وخفيفة، وبتقدر تدخل وتخرج من تركيب المواد في الأقطاب. أما الإلكترونات فبتمر من خلال الدايرة الخارجية، وده التيار اللي بيشغل جهازك."], ["التفريغ", "وقت الاستخدام، أيونات الليثيوم بتخرج من القطب السالب، وبتعدي من خلال الإلكتروليت للقطب الموجب. وفي نفس الوقت الإلكترونات بتتحرك من السالب للموجب في الدايرة الخارجية، فبتشغل جهازك. لما تكون أغلب الأيونات وصلت للموجب، البطارية تكون فاضية."], ["الشحن", "لما بتوصل الشاحن، الطاقة الخارجية بتجبر الأيونات ترجع للقطب السالب، والإلكترونات كمان. فبيتخزن الليثيوم تاني بين طبقات الجرافيت، والبطارية تتشحن. العملية دي بتتكرر مئات المرات، فتسمى دورات الشحن."], ["ليه الليثيوم", "الليثيوم أخف معدن، وبيدي طاقة كبيرة بالنسبة لوزنه، وده مهم للأجهزة المحمولة والعربيات. بطاريات الليثيوم بتخزن طاقة أكتر في نفس الوزن بالمقارنة بأنواع قديمة زي الرصاص والنيكل."], ["ليه البطارية بتضعف", "مع كل دورة شحن، بيحصل تغيرات صغيرة في المواد: بتتكون طبقات على سطح القطب، وبعض الأيونات بتتحبس وما بترجعش. فسعة البطارية بتقل تدريجيا. عمر البطارية بيتقاس بعدد دورات الشحن اللي بتحتفظ فيها بنسبة كبيرة من سعتها."], ["الحرارة", "الحرارة العالية بتسرّع التفاعلات الجانبية اللي بتبلي البطارية. والبرد الشديد بيبطأ حركة الأيونات فبتقل القدرة مؤقتا، والشحن في البرد الشديد ممكن يضر. عشان كده الأحسن تحافظ على موبايلك بعيد عن الحرارة الشديدة، وكتير من العربيات الكهربية فيها نظام تبريد وتسخين للبطارية."], ["الشحن السريع", "الشحن بتيار كبير بيخلي الأيونات تتحرك بسرعة، لكن بيطلع حرارة أكتر. عشان كده الأنظمة بتبدأ بتيار عالي ولما البطارية تمتلئ بتقل التيار تدريجيا، وغالبا بتبطئ آخر نسبة. ولو الجهاز سخن، بيقلل سرعة الشحن لحماية البطارية."], ["نظام إدارة البطارية", "في كل بطارية دايرة ذكية بتراقب الجهد والحرارة والتيار. هي بتمنع الشحن الزايد أو التفريغ العميق، وبتوازن الخلايا لو فيه أكتر من خلية، وبتفصل البطارية لو حصلت مشكلة. من غيرها البطارية تبقى أخطر وأقصر عمرا."], ["المخاطر", "البطارية فيها طاقة كبيرة في حيز صغير. لو اتلفت ميكانيكيا أو حصل ماس كهربي داخلي أو اتسخنت جدا، ممكن تسخن بسرعة وتولع. حوادث الاشتعال نادرة بالنسبة لعدد البطاريات، لكنها بتحصل. فاستخدم شواحن أصلية، ولا تستخدم بطارية منتفخة أو متضررة."], ["نصايح للعمر", "الأحسن ما تسيبش البطارية تفضي تماما كل مرة ولا تفضل على مية في المية فترات طويلة جدا، وتبعد عن الحرارة الشديدة. كتير من الأنظمة بتوفر خيار تحديد حد أقصى للشحن للمحافظة على العمر. والنصايح دي بتختلف قليلا من جهاز لجهاز، فشوف توصيات الشركة."], ["في العربيات الكهربية", "بطارية العربية عبارة عن آلاف الخلايا الصغيرة أو خلايا كبيرة متوصلة ببعض في حزم. ونظام إدارة بيراقبها. وكمان فيها استرجاع الطاقة في الفرملة. والمدى بيتأثر بالسرعة والحرارة وأسلوب القيادة."], ["التدوير والمواد", "البطاريات فيها مواد قيمة زي الليثيوم والكوبالت والنيكل. إعادة التدوير مهمة بيئيا واقتصاديا، لكن لسه بتتطور. ومتخلصش من البطاريات في الزبالة العادية، لأنها ممكن تسبب حرائق وتلوث."], ["الكاثود والأنود", "في الشحن والتفريغ بيتبدل اسم القطب الموجب والسالب بالنسبة للأنود والكاثود، لكن الفكرة العملية إن في قطب بيخزن الليثيوم لما البطارية مشحونة، وهو الجرافيت غالبا، وقطب بيستقبله لما تتفرغ. اختيار مواد القطب الموجب بيحدد خصائص البطارية: سعة، وأمان، وعمر، وتكلفة. وفيه كيميائيات مختلفة بتستخدم في موبايلات وعربيات وأجهزة تخزين."], ["الفاصل", "الفاصل رقيق جدا ومسامي: بيسمح للأيونات بالمرور وبيمنع الإلكترونات والتلامس المباشر بين القطبين. لو الفاصل اتخرق أو انصهر، القطبين بيلمسوا بعض ويحصل ماس كهربي داخلي. عشان كده جودة الفاصل من أهم عناصر أمان البطارية، وبعض التصميمات فيها فواصل بتتحمل حرارة أعلى."], ["الإلكتروليت", "الإلكتروليت سائل أو جل فيه ملح ليثيوم مذاب في مذيبات عضوية. بيسمح للأيونات بالانتقال لكنه قابل للاشتعال، وده سبب مخاطر الحريق. الأبحاث شغالة على إلكتروليتات صلبة أكتر أمانا، وبطاريات الحالة الصلبة موضوع تطوير نشط، لكن لسه في طور الانتشار."], ["السعة والجهد", "جهد خلية الليثيوم أيون حوالي ثلاثة ونص فولت في المتوسط، وبيتغير مع مستوى الشحن. السعة بتتقاس بالأمبير ساعة أو بالواط ساعة. لتحقيق جهد أعلى، بتتوصل خلايا على التوالي، ولسعة أكبر بتتوصل على التوازي. بطارية العربية الكهربية آلاف الخلايا في توليفة كبيرة."], ["نسبة الشحن", "نسبة البطارية اللي بتشوفها تقدير مش قياس مباشر. النظام بيحسبها من الجهد والتيار اللي دخل وخرج وتاريخ البطارية. عشان كده ممكن تتقلب أحيانا أو تنزل فجأة من نسبة معينة، خصوصا مع بطارية قديمة أو في البرد. ومعايرة النسبة بتحصل مع الاستخدام."], ["ليه البرد بيفضي البطارية", "في البرد، التفاعلات الكيميائية بتبطأ والمقاومة الداخلية بتزيد، فالبطارية بتدي طاقة أقل مؤقتا. ممكن موبايلك يقول عندك ثلاثين في المية ويطفي في الجو البارد. لما يدفى، بيرجع جزء من الطاقة. العربيات الكهربية بتسخن البطارية، لكن ده بيستهلك جزء من المدى."], ["أنواع أخرى", "فيه بطاريات ليثيوم حديد فوسفات أكتر أمانا وبتتحمل دورات شحن أكتر، لكن كثافة طاقتها أقل. وفيه أنواع بتستخدم نيكل وكوبالت أعلى في كثافة الطاقة. وفيه بطاريات صوديوم أيون قيد التطوير كبديل. التنوع ده بيخلي الاختيار حسب الاستخدام والسعر."], ["البطاريات والشبكة", "البطاريات الكبيرة بتتستخدم كمان لتخزين كهربا الشبكة، خصوصا من الشمس والرياح، وتفريغها وقت الذروة. ده بيساعد على استقرار الشبكة. التحدي هو التكلفة وعمر البطارية وسلامة التركيبات الكبيرة. ومع ما بتنخفض الأسعار، دورها بيزيد."], ["الخلاصة", "الخلاصة: في بطارية الليثيوم أيون، الأيونات بتتحرك بين قطب سالب وموجب خلال الإلكتروليت، والإلكترونات بتمشي في الدايرة الخارجية وتشغل جهازك. الشحن بيعكس الحركة. الحرارة والشحن الزايد بيقصروا العمر، ونظام إدارة بيحمي البطارية. وفهم الفكرة بيساعدك تحافظ على بطاريتك."]], "f": ["البطارية فيها قطب موجب وقطب سالب وإلكتروليت", "في التفريغ الأيونات بتتحرك من القطب السالب للموجب والإلكترونات بتمر في الدايرة الخارجية", "في الشحن بتتحرك الأيونات للاتجاه العكسي", "الحرارة العالية والشحن الزايد بيضروا البطارية", "بطاريات الليثيوم ليها عمر محدود بعدد دورات الشحن"], "c": "طاقة", "dur": "6 دقايق", "tot": 363, "st": [0, 20, 35, 48, 63, 75, 87, 102, 120, 135, 150, 167, 185, 198, 209, 230, 248, 264, 282, 300, 317, 333, 347], "w": 848}, {"n": 40, "t": "تحلية مية البحر بتتم ازاي؟", "e": "How Seawater Desalination Works", "h": "مية البحر مالحة ومينفعش نشربها. فيه طرق تفصل الملح عن المية، وكلها محتاجة طاقة. تعالى نفهم الطريقتين الأشهر.", "sc": [["مية كتير ومينفعش", "الأرض مغطاها مية، لكن أغلبها مالحة. لو شربت مية بحر، الملح الزايد يضر جسمك ويخليك تعطش أكتر. ومع ذلك دول كتير في العالم، ومنها دول عربية، بتعتمد على تحلية مية البحر لشرب الناس. هنشوف إزاي بتتفصل الأملاح، ومين الطرق الأساسية، ولماذا التحلية مكلفة، وإيه اللي بيحصل في الملح اللي بيتفصل."], ["نسبة الملح", "مية البحر فيها حوالي ثلاثة ونص في المية من وزنها أملاح، أغلبها ملح الطعام. المية الحلوة اللي بنشربها فيها كمية أملاح قليلة جدا. فهدف التحلية يقلل الأملاح لمستوى آمن للشرب والزراعة. ونسبة الملح بتختلف من بحر لبحر."], ["الطريقة الأولى: التقطير", "أقدم فكرة: سخن المية لحد ما تتبخر. البخار نقي لأن الأملاح بتفضل في المية. وبعدين برّد البخار فيرجع مية حلوة. ده بيحصل في الطبيعة لما الشمس تبخر البحر والغيوم تتكون. في محطات التحلية الحرارية بيتم ده بكميات ضخمة."], ["التحسين بالمراحل", "التسخين لدرجة الغليان بياخد طاقة كبيرة. عشان كده المحطات بتستخدم أكتر من مرحلة، وبتخفض الضغط عشان المية تغلي في درجة حرارة أقل. وبتستخدم حرارة البخار اللي بيتكثف في تسخين المية الجديدة، فبتوفر طاقة. الفكرة اسمها التبخير متعدد المراحل أو التأثيرات."], ["الطريقة الثانية: الأغشية", "الطريقة الأكتر انتشارا النهاردة هي التناضح العكسي. نبدأ بالتناضح الطبيعي: لو فصلنا مية حلوة عن مية مالحة بغشاء رقيق، المية الحلوة بتتحرك ناحية المالحة. التناضح العكسي بيعكس الاتجاه: بنضغط المية المالحة بضغط عالي جدا، فتتدفع المية خلال الغشاء وتسيب أغلب الملح."], ["الغشاء", "الغشاء فيه ثقوب صغيرة جدا بتسمح لجزيئات المية تعدي، وبتمنع أيونات الملح وأغلب الشوائب. الأغشية بتتلف على شكل أسطوانات لزيادة مساحة السطح، وفي محطة واحدة فيه عدد كبير منها. والضغط المطلوب بيكون عالي، وده بيستهلك الجزء الأكبر من الطاقة."], ["المعالجة الأولية", "مية البحر فيها طحالب ورمل وعوالق. لو دخلت الغشاء مباشرة هتسده. فبتعدي على مراحل ترشيح، وأحيانا بتتضاف مواد تساعد على تجميع الشوائب. وبعد التحلية، بتتعالج المية تاني وتتضاف لها أملاح ومعادن بكميات صغيرة، وتتعقم قبل ما توصل للناس."], ["استرجاع الطاقة", "المية المركزة الخارجة من الغشاء لسه تحت ضغط عالي. في المحطات الحديثة بيتم استرجاع جزء كبير من الطاقة دي بأجهزة خاصة بتنقل الضغط للمية الجديدة الداخلة. ده بيخفض استهلاك الكهربا جدا مقارنة بالأيام الأولى."], ["المحلول المركز", "التحلية بتنتج مية حلوة ومية مالحة جدا اسمها المحلول المركز أو الأجاج. لو اتصرف في البحر بدون ترتيب، ممكن يأثر على الكائنات القريبة لأنه أملح وأحيانا أسخن. فالمحطات بتصممه عشان يتخفف بسرعة بنوع من الناشرات، وبتراقب البيئة."], ["الطاقة والتكلفة", "التحلية بتستهلك طاقة، وده سبب تكلفتها العالية بالنسبة لمصادر المية العادية. لكن في الأماكن اللي مفيهاش بدائل، هي الحل. وفيه اتجاه لتشغيل المحطات بالطاقة الشمسية أو الرياح لتقليل البصمة الكربونية."], ["في مصر", "مصر عندها نهر النيل كمصدر رئيسي، لكن مع زيادة السكان بقى فيه اهتمام بالتحلية، خصوصا في المدن الساحلية وسيناء والساحل الشمالي. بتتبني محطات جديدة، لكن تفاصيل أحجامها وتكاليفها بتتغير، فمنتحدثش عن أرقام محددة هنا."], ["اختيار الطريقة", "التناضح العكسي غالبا أوفر في الطاقة، فهو الأكتر انتشارا. والتقطير ممكن يبقى مناسب لما يكون فيه حرارة مهدرة من محطة كهربا قريبة، أو لو المية شديدة التلوث. والاختيار بيعتمد على الموقع والتكلفة وجودة المية الداخلة."], ["الصيانة", "الأغشية بتتسخ وبتحتاج تنظيف دوري وتغيير بعد سنين. والأنابيب بتتآكل بسبب الملح. محطات التحلية محتاجة صيانة مستمرة وفريق متخصص. وده جزء من التكلفة التشغيلية."], ["بدائل وتوفير", "التحلية مش هي الحل الوحيد. معالجة مياه الصرف وإعادة استخدامها، وتقليل الفاقد في الشبكات، وترشيد الاستخدام، وتقنيات الري الحديثة، كلها بتخفف الحاجة للمية الجديدة. وده بيقلل الضغط على التحلية."], ["الضغط الأسموزي", "عشان التناضح العكسي يشتغل، لازم الضغط المسلط يكون أعلى من الضغط الأسموزي لمية البحر، وده بيعتمد على تركيز الملح. كل ما الملح أكتر، الضغط المطلوب أعلى. ولذلك مية البحر بتحتاج ضغط أعلى من المياه الجوفية الأقل ملوحة. وده بيفسر ليه تحلية المياه قليلة الملوحة أرخص."], ["المياه قليلة الملوحة", "في أماكن كتير في مصر والعالم فيه مياه جوفية فيها ملوحة أقل من البحر، وبتحتاج معالجة بنفس التقنية بتكلفة وطاقة أقل. التحلية مش بس لمية البحر. والاختيار بيعتمد على المصدر المتاح والتكلفة ومعايير الجودة."], ["جودة المية", "المية المنتجة لازم تتطابق مع معايير مياه الشرب: ملوحة منخفضة، وخالية من الميكروبات، وبمستوى معين من المعادن والأس الهيدروجيني. بعد التحلية، بتتعدل المية عشان ما تأكلش المواسير، وتتعقم بالكلور أو غيره. وبتتحاليل بصفة مستمرة."], ["البصمة الكربونية", "التحلية بتستهلك طاقة كبيرة، فلو الطاقة جاية من وقود أحفوري، ينتج عنها انبعاثات. عشان كده فيه توجه لربط محطات التحلية بالطاقة الشمسية والرياح. كمان تحسين الأغشية وأجهزة استرجاع الطاقة بيقلل الاستهلاك. وكل ما التكنولوجيا اتحسنت، التكلفة والطاقة نزلت."], ["المياه المنتجة والشبكة", "المية المحلاة بتتوزع غالبا في شبكة المواسير العادية. جزء من المية بيضيع بالتسريب من الشبكة، وده فاقد بيقلل الاستفادة من التحلية. فتقليل التسريب بيكون أحيانا أرخص من إنتاج مية جديدة. والصيانة الدورية للشبكة جزء من الحل."], ["الري والصناعة", "مش كل المية لازم تتحلى لدرجة الشرب. بعض الاستخدامات الزراعية والصناعية ممكن تستخدم مية أقل تنقية بتكلفة أقل. توجيه المية حسب جودتها المطلوبة بيوفر تكلفة. وبيتم في بعض المشروعات."], ["الخزانات الاستراتيجية", "بعض المدن بتخزن المية المحلاة في خزانات كبيرة تكفي أيام، عشان لو المحطة وقفت للصيانة أو لعطل، الناس ما تتأثرش. التخزين الاستراتيجي جزء من الأمن المائي. وبيتم تخطيطه مع طاقة المحطات واحتياجات السكان."], ["مياه الصرف المعالجة", "معالجة مياه الصرف وإعادة استخدامها طريقة تانية لزيادة المتاح. بتعدي على مراحل ترشيح وتعقيم وأغشية، وتستخدم في الري أو الصناعة، وفي بعض الدول بعد معالجة متقدمة جدا حتى للشرب. ده بيقلل الاعتماد على مصادر جديدة ويكمل دور التحلية."], ["الخلاصة", "الخلاصة: مية البحر فيها أملاح كتير. التقطير بيبخر المية ويكثفها، والتناضح العكسي بيضغطها خلال غشاء بيمنع الأملاح. العمليتين بتستهلكا طاقة وبينتجوا محلول مركز لازم يتصرف بحذر. وفي الآخر المية بتتعالج وتتعقم وتوصل للناس. تحلية بتفيد، لكنها لازم تتوازن مع ترشيد الاستخدام."]], "f": ["مية البحر فيها نسبة أملاح عالية تقريبا 3.5% ومينفعش نشربها", "التناضح العكسي بيدفع المية تحت ضغط عالي خلال غشاء بيمنع معظم الأملاح", "التقطير بيسخن المية لحد ما تتبخر وتتكثف من غير أملاح", "التحلية بتستهلك طاقة كبيرة وبتنتج محلول ملحي مركز", "الأرقام الدقيقة بتختلف حسب المحطة"], "c": "طاقة ومياه", "dur": "6 دقايق", "tot": 357, "st": [0, 21, 37, 54, 71, 88, 105, 121, 136, 152, 165, 179, 194, 204, 217, 236, 251, 265, 282, 297, 309, 324, 340], "w": 834}, {"n": 41, "t": "الأرصاد الجوية بتتوقع الطقس ازاي؟", "e": "How Weather Forecasting Works", "h": "توقع الطقس مش تخمين. هو حسابات ضخمة على بيانات من الأقمار والمحطات، لكن الجو نظام معقد، فالتوقع بيبقى أدق قريب ومش أدق بعيد.", "sc": [["ليه بنسأل عن الطقس", "كل يوم بنسأل: هتمطر؟ هتسخن؟ الناس بتحتاج الطقس لأمور بسيطة زي اللبس، وأمور كبيرة زي الطيران والزراعة والإنذار من العواصف. وتوقع الطقس النهاردة أدق بكتير من زمان، بفضل الأقمار والكمبيوترات القوية. في الفيديو ده هنفهم إزاي بيتحسب التوقع، وليه أحيانا بيغلط، ومعنى نسبة احتمال المطر."], ["إيه هو الطقس", "الطقس هو حالة الجو في مكان ووقت معينين: حرارة وضغط ورطوبة ورياح وسحب وأمطار. أما المناخ فهو متوسط الطقس لفترة طويلة. الطقس بيتحرك بفعل الشمس اللي بتسخن الأرض بشكل غير متساوي، وبتتحرك الكتل الهوائية بسبب فرق الحرارة والضغط."], ["الضغط والرياح", "الهوا بيتحرك من منطقة ضغط عالي لمنطقة ضغط منخفض، وده اللي بنسميه رياح. مناطق الضغط المنخفض غالبا بتكون مرتبطة بصعود الهوا وتكوين السحب والمطر، ومناطق الضغط العالي بتكون غالبا طقس أهدى. وبسبب دوران الأرض، الرياح بتنحرف وتلف حوالين مراكز الضغط."], ["جمع البيانات", "عشان نتوقع، لازم نعرف حالة الجو دلوقتي. بيتم جمع بيانات من آلاف المحطات الأرضية، وسفن وطيارات، وبالونات بتتطلق تقيس الحرارة والرطوبة والضغط على ارتفاعات مختلفة، ورادارات بتتتبع المطر، وأقمار صناعية بتصور السحب وتقيس الحرارة من الفضاء."], ["الأقمار الصناعية", "الأقمار بتديك صورة شاملة. فيه أقمار ثابتة فوق نقطة معينة على خط الاستواء بتراقب نفس المنطقة بشكل مستمر، وأقمار بتلف حوالين الأرض في مدارات أقرب وبتغطي الأرض كلها. وبتقيس إشعاع من الأرض والسحب، وبيحولوه لمعلومات عن الحرارة والرطوبة."], ["الرادار", "رادار الطقس بيبعت موجات راديو بتنعكس على قطرات المطر. من قوة الإشارة المرتدة، بيعرف شدة المطر، ومن تغير الترددات بيعرف حركة القطرات. وده بيساعد في الإنذار القصير المدى للعواصف."], ["النموذج الرياضي", "أخذ البيانات ده بيتحط في نموذج رياضي بيمثل الغلاف الجوي بشبكة من نقط ثلاثية الأبعاد. المعادلات بتوصف حركة الهوا والحرارة والرطوبة وبتتحل خطوة بخطوة لحساب الحالة بعد دقائق، وبعدين تتكرر لحساب ساعات وأيام."], ["الكمبيوترات", "الحسابات دي ضخمة جدا، فبتتعمل على حواسيب عملاقة. كل ما الشبكة أدق، تفاصيل أكتر، وكل ما كانت أدق، الحسابات أكتر. وده من أسباب تحسن التوقعات مع تطور الحواسيب."], ["الفوضى", "الجو نظام حساس للظروف الابتدائية. غلطة صغيرة في القياس في البداية ممكن تكبر مع الوقت. ده ما بيعنيش إن التوقع مستحيل، لكنه بيحد من مدى التوقع الدقيق. في العموم، توقعات الأيام القليلة القادمة أدق بكتير من توقعات أسبوعين."], ["مجموعة نماذج", "عشان نتعامل مع عدم اليقين، الأرصاد بتشغل النموذج عدة مرات بظروف ابتدائية مختلفة قليلا. لو كل النتايج متفقة، التوقع واثق. لو مختلفة، التوقع أقل يقين. وده بيتحول لاحتمالات."], ["معنى نسبة المطر", "لما تسمع احتمال مطر سبعين في المية، ده مش معناه إن المطر هيغطي سبعين في المية من المنطقة. أغلب الأحيان معناه إن فيه احتمال كبير إن المطر يحصل في مكان ما في المنطقة في الفترة المحددة. والتفاصيل بتختلف حسب الجهة، لكن الفكرة إنه احتمال مش يقين."], ["التوقع المحلي", "النموذج بيدي صورة عامة، لكن الطقس المحلي بيتأثر بالتضاريس والبحر والمدن. فالخبراء بيعدلوا النتايج حسب خبرتهم وبيانات المنطقة. ولذلك في الساحل الشمالي مثلا ممكن يختلف الجو عن القاهرة وسط نفس اليوم."], ["الإنذارات", "للعواصف والرياح الشديدة والعواصف الترابية والحرارة العالية، بتصدر جهات الأرصاد إنذارات. الإنذار المبكر بيساعد ناس تاخد احتياطات. ولو صدر إنذار في منطقتك، اتبع تعليمات الجهات الرسمية."], ["تطبيقات الطقس", "التطبيقات اللي على موبايلك بتاخد بيانات من مراكز الأرصاد ونماذجها، وأحيانا بتدمج أكتر من مصدر. جودتها بتختلف، وبتختلف بين التطبيقات أحيانا في نفس المكان. ومصادر الجهات الرسمية بتكون مرجع أفضل في الإنذارات."], ["الجبهات", "الجبهة هي الحد الفاصل بين كتلتين هوائيتين مختلفتين في الحرارة والرطوبة. لما كتلة باردة تتقدم وتدفع كتلة دافئة لفوق، بتتكون سحب وأمطار غالبا، وبيحصل تغير سريع في الحرارة والرياح. الأرصاد بتتابع الجبهات دي على الخرايط لأنها من أهم أسباب تغير الطقس في أيام قليلة."], ["الرطوبة والسحب", "الهوا الدافئ بيشيل بخار مية. لما يطلع لفوق أو يبرد، البخار بيتكثف على ذرات دقيقة ويتكون قطرات صغيرة جدا، وده السحاب. لو القطرات كبرت وتجمعت بما يكفي، بتنزل مطر. وفي البرد الشديد في طبقات عالية بتتكون بلورات ثلج. نوع السحب بيدي إشارة عن الطقس القادم."], ["ليه الجو بيتغير بسرعة", "تأثير الشمس على الأرض بيختلف من مكان لمكان: الصحرا بتسخن بسرعة، والبحر بيسخن ببطء. الفرق في الحرارة بيحرك الهوا. وفي مصر، الرياح الشمالية على الساحل بتجيب رطوبة، وكتل هوا من الصحرا أحيانا بتجيب غبار وحرارة عالية. فتوقع الطقس محتاج فهم المنطقة."], ["العواصف الترابية", "في بعض الأيام الرياح الشديدة بتشيل تراب ورمل وتقلل الرؤية. الأرصاد بتتوقعها بمراقبة الرياح وحالة التربة وحركة الكتل الهوائية. العواصف دي ممكن تأثر على الطيران والقيادة وصحة ناس عندهم حساسية. وتعليمات الجهات الرسمية بتنصح بالبقاء في أماكن مغلقة ساعتها."], ["ازاي بنقيس الحرارة", "محطات الأرصاد بتقيس الحرارة في صندوق مخصوص بعيد عن أشعة الشمس المباشرة وعلى ارتفاع قياسي، عشان القراءات تبقى قابلة للمقارنة. الحرارة اللي ممكن تحس بيها في الشمس أو على الأسفلت أعلى من الرقم الرسمي، عشان كده الرقم الرسمي مش دايما اللي بتحسه."], ["الإحساس بالحرارة", "الإحساس بالحرارة بيعتمد على الرطوبة والرياح كمان. في الرطوبة العالية، عرقك ما بيتبخرش بسهولة فبتحس بحر أكتر. وفي رياح باردة، بتحس ببرودة أكتر من الرقم. بعض الأرصاد بتنشر مؤشرات بتجمع العوامل دي، وبتختلف طرق حسابها."], ["التغير المناخي والطقس", "المناخ هو الاتجاه الطويل، والطقس هو اليوم. لكن ارتفاع متوسط حرارة الأرض بيأثر على تكرار بعض الظواهر وشدتها، زي موجات الحر. الباحثين بيدرسوا العلاقة وبيربطوا حدث معين بالتغير المناخي بدراسات إحصائية، مش بحدث واحد. والتفاصيل علمية معقدة ومتجددة."], ["إزاي تستفيد", "شوف توقعات الساعة والأيام القادمة من مصدر موثوق، وانتبه لوقت الإنذارات. للتخطيط لرحلة أو فرح في الخارج، التوقع قبلها بيوم أو اتنين أدق بكتير من توقع قبلها بأسبوعين. وافتكر إن النسبة احتمال، فخد احتياطك لو كان القرار مهم."], ["الخلاصة", "الخلاصة: بيانات من محطات وأقمار ورادارات وبالونات بتتحط في نموذج رياضي بيحل معادلات الجو على حواسيب عملاقة. الجو حساس، فالتوقع القريب أدق من البعيد، والنتيجة بتتقدم كاحتمالات. فمعاك دلوقتي أدوات تعرف بيها ليه المطر بيتقال بنسبة مش بيقين."]], "f": ["التوقعات بتتحسب بنماذج رياضية للغلاف الجوي على كمبيوترات قوية", "البيانات بتتجمع من محطات أرضية وبالونات وأقمار صناعية ورادارات", "الدقة بتقل كل ما زادت مدة التوقع", "الجو نظام فوضوي: تغيير صغير في البداية ممكن يكبر", "توقعات المطر بتقول احتمال مش يقين"], "c": "علوم", "dur": "6 دقايق", "tot": 363, "st": [0, 19, 36, 53, 68, 84, 97, 111, 123, 139, 151, 171, 184, 195, 209, 228, 247, 265, 282, 300, 315, 331, 347], "w": 848}, {"n": 42, "t": "العربية ذاتية القيادة بتشوف وتقرر ازاي؟", "e": "How Self-Driving Cars Work", "h": "العربية ذاتية القيادة مش بتشوف بعين واحدة. بتجمع كاميرات ورادار وليدار وكمبيوتر، وبتقرر في أجزاء من الثانية.", "sc": [["مين بيسوق", "تخيل تركب عربية ومفيش حد ماسك الدركسيون. فكرة الخيال العلمي ده اتحولت لتجارب واقعية. لكن في الحقيقة لسه معظم العربيات التجارية بتقدم مساعدة للسائق، مش قيادة كاملة من غير تدخل. في الفيديو ده هنشوف إزاي العربية بتحس باللي حواليها، وإزاي بتقرر، وإيه اللي لسه صعب."], ["مستويات الأتمتة", "فيه مستويات لوصف مدى اعتماد العربية على نفسها. مستوى صفر: السائق يعمل كل حاجة. مستويات أولى وتانية: مساعدة زي الحفاظ على المسار والتحكم في السرعة، والسائق لازم يفضل منتبه. المستويات الأعلى: العربية تسوق نفسها في ظروف معينة، وفي الأخير قيادة كاملة في أي ظروف. وأغلب الموجود في الأسواق في المستويات الأقل."], ["العيون: الكاميرات", "الكاميرات بتتعرف على علامات الطريق والحارات والإشارات والمشاة والعربيات. هي رخيصة وبتدي تفاصيل كتيرة، لكنها بتتأثر بالضوء الضعيف والمطر والضباب والوهج. فمعظم الأنظمة مش بتعتمد عليها لوحدها."], ["الرادار", "الرادار بيبعت موجات راديو وبيستقبل انعكاسها. بيقيس المسافة وسرعة الأجسام القريبة، حتى في الضباب والمطر. ممتاز لتتبع العربيات اللي قدامك. لكنه مش دقيق في تحديد شكل الجسم وتفاصيله."], ["الليدار", "الليدار بيبعت نبضات ليزر آلاف المرات، وبيقيس الوقت اللي بتاخده تروح وترجع. منها بيبني خريطة ثلاثية الأبعاد من نقط حوالين العربية. ده بيديك شكل دقيق للمحيط. لكنه غالي نسبيا وممكن يتأثر بظروف جوية معينة، وبعض الشركات بتعتمد عليه وبعضها بتعتمد على الكاميرات أكتر."], ["الموجات فوق الصوتية", "في الأماكن القريبة زي الركنة، بتستخدم حساسات فوق صوتية بتبعت موجات صوت وتقيس الصدى. ده اللي بيطلع صوت الصفير لما تقرب من حاجز. مداها قصير لكنها رخيصة ومفيدة في السرعات المنخفضة."], ["تحديد الموقع", "العربية لازم تعرف مكانها بدقة. بتستخدم GPS وحساسات الحركة وخرائط تفصيلية، وبتطابق ما تشوفه بالحساسات مع الخريطة. الدقة المطلوبة أعلى من المطلوب في تطبيقات الخرايط العادية، لأنها لازم تعرف أنهي حارة هي فيها."], ["دمج الحساسات", "كل حساس ليه نقاط قوة وضعف. دمج الحساسات هو إن الكمبيوتر يجمع قراءاتهم ويطلع صورة موحدة. لو الكاميرا شافت جسم والرادار أكد المسافة، يزيد الاطمئنان. ولو اختلفوا، النظام لازم يقرر مين يثق فيه."], ["التعرف على الأجسام", "برامج الذكاء الاصطناعي بتتعلم من آلاف أو ملايين الصور تتعرف على الأجسام: عربية ودراجة وشخص ومخروط ومطب. لكن الشوارع بتفاجئ: كرة بتتدحرج، حد بيشاور بإيده، عمال طريق. الحالات النادرة هي أصعب تحدي."], ["التنبؤ بالحركة", "مش كفاية تعرف فين الأجسام دلوقتي. لازم تتوقع هتروح فين. الشخص اللي على الرصيف ممكن يعدي؟ العربية اللي جنبك هتغير الحارة؟ النظام بيحسب احتمالات لمسارات مختلفة، وبيختار قرار آمن."], ["التخطيط", "بعدين النظام يقرر المسار: أنهي حارة، وسرعة قد إيه، ومتى يفرمل أو يلف. لازم يحترم قواعد المرور ويكون مريح لراكبيه، يعني من غير فرملة مفاجئة. والتخطيط بيتجدد عشرات المرات في الثانية."], ["التحكم", "بعد القرار، بيتحول لأوامر للدركسيون والفرامل والبنزين أو الموتور. حلقات تحكم بتقارن اللي المفروض يحصل باللي بيحصل فعلا وتصحح. وده شبه اللي بيعمله السائق، بس بسرعة ودقة حسابية."], ["المشاكل الصعبة", "الجو السيئ، والطرق اللي مالهاش علامات واضحة، والتصرفات غير المتوقعة من السائقين والمشاة، والحالات النادرة. وكمان القرارات الأخلاقية والقانونية: مين المسؤول لو حصل حادث؟ دي مسائل بتتناقش وبتتحط لها قوانين."], ["دور السائق", "في الأنظمة اللي بتساعد، السائق لازم يفضل منتبه وإيده جاهزة. الاعتماد الزايد على النظام خطر. والأنظمة بتحتوي على أدوات بتراقب انتباه السائق. لازم تقرأ تعليمات عربيتك وتعرف حدود النظام."], ["المستقبل", "التقنية بتتحسن، وفيه تجارب لسيارات أجرة من غير سائق في بعض المدن، في مناطق محددة ومخططة. لكن التعميم على كل الطرق وكل الظروف لسه محتاج وقت وتطوير وقوانين."], ["الخرائط عالية الدقة", "كتير من أنظمة القيادة الذاتية بتعتمد على خرائط ثلاثية الأبعاد دقيقة جدا للطرق: حارات وإشارات ومطبات. العربية بتقارن اللي بتشوفه بالخريطة عشان تعرف موقعها بدقة سنتيمترات. إنشاء الخرائط دي وتحديثها مكلف، وده من أسباب إن بعض الأنظمة بتشتغل بس في مناطق محددة."], ["الذكاء الاصطناعي في الرؤية", "شبكات عصبية بتتدرب على أمثلة كتيرة تتعرف على الأجسام في صورة الكاميرا. التدريب بيحتاج أمثلة متنوعة: ليل ونهار ومطر وشوارع مختلفة. والنظام بيقدم نسبة ثقة لكل جسم. لو الثقة قليلة، بيتصرف بحذر أو بيطلب من السائق التدخل. التحدي هو إن النظام ممكن يغلط في حالات ما اتدربش عليها."], ["المحاكاة والاختبار", "الشركات بتختبر الأنظمة في محاكاة حاسوبية على مليارات الكيلومترات الافتراضية، وفي ميادين اختبار، وفي الطرق الحقيقية تحت رقابة. المحاكاة بتخلي تجرب مواقف خطرة من غير ضرر. لكن مفيش اختبار بيغطي كل مواقف الطريق، وده سبب الحذر في الانتشار."], ["الأمان السيبراني", "العربية المتصلة بالإنترنت ممكن تكون هدف لاختراق. فيه خطر لو حد سيطر على أنظمتها. عشان كده بتتصمم بطبقات أمان، وتتحدث بالبرمجيات بتوقيع رقمي، وتفصل الأنظمة الحرجة عن الترفيه. الأمان جزء أساسي من تصميم أي عربية حديثة."], ["السرعة اللحظية", "لازم القرار يتاخد في أجزاء من الثانية. العربية بسرعة تسعين كيلومتر في الساعة بتقطع حوالي خمسة وعشرين متر في الثانية. فأي تأخير في اكتشاف عائق بيتحول لمتر كتير. عشان كده الكمبيوتر داخل العربية قوي، وبيعالج بيانات حساسات بسرعة عالية."], ["التفاعل مع البشر", "السائق الآلي لازم يفهم إشارات البشر: نظرة سائق تاني، حركة إيد شرطي مرور، سلوك غير متوقع من مشاة. البشر بيتواصلوا بإشارات خفية، والآلات لسه بتتعلمها. وبرضه الناس بتتفاعل مع عربية من غير سائق بطرق مختلفة، وده بيأثر على القبول."], ["القانون والمسؤولية", "لو عربية فيها نظام مساعدة حصل لها حادث، من المسؤول؟ السائق ولا الشركة؟ الجواب بيختلف حسب القانون وحسب مستوى الأتمتة ونوع الخلل. دول كتير بتعدل قوانين المرور لتغطي الأنظمة دي. وده من أسباب إن الانتشار الواسع محتاج إطار قانوني واضح."], ["الفوايد المحتملة", "من الفوايد المتوقعة تقليل الحوادث الناتجة عن خطأ بشري زي التعب والشرود، ومساعدة كبار السن وذوي الإعاقة، وتحسين انسيابية المرور. لكن دي فوايد محتملة بتعتمد على نجاح التقنية، ومش مضمونة. وبتتقيم بالأرقام الفعلية مش بالوعود."], ["الخلاصة", "الخلاصة: كاميرات ورادار وليدار وحساسات تانية بتدي صورة للمحيط، والكمبيوتر بيدمجها ويتعرف على الأجسام ويتوقع حركتها ويخطط المسار ويتحكم في العربية. لسه فيه تحديات وحالات نادرة، وغالبا المتاح اليوم مساعدة للسائق مش بديل كامل عنه."]], "f": ["العربية بتستخدم حساسات: كاميرات ورادار وأحيانا ليدار", "الليدار بيستخدم نبضات ليزر لقياس المسافات وبناء خريطة ثلاثية الأبعاد", "الكمبيوتر بيدمج بيانات الحساسات (دمج الحساسات) ويتعرف على الأجسام ويتوقع حركتها ويخطط المسار", "مستويات الأتمتة بتتدرج من مساعدة السائق لقيادة كاملة، ومعظم العربيات التجارية اليوم مساعدة وليست قيادة كاملة", "السائق لازم ينتبه في الأنظمة اللي بتطلب كده"], "c": "تكنولوجيا", "dur": "6 دقايق", "tot": 364, "st": [0, 19, 41, 53, 65, 83, 96, 111, 125, 138, 151, 164, 176, 189, 201, 213, 231, 252, 268, 284, 300, 317, 334, 349], "w": 850}, {"n": 43, "t": "المد والجزر: القمر بيحرك البحر ازاي؟", "e": "Tides and the Moon", "h": "مستوى البحر بيعلى وينزل مرتين تقريبا كل يوم. السبب مش سحر، هو جاذبية القمر والشمس وحركة الأرض.", "sc": [["البحر بيعلى وينزل", "لو قعدت على شاطئ بالساعات، هتلاحظ إن المية بتقرب وتبعد. أحيانا بتوصل لمكان وبعدها بساعات بتبقى بعيدة. ده المد والجزر. ومن زمان الناس لاحظت إن الموضوع مرتبط بالقمر. في الفيديو ده هنفهم العلاقة، وليه فيه مدين في اليوم، وليه المد بيختلف من أسبوع لأسبوع، وليه بعض الأماكن فيها مد كبير وبعضها مد صغير."], ["جاذبية القمر", "الجاذبية قوة بتجذب الأجسام لبعض. كل ما الجسم أقرب، الجذب أقوى. القمر بيجذب الأرض ومنها مية المحيطات. الجانب القريب من القمر بيتجذب أكتر من الجانب البعيد، لأن المسافة مختلفة. الفرق ده في الجذب هو الأساس."], ["المد في الناحيتين", "منطقيا نتخيل إن بس الناحية اللي قدام القمر هي اللي فيها مد. لكن في الحقيقة فيه انتفاخ في الجانب المواجه للقمر وانتفاخ في الجانب البعيد. السبب إن الجذب على الجانب البعيد أضعف من الجذب على مركز الأرض، فالمية هناك بتتأخر نسبيا وبتتكوم. فتبقى الانتفاخات اتنين."], ["ليه مدين في اليوم", "الأرض بتلف حوالين نفسها كل يوم، يعني أي مكان على الشاطئ بيعدي على الانتفاخين في اليوم. يبقى مد عالي لما تعدي على كل واحد، وجزر لما تكون بينهم. لأن القمر بيتحرك في مداره، اليوم القمري أطول شوية من 24 ساعة، فالمد بيتأخر حوالي خمسين دقيقة كل يوم."], ["دور الشمس", "الشمس كمان بتجذب المحيطات لكن تأثيرها أقل، لأنها رغم ضخامتها بعيدة جدا. تأثير الشمس تقريبا نصف تأثير القمر في المد. لما الشمس والقمر والأرض في خط واحد، يتجمع التأثير."], ["المد الربيعي", "في أول الشهر القمري والبدر، الشمس والقمر والأرض بيكونوا في خط واحد تقريبا، فتأثيرهم بيتجمع والمد بيكون أعلى والجزر أوطى. دي اسمها المد الربيعي، رغم أن الاسم مالوش علاقة بفصل الربيع."], ["المد الميت", "في التربيع الأول والأخير للقمر، الشمس والقمر بيكونوا في زاوية قايمة، فتأثيرهم بيتعاكس جزئيا. المد بيكون أقل والجزر أقل. الفرق بين المد والجزر بيكون صغير."], ["مش كل الأماكن زي بعض", "المد في بعض الأماكن بيكون كبير جدا، وفي أماكن تانية صغير، وفي بعض الأماكن مد واحد في اليوم. السبب شكل الساحل وعمق البحر وحجم الحوض البحري. في البحر المتوسط، المد صغير بالنسبة للمحيطات، وفي البحر الأحمر كمان نسبيا صغير."], ["المصبات والخلجان", "في خلجان بتضيق تدريجيا، المية بتتجمع فيها وبترتفع أكتر. ده بيعمل مد عالي في بعض الأماكن حول العالم. وفيه أنهار بيدخلها المد وبيرفع منسوبها لمسافات داخل اليابسة."], ["التنبؤ بالمد", "المد من أكتر الظواهر الطبيعية اللي بنقدر نتنبأ بيها بدقة، لأن حركات الأرض والقمر والشمس معروفة بدقة. الجداول بتتحسب بنماذج رياضية معتمدة على قياسات لسنين في كل ميناء. والظروف الجوية كالرياح والضغط ممكن تعدل الارتفاع الفعلي شوية."], ["تأثيره على الحياة", "الكائنات على الشواطئ بتتأقلم مع المد: بعضها بيختبئ وقت الجزر وبعضها بيتغذى وقت المد. الصيادين والمواني والسفن بتتحرك على جدول المد. وفي بعض الأماكن المد بيكشف مساحات شاسعة من القاع وقت الجزر."], ["الطاقة", "فيه محاولات لتوليد كهربا من المد، بتوربينات تحت الماء أو سدود مد. الفكرة جذابة لأن المد يمكن التنبؤ به. لكن التكلفة والأثر البيئي بيحدوا من انتشارها."], ["مد اليابسة", "القمر كمان بيشد اليابسة، لكن الصخور صلبة فبتتحرك قليلا جدا، بالسنتيمترات. ده اسمه مد الأرض، وبتقيسه أجهزة حساسة."], ["أسئلة شائعة", "هل القمر بيأثر على جسم الإنسان لأن فيه مية؟ تأثير المد على كتلة صغيرة زي جسم الإنسان صغير جدا. المد بيظهر في كتل المياه الكبيرة. وفكرة إن البدر بيأثر على السلوك أو الولادات ما فيش دليل علمي قوي عليها."], ["الفرق بين المد والتيار", "المد هو ارتفاع وانخفاض منسوب البحر. التيار المدي هو حركة المية الأفقية الناتجة عنه. في بعض المضايق، التيارات المدية بتكون قوية جدا وبتأثر على الملاحة. السفن بتخطط حركتها حسب جداول التيارات، لأنها ممكن تساعد السفينة أو تعطلها."], ["الأرض والقمر يدوروا حوالين مركز مشترك", "الأرض والقمر مش القمر بيلف حوالين أرض ثابتة. الاتنين بيلفوا حوالين مركز كتلة مشترك قريب من مركز الأرض، جوه الأرض نفسها. الحركة دي مرتبطة بفكرة الانتفاخ الثاني: في الجانب البعيد، القوة الطاردة المركزية الناتجة عن الحركة بتساهم في المد. وتفسير ده الفيزيائي أدق من الشرح المبسط."], ["المد في الأماكن الضيقة", "في خلجان بتتحول مداخلها لضيقة، الموجة المدية بتتضخم. في بعض الأماكن حول العالم المد بيوصل لعدة أمتار فوق وتحت المتوسط، بينما في أماكن تانية بيكون أقل من متر. وفي بعض الأنهار بيتولد موجة مدية بتتحرك عكس التيار. الفروق دي بتعتمد على الشكل الهندسي للمكان."], ["البحر المتوسط", "في البحر المتوسط المد صغير نسبيا لأنه حوض شبه مقفول بيتصل بالمحيط بمضيق ضيق. فمفيش مجال كبير لتتحرك كمية مية كبيرة. لكن فيه أماكن ممكن يبان فيها فرق ملحوظ. وأمور زي الرياح والضغط الجوي ممكن تكون أكبر تأثيرا في المستوى اليومي من المد نفسه."], ["قناة السويس", "في قناة السويس، السفن تمر في ممر بين البحرين المتوسط والأحمر. مستوى المد بيختلف بين الطرفين، وده بيعمل تيارات في القناة. الملاحة بتاخد ده في الاعتبار. والفكرة بتورّي إن المد مش مجرد ظاهرة على الشاطئ، هو عنصر عملي في الملاحة والمواني."], ["الشواطئ والأمان", "في أماكن فيها مد وجزر ملحوظين، الناس ممكن تتخطف بالمد وتتحاصر على جزر رملية. وكتير من حوادث الغرق بتحصل بسبب تيارات الرجوع القوية. لو بتسبح أو بتمشي على الشاطئ، اتأكد من جداول المد والتحذيرات المحلية، وما تسبحش في منطقة فيها تحذير أو أعلام حمرا."], ["الجداول والتطبيقات", "جداول المد بتتحسب وتتنشر قبل أوقات طويلة، لأن حركة القمر والشمس معروفة. التطبيقات بتعرض لك أوقات المد العالي والمنخفض لمكانك. الفرق بين الجدول والواقع بيكون بسيط غالبا، وبيتأثر بالرياح والضغط. للأنشطة المهمة ارجع للمصادر الرسمية في بلدك."], ["المد في الكواكب والأقمار", "المد مش بس على الأرض. أقمار بعض الكواكب العملاقة بتتأثر بمد قوي من جاذبية كوكبها، وبيسخن باطنها. ده بيتناقش كمصدر حرارة ممكن يخلي أقمار معينة نشطة جيولوجيا. فالمد ظاهرة جاذبية عامة في الكون، مش خاصة بالأرض."], ["الخلاصة", "الخلاصة: جاذبية القمر، ومعاها جاذبية الشمس بدرجة أقل، بتخلق انتفاخين في مية المحيطات. بدوران الأرض بيعدي الشاطئ على كل انتفاخ، فتحصل مدين وجزرين تقريبا في اليوم. ويختلف المد في القوة حسب مواقع القمر والشمس وشكل الساحل، وبيتحسب مقدما بدقة."]], "f": ["جاذبية القمر هي السبب الأساسي للمد والجزر والشمس ليها تأثير أقل", "فيه تقريبا مدين وجزرين في اليوم في أغلب الأماكن", "المد العالي بيحصل في الجانب المواجه للقمر والجانب البعيد", "في القمر الجديد والبدر المد بيكون أعلى (المد الربيعي)", "الشكل الفعلي بيتأثر بشكل السواحل وعمق البحر"], "c": "علوم", "dur": "6 دقايق", "tot": 365, "st": [0, 23, 38, 57, 77, 90, 103, 114, 130, 142, 158, 171, 183, 190, 207, 223, 243, 261, 280, 298, 317, 333, 348], "w": 851}, {"n": 44, "t": "الصوت: الميكروفون والسماعة بيشتغلوا ازاي؟", "e": "Microphones and Speakers", "h": "صوتك بيتحول لكهربا في الميكروفون، وبيرجع صوت من السماعة. الاتنين بيعملوا نفس الفكرة بالعكس.", "sc": [["صوت بيسافر", "لما بتتكلم، حبالك الصوتية بتهز الهوا، فبتتكون موجات ضغط بتنتقل لودن اللي قدامك. لو عايز تسجل الصوت أو تسمعه من بعيد، لازم تحوله لشكل تاني. الميكروفون بيحوله لكهربا، والسماعة بترجعه صوت. في الفيديو ده هنفهم إزاي الأجهزة دي بتشتغل، وإزاي التسجيل الرقمي بيحفظ صوتك كأرقام."], ["الصوت موجة", "الصوت اهتزاز بينتقل في الهوا أو أي وسط. الاهتزاز بيخلق مناطق ضغط عالي وضغط منخفض، بتتحرك زي الموجة. عدد الاهتزازات في الثانية هو التردد، وبيحدد حدة الصوت. وارتفاع الضغط بيحدد علو الصوت. الإنسان بيسمع تقريبا من عشرين هرتز لعشرين ألف هرتز."], ["الميكروفون الديناميكي", "الميكروفون الديناميكي فيه غشاء رقيق متصل بملف سلك صغير، والملف موجود جنب مغناطيس. لما الصوت يهز الغشاء، الملف بيتحرك قدام المغناطيس، فبيتولد فيه تيار كهربي صغير يتغير مع الصوت. ده نفس مبدأ المولد، والإشارة الناتجة نسخة كهربية من الموجة."], ["ميكروفون المكثف", "النوع التاني اسمه المكثف. فيه صفيحتين: غشاء رقيق وصفيحة ثابتة، شغالين زي مكثف كهربي. لما الغشاء يتحرك، المسافة بين الصفيحتين بتتغير، فبتتغير السعة الكهربية. ده بينتج إشارة. النوع ده أحساس وبيحتاج طاقة، وبيستخدم في الاستوديوهات. وميكروفون الموبايل غالبا من نوع صغير مشابه."], ["ليه الإشارة ضعيفة", "الإشارة اللي بتطلع من الميكروفون صغيرة جدا. فبتعدي على مضخم يكبرها قبل ما تتسجل أو تتبعت. والتضخيم ده أساسي في كل جهاز صوتي."], ["التسجيل الرقمي", "عشان نخزن الصوت في موبايل أو كمبيوتر، لازم نحول الإشارة الكهربية المستمرة لأرقام. جهاز اسمه المحول التناظري الرقمي بيقيس قيمة الإشارة آلاف المرات في الثانية، وبيكتب كل قياس كرقم. معدل القياس اسمه معدل العينات، ومن الشائع مثلا ٤٤ ألف عينة في الثانية."], ["ليه العدد ده", "فيه قاعدة في الاتصالات بتقول إن لازم نقيس بمعدل ضعف أعلى تردد عايزين نسجله على الأقل. الإنسان بيسمع لحد حوالي عشرين ألف هرتز، فمعدل أربعين ألف عينة وأكتر كافي. عشان كده المعدلات الشائعة بتبدأ من حوالي أربعين ألف."], ["دقة القياس", "كل قياس بيتخزن بعدد معين من البتات. كل ما كان عدد البتات أكبر، الدقة أعلى وتفاصيل الصوت الهادي والعالي أحسن. بعض التسجيلات بتستخدم ست عشرة بت، وبعضها أربعة وعشرين."], ["الضغط", "الملفات الرقمية بتبقى كبيرة، فبنضغطها. فيه ضغط من غير فقد بيرجع الملف زي ما هو، وفيه ضغط بفقد زي صيغة إم بي ثري بيشيل معلومات ما بنسمعهاش بسهولة عشان يصغر الحجم. جودة الضغط بتختلف حسب معدل البيانات."], ["التشغيل والعكس", "للتشغيل، بنعكس العملية. محول رقمي تناظري بيحول الأرقام لإشارة كهربية، ومضخم بيكبرها ويوصلها للسماعة. جودة المحول والمضخم بتأثر على جودة الصوت."], ["السماعة", "السماعة الديناميكية شبه الميكروفون الديناميكي بالعكس. فيها مغناطيس وملف متصل بمخروط من ورق أو بلاستيك. لما التيار المتغير يعدي في الملف، بيتولد مجال بيتفاعل مع المغناطيس، فالملف بيتحرك لقدام ولورا، والمخروط بيهز الهوا. فبيطلع الصوت."], ["أحجام السماعات", "السماعات الصغيرة بتتفوق في الترددات العالية، والكبيرة في الترددات المنخفضة. عشان كده الأنظمة الجيدة فيها أكتر من سماعة: واحدة صغيرة للأصوات الحادة وكبيرة للباص، وبتتوزع الترددات بينهم بمرشحات."], ["سماعات الأذن", "سماعات الأذن الصغيرة بتستخدم نفس الفكرة بحجم أصغر، وبتشتغل قريب من الودن فمش محتاجة قدرة كبيرة. والأمان السمعي مهم: الصوت العالي لفترات طويلة ممكن يضر السمع."], ["السماعات اللاسلكية", "في السماعات اللاسلكية، الصوت بيتحول لأرقام، بيتضغط، وبيتبعت عن طريق بلوتوث كإشارة راديو. السماعة بتفك الضغط وتحول لإشارة وتشغلها. عملية الضغط والإرسال ممكن تضيف تأخير بسيط وتقلل الجودة بعض الشيء حسب التقنية."], ["الصدى والصدى المتأخر", "في الغرف، الصوت بيرتد من الحيطان ويتأخر عن الصوت الأصلي. لو التأخر قليل بيتحول لصدى مصاحب بيدي دفء للصوت، لو كبير بيتسمع كصدى منفصل. استوديوهات التسجيل بتتعالج بمواد بتمتص الصوت عشان تقلل الصدى والأصداء الغير مرغوبة. عشان كده الحاجات اللي بتسمعها في مكالمة في أوضة فاضية بتبان فيها رنين."], ["اتجاه الميكروفون", "الميكروفونات بتتفرق في الاتجاه اللي بتلتقط منه الصوت. فيه ميكروفون بياخد من كل الاتجاهات، وفيه ميكروفون بياخد من قدام بس وبيقلل الجانب والخلف. الميكروفون اللي بياخد من الأمام مناسب في أماكن زحمة. واختيار الميكروفون المناسب بيفرق في وضوح الصوت."], ["التغذية العكسية", "لما السماعة تكون قريبة من الميكروفون، الصوت الخارج من السماعة بيدخل الميكروفون تاني ويتضخم، وبيحصل صفير حاد. ده اسمه تغذية عكسية. بيتحل بتبعيد الميكروفون عن السماعة، أو توجيهه بعيد، أو خفض الصوت. وبعض الأجهزة فيها دايرة بتقلله تلقائيا."], ["إلغاء الصدى في المكالمات", "في مكالمة، صوت الطرف التاني بيطلع من سماعتك وممكن يدخل ميكروفونك ويرجع له. البرامج بتطرح الإشارة المعروفة من اللي دخل الميكروفون عشان تلغي الصدى. ده بيحصل في الوقت الفعلي ومن غير ما تلاحظ. وبرضه فيه تقنيات تقلل ضوضاء الخلفية."], ["تسجيل ستريو", "الستريو بيستخدم قناتين، يمين وشمال. بيدي إحساس بالمكان لأن كل ودن بتسمع إشارة مختلفة شوية. الاختلاف في التوقيت والعلو بين القناتين هو اللي بيخلي المخ يحدد مصدر الصوت. وفيه تنسيقات بتستخدم قنوات أكتر زي السينما."], ["الاستجابة الترددية", "سماعة أو ميكروفون جيد بيعيد كل الترددات بشكل متوازن. في الواقع كل جهاز ليه منحنى استجابة، بيضخم أو يضعف ترددات معينة. ده جزء من الطابع الصوتي. وفيه معدلات في التطبيقات بتتحكم في الباص والطبقات الحادة لتناسب ذوقك."], ["ملفات الصوت", "ملف غير مضغوط بيحتفظ بكل البيانات لكن حجمه كبير. الملفات المضغوطة بفقد بتشيل تفاصيل قليلة التأثير، فبتصغر. جودة الصوت بتتأثر بمعدل البيانات: كل ما كان أعلى، الجودة أقرب للأصلية. ولأغلب الناس وأغلب الأجهزة، الفرق في معدلات بيانات عالية بيكون صغير جدا."], ["حماية السمع", "التعرض لصوت عالي لفترات طويلة بيتلف خلايا شعرية صغيرة في الأذن الداخلية، والضرر دايم. قاعدة بسيطة: لو مش بتقدر تسمع اللي حواليك أو الشخص جنبك بيسمع موسيقاك من السماعة، الصوت عالي. حدد وقت الاستماع بالسماعات، وخد استراحات. السمع مش بيتعوض."], ["الخلاصة", "الخلاصة: الميكروفون بيحول اهتزاز الهوا لإشارة كهربية، والتسجيل الرقمي بيقيسها آلاف المرات في الثانية ويخزنها كأرقام. وفي التشغيل، الأرقام ترجع إشارة، والسماعة بتحركها لتهز الهوا وتعيد الصوت. نفس الفكرة بالعكس بين الميكروفون والسماعة."]], "f": ["الصوت اهتزازات في الهوا", "الميكروفون بيحول الاهتزازات لإشارة كهربية", "السماعة بتحول الإشارة الكهربية لاهتزازات في الهوا", "في السماعة الديناميكية ملف بيتحرك في مجال مغناطيسي", "التسجيل الرقمي بيقيس الإشارة آلاف المرات في الثانية"], "c": "صوت وإلكترونيات", "dur": "6 دقايق", "tot": 355, "st": [0, 19, 37, 54, 72, 81, 99, 116, 128, 144, 153, 168, 180, 191, 205, 226, 243, 259, 276, 291, 306, 324, 341], "w": 829}, {"n": 45, "t": "المترو والقطار الكهربي بيشتغل ازاي؟", "e": "How Electric Metro Trains Work", "h": "المترو مبيحرقش بنزين. بياخد كهربا من الشبكة ويحولها لحركة، ويفرمل بنظام ممكن يرجع جزء من الطاقة.", "sc": [["نقل جماعي بكهربا", "في مدينة زي القاهرة، المترو بينقل مئات الآلاف من الناس في اليوم. مفيهوش دخان عادم في الشارع، وبيمشي على قضبان من غير زحمة العربيات. وراء ده نظام هندسي: كهربا بتتوصل للقطار، موتورات بتحركه، وفرامل ونظام إشارات بيحافظ على الأمان. تعالى نفهم الأجزاء دي."], ["من أين تأتي الكهربا", "القطار الكهربي محتاج مصدر طاقة مستمر. في المترو، الكهربا بتيجي إما من قضيب ثالث موجود جنب القضبان أو من سلك علوي فوق القطار. محطات فرعية بتاخد الكهربا من الشبكة وتحولها للجهد المناسب للقطارات."], ["القضيب الثالث والسلك العلوي", "القضيب الثالث بيكون معزول جزئيا، والقطار بيلمسه بحذاء معدني بينزلق عليه. السلك العلوي بيتلمسه جهاز على سقف القطار. الاتنين بيوصلوا الكهربا، والقضبان العادية بترجع التيار للدايرة. ولا يجوز لمس القضيب الثالث أبدا لأنه خطر."], ["الموتور الكهربي", "الكهربا بتروح لموتورات تحت عربات القطار. الموتور فيه مغناطيس وملفات، والتيار بيخلق قوة بتلف المحور. المحور بيحرك العجل. الموتورات الكهربية قوية وبتدي عزم كبير من أول لحظة، وده بيخلي القطار يتسارع بشكل جيد."], ["التحكم في السرعة", "السائق بيحرك ذراع بيتحكم في كمية الطاقة اللي بتروح للموتورات. جهاز إلكتروني بيعدل التيار والتردد حسب الطلب. وفي القطارات الحديثة، التحكم يكون بالإلكترونيات، وبيسمح بسلاسة في التسارع وتوفير في الطاقة."], ["العجلة والقضيب", "عجلة حديد على قضيب حديد احتكاكها قليل نسبيا بالمقارنة بالإطار المطاط على الأسفلت. ده بيوفر طاقة في الحركة لأن مقاومة المشي قليلة. لكن بيعني كمان إن الفرملة محتاجة مسافة أطول، وإن القطار ممكن ينزلق لو القضيب مبلول."], ["شكل العجلة", "عجلة القطار مش مسطحة تماما، هي مخروطية شوية. لما القطار يميل ناحية، قطر العجلة اللي بتلمس القضيب يزيد، فبيرجع القطار لمنتصف القضيب من غير ما يحتاج توجيه. والحافة الداخلية بتمنع الخروج عن القضيب."], ["الفرامل", "فيه فرامل ميكانيكية بتضغط على العجل أو أقراص. والقطارات الكهربية الحديثة عندها فرملة كهربية: الموتور بيشتغل كمولد، فبيبطأ القطار ويولد كهربا. الكهربا دي ممكن ترجع للشبكة تستخدمها قطارات تانية قريبة، أو تتحول لحرارة في مقاومات."], ["الإشارات", "القطارات بتمشي على نفس الخطوط، ولازم يفضل بينها مسافة آمنة. الخط بيتقسم لأقسام. نظام الإشارات بيعرف لو في قطار في القسم، وبيمنع دخول قطار تاني. وفي الأنظمة الحديثة، الحاسوب بيتحكم في السرعة المسموحة ويفرمل القطار تلقائيا لو السائق تجاوز."], ["أنظمة الأمان", "في المترو أنظمة أمان بتمنع تحرك القطار والأبواب مفتوحة، وبتتأكد من قفل الأبواب. وفيه نظام يقف القطار لو السائق ما استجابش. وعند المحطات، أبواب الرصيف في بعض الخطوط بتمنع السقوط."], ["المحطات والتهوية", "المحطات تحت الأرض محتاجة تهوية لإزالة الحرارة والهوا القديم. القطار وهو يمشي بيدفع الهوا في النفق، فبيحصل تيار هوا في المحطة. وفيه مراوح وأنظمة لإدارة الدخان في الطوارئ."], ["إدارة الشبكة", "الخطوط في المدن بتتصمم بحيث القطارات تيجي بتردد كبير، كل كام دقيقة. التحكم في توقيتها بيتم من مركز عمليات بيراقب الشبكة كلها، وبيعدل الجداول لو في تأخير."], ["توفير الطاقة", "القطار الكهربي بيستخدم طاقة أقل بالنسبة للراكب مقارنة بالسيارات الخاصة، خصوصا مع الازدحام. ومع الفرملة الاسترجاعية وتصميم خفيف، بيتحسن أكتر. كمان الكهربا لو مصدرها متجدد، البصمة الكربونية بتقل."], ["الصيانة", "القضبان والعجل والموتورات والإشارات بتتفحص باستمرار. فيه ورش بتتم فيها الصيانة في الليل. الصيانة الجيدة هي اللي بتخلي النظام آمن ومنتظم."], ["الاستخدام الآمن", "في المحطة، ابتعد عن حافة الرصيف، واتبع الخط الأصفر، ولا تحاول تنزل على القضبان. القضيب الثالث بجهد عالي خطر جدا. وسيب الناس تنزل قبل ما تركب."], ["السرعات والمسافات بين المحطات", "في المترو المسافات بين المحطات قصيرة، فالقطار بيتسارع بسرعة ويفرمل بسرعة. عشان كده التسارع العالي والفرامل القوية مهمين. الموتورات الكهربية مناسبة لأنها بتدي عزم عالي من أول لحظة. السرعة القصوى للمترو أقل من القطارات بين المدن، لأن مفيش مجال لسرعة عالية في مسافات قصيرة."], ["القطارات بين المدن", "القطارات بين المدن بتتحرك بسرعات أعلى على مسافات طويلة. بعضها كهربي بسلك علوي، وبعضها ديزل كهربي: محرك ديزل بيولد كهربا لموتورات العجل. القطارات فائقة السرعة بتحتاج خطوط خاصة مستقيمة تقريبا ونظام إشارات متطور."], ["القطار المعلق", "فيه قطارات بتستخدم قوى مغناطيسية لرفع القطار ودفعه فوق مسار من غير تلامس مع العجل. بتقلل الاحتكاك وبتوصل لسرعات عالية جدا. لكن البنية التحتية غالية، وعدد الخطوط التجارية في العالم قليل. هي مثال لفكرة هندسية مختلفة عن القطار التقليدي."], ["التعامل مع الأحمال", "في أوقات الذروة، القطار بيتحمل ركاب كتير فبيزيد وزنه. الموتورات والفرامل بتتصمم للتعامل مع الحمل الأقصى. ودرجة الازدحام بتأثر على زمن الوقوف في المحطات، وبالتالي على انتظام الخط كله. إدارة الأحمال جزء من تشغيل شبكة المترو."], ["الأنفاق والحفر", "المترو تحت الأرض بيتبني بآلات حفر ضخمة بتحفر النفق وتركب بطانة خرسانية حواليه في نفس الوقت. العمل بيتم بحذر عشان ما يأثرش على المباني فوق. وفي مدن زي القاهرة، التربة والمياه الجوفية والآثار بتحتاج دراسات دقيقة قبل الحفر."], ["الكهربا للمحطات والتكييف", "المترو مش القطارات بس. المحطات فيها إضاءة وسلالم متحركة وتكييف وتهوية وبوابات إلكترونية، وكلها محتاجة كهربا. نظام التحصيل بالتذاكر أو الكروت بيشتغل بتقنيات إلكترونية، منها بطاقات لاتلامسية. فالنظام كله شبكة طاقة وبيانات."], ["الاتصالات والتحكم", "مركز التحكم بيتواصل مع السائقين وبيتابع مواقع القطارات على شاشات. فيه نظام اتصالات لاسلكي بين القطار والمركز، وكاميرات في المحطات. في بعض الأنظمة الحديثة، القطارات بتتحرك آليا بإشراف بشري، وده بيقلل التأخير ويحسن الانتظام."], ["الفرق في تجربة الراكب", "المترو بيوفر وقت في الزحمة، لأنه مش بيتأثر بالمرور. تذكرته غالبا أرخص من الأجرة الخاصة. وبيقلل الحاجة لمواقف سيارات وبيقلل التلوث في الشارع. لكن النجاح بيحتاج تغطية جيدة وتكرار مناسب وأمان وصيانة، وده بيعتمد على الاستثمار والتشغيل."], ["الخلاصة", "الخلاصة: كهربا من الشبكة توصل للقطار بقضيب أو سلك، موتورات كهربية بتحرك العجل، عجلات حديد على قضبان بتوفر طاقة، فرامل ميكانيكية وكهربية بتبطأ وممكن ترجع طاقة، ونظام إشارات وأمان بيحافظ على المسافة والتحكم. نقل جماعي بكفاءة، مبني على قواعد فيزيائية وهندسية واضحة."]], "f": ["المترو بياخد الكهربا من قضيب ثالث أو سلك علوي", "الموتور الكهربي بيحول الكهربا لحركة دوران", "القطارات بتفرمل بفرامل ميكانيكية وممكن فرملة كهربية بتسترجع الطاقة", "العجلة الحديد على قضيب حديد احتكاكها قليل فبتحتاج مسافة فرملة أطول", "أنظمة الإشارات بتمنع تصادم القطارات"], "c": "مواصلات", "dur": "6 دقايق", "tot": 348, "st": [0, 18, 33, 47, 61, 74, 90, 104, 119, 136, 149, 161, 172, 184, 193, 204, 223, 237, 254, 270, 286, 300, 314, 330], "w": 812}];
